import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL || '';
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY || '';

// If keys are missing, we will fallback to localStorage in the service layer
export const supabase = (supabaseUrl && supabaseAnonKey) 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';

const getLocalRecords = (): DailyRecord[] => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

const setLocalRecords = (records: DailyRecord[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
};

// Simulate async delay for realism
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    if (supabase) {
      const { data, error } = await supabase.from('daily_records').select('*').order('date', { ascending: false });
      if (!error && data) return data as DailyRecord[];
    }
    // Fallback
    await delay(300);
    return getLocalRecords().sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at'>): Promise<DailyRecord> {
    const newRecord: DailyRecord = {
      ...record,
      id: crypto.randomUUID(),
      created_at: new Date().toISOString(),
    };

    if (supabase) {
      const { data, error } = await supabase.from('daily_records').insert(newRecord).select().single();
      if (!error && data) return data as DailyRecord;
    }

    // Fallback
    await delay(500);
    const records = getLocalRecords();
    records.push(newRecord);
    setLocalRecords(records);
    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    if (supabase) {
      const { data, error } = await supabase.from('daily_records').update(updates).eq('id', id).select().single();
      if (!error && data) return data as DailyRecord;
    }

    // Fallback
    await delay(300);
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
        if (data) return data as DailyRecord;
    }
    await delay(200);
    return getLocalRecords().find(r => r.id === id);
  }
};

import { GoogleGenAI } from "@google/genai";
import { DailyRecord } from "../types";

const apiKey = process.env.API_KEY || ''; 
// NOTE: In a real PWA, you'd proxy this through a backend or use strict controls. 
// For this demo, we assume the environment variable is available.

const ai = new GoogleGenAI({ apiKey });

// Helper to format records for context
const formatContext = (records: DailyRecord[]) => {
  if (records.length === 0) return "No records available yet.";
  return JSON.stringify(records.slice(0, 10).map(r => ({
    date: r.date,
    team: r.team,
    km_total: r.km_total,
    delivered: r.articles_delivered,
    not_delivered: r.articles_not_delivered,
    fuel: r.fuel_amount,
    notes: r.notes
  })));
};

export const geminiService = {
  // Chatbot using Gemini 3 Pro for reasoning
  async chatWithBot(message: string, records: DailyRecord[]) {
    if (!apiKey) return "API Key not configured.";

    const context = formatContext(records);
    const systemInstruction = `You are a helpful assistant for the SNavegar delivery app. 
    You have access to the following recent delivery records: ${context}.
    Answer questions about delivery performance, issues, or general help. Keep answers concise.`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: message,
        config: {
          systemInstruction,
        }
      });
      return response.text || "I couldn't generate a response.";
    } catch (error) {
      console.error("Gemini Chat Error:", error);
      return "Sorry, I'm having trouble connecting to the AI service right now.";
    }
  },

  // Fast responses using Gemini Flash Lite
  async getQuickInsight(records: DailyRecord[]) {
    if (!apiKey) return "API Key missing.";

    const context = formatContext(records);

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-flash-lite-latest', // Alias for 2.5 flash lite
        contents: `Analyze these delivery records and give me ONE short, motivating sentence about performance or a quick tip based on the data: ${context}`,
      });
      return response.text || "Keep up the good work!";
    } catch (error) {
      console.error("Gemini Flash Lite Error:", error);
      return "Ready for a new day!";
    }
  }
};

