const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [records, setRecords] = useState<DailyRecord[]>([]);

  // On mount, check if already logged in (mock)
  useEffect(() => {
    const loggedIn = localStorage.getItem('snavegar_auth');
    if (loggedIn) setIsAuthenticated(true);
  }, []);

  // Fetch records for ChatBot context whenever auth changes
  useEffect(() => {
    if (isAuthenticated) {
        recordService.getAll().then(setRecords);
    }
  }, [isAuthenticated]);

  const handleLogin = () => {
    localStorage.setItem('snavegar_auth', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('snavegar_auth');
    setIsAuthenticated(false);
  };

  return (
    <HashRouter>
      <Routes>
        <Route 
          path="/login" 
          element={!isAuthenticated ? <Login onLogin={handleLogin} /> : <Navigate to="/" />} 
        />

        <Route
          path="/*"
          element={
            isAuthenticated ? (
              <Layout onLogout={handleLogout}>
                <Routes>
                  <Route path="/" element={<Home />} />
                  <Route path="/create" element={<RecordForm />} />
                  <Route path="/records" element={<RecordList />} />
                  <Route path="/records/:id" element={<RecordDetail />} />
                  <Route path="/records/:id/edit" element={<RecordForm />} />
                  <Route path="/analytics" element={<Analytics />} />
                  <Route path="*" element={<Navigate to="/" />} />
                </Routes>
                {/* Global ChatBot available on all protected routes */}
                <ChatBot records={records} />
              </Layout>
            ) : (
              <Navigate to="/login" />
            )
          }
        />
      </Routes>
    </HashRouter>
  );
};

export default App;

