import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Truck, Loader2 } from 'lucide-react';
import { supabase } from '../services/supabaseClient';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) {
        setError("Supabase not configured. Check environment variables.");
        return;
    }

    setLoading(true);
    setError('');
    setMessage('');

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email,
          password,
        });
        if (error) throw error;
        setMessage('Account created! You can now log in.');
        setIsSignUp(false);
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (error) throw error;
        onLogin();
        navigate('/');
      }
    } catch (err: any) {
      setError(err.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-sm">
        <div className="flex flex-col items-center mb-8">
          <div className="bg-blue-100 p-4 rounded-full mb-4 text-primary">
            <Truck size={40} />
          </div>
          <h1 className="text-2xl font-bold text-gray-900">SNavegar</h1>
          <p className="text-gray-500 text-sm mt-1">Daily Delivery Operations</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all"
              placeholder="team@snavegar.com"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all"
              placeholder="••••••••"
              required
            />
          </div>

          {error && <p className="text-red-500 text-sm text-center bg-red-50 p-2 rounded">{error}</p>}
          {message && <p className="text-green-600 text-sm text-center bg-green-50 p-2 rounded">{message}</p>}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primary text-white py-3 rounded-lg font-semibold shadow-md hover:bg-blue-700 transition-colors flex items-center justify-center"
          >
            {loading ? <Loader2 className="animate-spin" /> : (isSignUp ? 'Create Account' : 'Login')}
          </button>
        </form>

        <div className="mt-6 text-center">
            <button 
                onClick={() => { setIsSignUp(!isSignUp); setError(''); setMessage(''); }}
                className="text-sm text-primary hover:underline"
            >
                {isSignUp ? 'Already have an account? Login' : 'Need an account? Sign Up'}
            </button>
        </div>

        <p className="text-center text-xs text-gray-400 mt-6">
          © {new Date().getFullYear()} SNavegar Operations
        </p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import ChatBot from './components/ChatBot';
import Login from './pages/Login';
import Home from './pages/Home';
import RecordForm from './pages/RecordForm';
import RecordList from './pages/RecordList';
import RecordDetail from './pages/RecordDetail';
import Analytics from './pages/Analytics';
import { DailyRecord } from './types';
import { recordService } from './services/recordService';
import { supabase } from './services/supabaseClient';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [records, setRecords] = useState<DailyRecord[]>([]);

  useEffect(() => {
    // Check active session
    const checkSession = async () => {
        if (supabase) {
            const { data: { session } } = await supabase.auth.getSession();
            setIsAuthenticated(!!session);
        } else {
             // Fallback for demo without Supabase keys
             const localAuth = localStorage.getItem('snavegar_auth');
             if (localAuth) setIsAuthenticated(true);
        }
        setLoading(false);
    };

    checkSession();

    // Listen for auth changes
    const { data: authListener } = supabase?.auth.onAuthStateChange((_event, session) => {
        setIsAuthenticated(!!session);
    }) || { data: { subscription: { unsubscribe: () => {} } } };

    return () => {
        authListener.subscription.unsubscribe();
    };
  }, []);

  // Fetch records for ChatBot context whenever auth changes
  useEffect(() => {
    if (isAuthenticated) {
        recordService.getAll().then(setRecords);
    }
  }, [isAuthenticated]);

  const handleLogin = () => {
    // handled by supabase listener usually, but kept for local fallback
    setIsAuthenticated(true);
  };

  const handleLogout = async () => {
    if (supabase) {
        await supabase.auth.signOut();
    } else {
        localStorage.removeItem('snavegar_auth');
    }
    setIsAuthenticated(false);
  };

  if (loading) {
      return <div className="min-h-screen flex items-center justify-center bg-gray-50 text-primary">Loading...</div>;
  }

  return (
    <HashRouter>
      <Routes>
        <Route 
          path="/login" 
          element={!isAuthenticated ? <Login onLogin={handleLogin} /> : <Navigate to="/" />} 
        />

        <Route
          path="/*"
          element={
            isAuthenticated ? (
              <Layout onLogout={handleLogout}>
                <Routes>
                  <Route path="/" element={<Home />} />
                  <Route path="/create" element={<RecordForm />} />
                  <Route path="/records" element={<RecordList />} />
                  <Route path="/records/:id" element={<RecordDetail />} />
                  <Route path="/records/:id/edit" element={<RecordForm />} />
                  <Route path="/analytics" element={<Analytics />} />
                  <Route path="*" element={<Navigate to="/" />} />
                </Routes>
                {/* Global ChatBot available on all protected routes */}
                <ChatBot records={records} />
              </Layout>
            ) : (
              <Navigate to="/login" />
            )
          }
        />
      </Routes>
    </HashRouter>
  );
};

export default App;

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';

const getLocalRecords = (): DailyRecord[] => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

const setLocalRecords = (records: DailyRecord[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
};

// Simulate async delay for realism
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    if (supabase) {
      const { data, error } = await supabase
        .from('daily_records')
        .select('*')
        .order('date', { ascending: false });

      if (!error && data) return data as DailyRecord[];
      if (error) console.error("Error fetching records:", error);
    }

    // Fallback if no supabase or error
    if (!supabase) {
        await delay(300);
        return getLocalRecords().sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }
    return [];
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at'>): Promise<DailyRecord> {
    const newRecordBase = {
      ...record,
      id: crypto.randomUUID(),
      created_at: new Date().toISOString(),
    };

    if (supabase) {
      // Get current user to attach to record
      const { data: { user } } = await supabase.auth.getUser();

      const payload = {
          ...newRecordBase,
          user_id: user?.id
      };

      const { data, error } = await supabase.from('daily_records').insert(payload).select().single();
      if (!error && data) return data as DailyRecord;
      if (error) {
          console.error("Error creating record:", error);
          throw error;
      }
    }

    // Fallback
    await delay(500);
    const records = getLocalRecords();
    records.push(newRecordBase);
    setLocalRecords(records);
    return newRecordBase;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    if (supabase) {
      const { data, error } = await supabase.from('daily_records').update(updates).eq('id', id).select().single();
      if (!error && data) return data as DailyRecord;
      if (error) console.error("Error updating record:", error);
    }

    // Fallback
    await delay(300);
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
        if (!error && data) return data as DailyRecord;
    }
    await delay(200);
    return getLocalRecords().find(r => r.id === id);
  }
};

