import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Save, CheckCircle, Camera, UploadCloud, X } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

const RecordForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams(); // If ID exists, we are editing
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState<Partial<DailyRecord>>({
    date: new Date().toISOString().split('T')[0],
    team: '',
    van_plate: '',
    start_time: '08:00',
    km_start: 0,
    km_end: 0,
    km_total: 0,
    articles_loaded: 0,
    articles_delivered: 0,
    articles_not_delivered: 0,
    reason_not_delivered: '',
    fueling: false,
    fuel_amount: 0,
    toll_amount: 0,
    attachments: [],
    notes: '',
    status: 'draft'
  });

  useEffect(() => {
    if (id) {
      const loadRecord = async () => {
        const record = await recordService.getById(id);
        if (record) setFormData(record);
      };
      loadRecord();
    }
  }, [id]);

  // Auto-calculate total KM
  useEffect(() => {
    const start = Number(formData.km_start) || 0;
    const end = Number(formData.km_end) || 0;
    if (end >= start) {
      setFormData(prev => ({ ...prev, km_total: end - start }));
    }
  }, [formData.km_start, formData.km_end]);

  // Auto-calculate delivered/not delivered balance (optional helper)
  // We won't force it, but let the user input freely as per requirements.

  const handleChange = (field: keyof DailyRecord, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setFormData(prev => ({
            ...prev,
            attachments: [...(prev.attachments || []), reader.result as string]
          }));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const removeAttachment = (index: number) => {
    setFormData(prev => ({
        ...prev,
        attachments: prev.attachments?.filter((_, i) => i !== index)
    }));
  };

  const handleSubmit = async (status: 'draft' | 'finalized') => {
    if (!formData.team || !formData.van_plate) {
        alert("Please fill in Team and Van Plate.");
        return;
    }

    setLoading(true);
    const dataToSave = { ...formData, status } as DailyRecord; // Cast for simplicity in demo

    try {
        if (id) {
            await recordService.update(id, dataToSave);
        } else {
            await recordService.create(dataToSave);
        }
        navigate('/');
    } catch (error) {
        console.error(error);
        alert("Error saving record.");
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="pb-10">
      <h2 className="text-2xl font-bold mb-6 text-gray-800">{id ? 'Edit Record' : 'New Daily Record'}</h2>

      <div className="space-y-6">
        {/* Section 1: General */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold text-primary mb-4 border-b pb-2">General Info</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-gray-600 mb-1">Date</label>
              <input type="date" className="input-field" value={formData.date} onChange={e => handleChange('date', e.target.value)} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Start Time</label>
              <input type="time" className="input-field" value={formData.start_time} onChange={e => handleChange('start_time', e.target.value)} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Team Name</label>
              <input type="text" placeholder="e.g. Mario & Luigi" className="input-field" value={formData.team} onChange={e => handleChange('team', e.target.value)} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Van Plate</label>
              <input type="text" placeholder="AA-00-BB" className="input-field uppercase" value={formData.van_plate} onChange={e => handleChange('van_plate', e.target.value)} />
            </div>
          </div>
