        </div>
      ) : (
        <div className="grid gap-4">
          {filteredRecords.map(record => (
            <div 
              key={record.id}
              onClick={() => navigate(`/records/${record.id}`)}
              className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center group"
            >
              <div>
                <div className="flex items-center space-x-3 mb-2">
                    <div className="bg-blue-50 text-primary px-2 py-1 rounded text-xs font-bold uppercase tracking-wide">
                        {new Date(record.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
