export default RecordList;

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Bot, User } from 'lucide-react';
import { geminiService } from '../services/geminiService';
import { DailyRecord } from '../types';

interface ChatBotProps {
  records: DailyRecord[];
}

const ChatBot: React.FC<ChatBotProps> = ({ records }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [message, setMessage] = useState('');
  const [history, setHistory] = useState<{ sender: 'user' | 'bot'; text: string }[]>([
    { sender: 'bot', text: 'Hi! I can help you analyze your delivery data. Ask me anything!' }
  ]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history, isOpen]);

  const handleSend = async () => {
    if (!message.trim()) return;

    const userMsg = message;
    setMessage('');
    setHistory(prev => [...prev, { sender: 'user', text: userMsg }]);
    setLoading(true);

    const response = await geminiService.chatWithBot(userMsg, records);

    setHistory(prev => [...prev, { sender: 'bot', text: response }]);
    setLoading(false);
  };

  return (
    <>
      {/* Floating Trigger */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-20 md:bottom-8 right-4 md:right-8 bg-primary text-white p-3 rounded-full shadow-lg hover:bg-blue-700 transition-all z-40 ${isOpen ? 'hidden' : 'flex'}`}
        aria-label="Open Chat"
      >
        <MessageSquare size={24} />
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-0 right-0 md:bottom-24 md:right-8 w-full md:w-96 h-[80vh] md:h-[600px] bg-white shadow-2xl rounded-t-2xl md:rounded-2xl flex flex-col z-50 overflow-hidden border border-gray-200">
          {/* Header */}
          <div className="bg-primary p-4 text-white flex justify-between items-center shadow-md">
            <div className="flex items-center space-x-2">
              <Bot size={20} />
              <span className="font-semibold">AI Assistant</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-blue-600 p-1 rounded">
              <X size={20} />
            </button>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50" ref={scrollRef}>
            {history.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] p-3 rounded-lg text-sm ${
                    msg.sender === 'user'
                      ? 'bg-primary text-white rounded-br-none'
                      : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {loading && (
               <div className="flex justify-start">
                <div className="bg-gray-200 text-gray-500 text-xs px-3 py-2 rounded-lg animate-pulse">
                  Thinking...
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-3 bg-white border-t flex items-center space-x-2">
            <input
              type="text"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask about deliveries..."
              className="flex-1 border border-gray-300 rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-gray-900"
            />
            <button
              onClick={handleSend}
              disabled={loading || !message.trim()}
              className="bg-primary text-white p-2 rounded-full hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </>
  );
};

export default ChatBot;

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Save, CheckCircle, Camera, UploadCloud, X } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

const TEAMS = [
  "Equipe 1 - Luiz e Luigi",
  "Equipe 2 - David e Ruben"
];

const RecordForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams(); // If ID exists, we are editing
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState<Partial<DailyRecord>>({
    date: new Date().toISOString().split('T')[0],
    team: '',
    van_plate: '',
    start_time: '08:00',
    km_start: 0,
    km_end: 0,
    km_total: 0,
    articles_loaded: 0,
    articles_delivered: 0,
    articles_not_delivered: 0,
    reason_not_delivered: '',
    fueling: false,
    fuel_amount: 0,
    toll_amount: 0,
    attachments: [],
    notes: '',
    status: 'draft'
  });

  useEffect(() => {
    if (id) {
      const loadRecord = async () => {
        const record = await recordService.getById(id);
        if (record) setFormData(record);
      };
      loadRecord();
    }
  }, [id]);

  // Auto-calculate total KM
  useEffect(() => {
    const start = Number(formData.km_start) || 0;
    const end = Number(formData.km_end) || 0;
    if (end >= start) {
      setFormData(prev => ({ ...prev, km_total: end - start }));
    }
  }, [formData.km_start, formData.km_end]);

  const handleChange = (field: keyof DailyRecord, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          setFormData(prev => ({
            ...prev,
            attachments: [...(prev.attachments || []), reader.result as string]
          }));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const removeAttachment = (index: number) => {
    setFormData(prev => ({
        ...prev,
        attachments: prev.attachments?.filter((_, i) => i !== index)
    }));
  };

  const handleSubmit = async (status: 'draft' | 'finalized') => {
    if (!formData.team || !formData.van_plate) {
        alert("Please select a Team and fill in Van Plate.");
        return;
    }

    setLoading(true);
    const dataToSave = { ...formData, status } as DailyRecord; // Cast for simplicity in demo

    try {
        if (id) {
            await recordService.update(id, dataToSave);
        } else {
            await recordService.create(dataToSave);
        }
        navigate('/');
    } catch (error) {
        console.error(error);
        alert("Error saving record.");
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="pb-10">
      <h2 className="text-2xl font-bold mb-6 text-gray-800">{id ? 'Edit Record' : 'New Daily Record'}</h2>

      <div className="space-y-6">
        {/* Section 1: General */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold text-primary mb-4 border-b pb-2">General Info</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-gray-600 mb-1">Date</label>
              <input type="date" className="input-field" value={formData.date} onChange={e => handleChange('date', e.target.value)} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Start Time</label>
              <input type="time" className="input-field" value={formData.start_time} onChange={e => handleChange('start_time', e.target.value)} />
            </div>
