    // Critical: Stop the click from bubbling up to the card div (which navigates to details)
    e.preventDefault(); 
    e.stopPropagation(); 

    setErrorMsg('');
    const willArchive = !record.archived;

    // Optimistic Update: Update UI immediately
    setRecords(prevRecords => prevRecords.map(r => {
        if (r.id === record.id) {
            return { ...r, archived: willArchive };
        }
        return r;
    }));

