                    </div>
                    <span className={`font-bold ${record.archived ? 'text-gray-500' : 'text-gray-900'}`}>{record.team}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full ${record.status === 'finalized' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                        {record.status}
