import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';

const getLocalRecords = (): DailyRecord[] => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

const setLocalRecords = (records: DailyRecord[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
};

// Simulate async delay for realism
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    if (supabase) {
      const { data, error } = await supabase
        .from('daily_records')
        .select('*')
        .order('date', { ascending: false });

      if (!error && data) {
        const serverRecords = data as DailyRecord[];
        const localRecords = getLocalRecords();

        // Merge strategy: Preserve local 'archived' state if server schema doesn't support it yet
        // This prevents overwriting local changes when the DB is missing the column
        const mergedRecords = serverRecords.map(r => {
            const local = localRecords.find(l => l.id === r.id);
            // Check if 'archived' is missing from server response (undefined)
            const serverHasArchived = 'archived' in r;

            // If server has it, use it. If not, fallback to local, then default to false.
            const archived = serverHasArchived ? r.archived : (local?.archived || false);

            return { ...r, archived };
        });

        setLocalRecords(mergedRecords);
        return mergedRecords;
      }

      // If error, log it and fall through to local storage
      if (error) console.error("Error fetching records (falling back to local):", error);
    }

    // Fallback (runs if supabase is missing OR if it errored)
    await delay(300);
    return getLocalRecords().sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newRecordBase = {
      ...record,
      id: crypto.randomUUID(),
      archived: false,
      created_at: new Date().toISOString(),
    } as DailyRecord;

    if (supabase) {
      const { data: { user } } = await supabase.auth.getUser();
      const payload = { ...newRecordBase, user_id: user?.id };

      // Attempt insert. If 'archived' column is missing in DB, this might fail or ignore it depending on API strictness.
      const { data, error } = await supabase.from('daily_records').insert(payload).select().single();

      if (!error && data) {
        // Also update local cache with the new record
        const currentLocal = getLocalRecords();
        currentLocal.push(data as DailyRecord);
        setLocalRecords(currentLocal);
        return data as DailyRecord;
      }

      if (error) {
          // Check for schema error on create as well
          const isSchemaError = error.code === 'PGRST204' || error.message?.includes("column"); // Broad check for column errors
          if (isSchemaError) {
             console.warn("Schema mismatch on create (likely missing column), falling back to local storage.");
          } else {
             console.error("Error creating record (falling back to local):", error);
          }
          // Fall through to local storage
      }
    }

    // Fallback
    await delay(500);
    const records = getLocalRecords();
    records.push(newRecordBase);
    setLocalRecords(records);
    return newRecordBase;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let supabaseError = null;

    if (supabase) {
      const { data, error } = await supabase.from('daily_records').update(updates).eq('id', id).select().single();

      if (!error && data) {
         // Update local cache as well to keep in sync
         const records = getLocalRecords();
         const index = records.findIndex(r => r.id === id);
         if (index !== -1) {
            records[index] = { ...records[index], ...data };
            setLocalRecords(records);
         }
         return data as DailyRecord;
      }

      if (error) {
        // Handle Schema Mismatch (Missing Column) gracefully
        // PGRST204: Could not find the 'archived' column...
        const isSchemaError = error.code === 'PGRST204' || error.message?.includes("Could not find the 'archived' column");

        if (isSchemaError) {
             console.warn("Supabase schema missing 'archived' column. Using local-only update for this field.");
             // We do NOT set supabaseError, so we don't throw later. 
             // We just proceed to update local storage.
        } else {
             console.error("Error updating record in Supabase:", JSON.stringify(error));
             supabaseError = error;
        }
      }
    }

    // Fallback for local-only records OR failed server updates
    await delay(300);
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }

    // If not found locally AND we had a supabase error, then it's a real failure.
    if (supabaseError) {
        throw supabaseError;
    }

    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
        if (!error && data) {
            // Merge logic for single record get
            const localRecords = getLocalRecords();
            const local = localRecords.find(l => l.id === id);
            const serverHasArchived = 'archived' in data;
            const archived = serverHasArchived ? data.archived : (local?.archived || false);
            return { ...data, archived } as DailyRecord;
        }
    }
    await delay(200);
    return getLocalRecords().find(r => r.id === id);
  }
};

