            // Nota: Se for um registro 'localOnly', r.archived já estará correto vindo do objeto r.
            const archived = serverHasArchived ? r.archived : (local?.archived || (r as any).archived || false);

            return { ...r, archived };
        });

        // Reordenar por data (garante que o novo registro apareça no topo se for recente)
        mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

