  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let supabaseError = null;

    if (supabase) {
      const { data, error } = await supabase.from('daily_records').update(updates).eq('id', id).select().single();

      if (!error && data) {
         const records = getLocalRecords();
         const index = records.findIndex(r => r.id === id);
         if (index !== -1) {
            records[index] = { ...records[index], ...data };
            setLocalRecords(records);
         }
         return data as DailyRecord;
      }

      if (error) {
        const isSchemaError = error.code === 'PGRST204' || error.message?.includes("Could not find the 'archived' column");

        if (isSchemaError) {
             console.warn("Supabase schema missing 'archived' column. Using local-only update for this field.");
        } else {
             console.error("Error updating record in Supabase:", JSON.stringify(error));
             supabaseError = error;
        }
      }
    }

    // Fallback
    await delay(300);
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }

    if (supabaseError) throw supabaseError;
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
        if (!error && data) {
            const localRecords = getLocalRecords();
            const local = localRecords.find(l => l.id === id);
            const serverHasArchived = 'archived' in data;
            const archived = serverHasArchived ? data.archived : (local?.archived || false);
            return { ...data, archived } as DailyRecord;
        }
    }
    await delay(200);
    return getLocalRecords().find(r => r.id === id);
  }
};

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';

const getLocalRecords = (): DailyRecord[] => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

const setLocalRecords = (records: DailyRecord[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
};

// Simulate async delay ONLY for offline actions
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper robusto para gerar UUIDs
const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    if (supabase) {
      const { data, error } = await supabase
        .from('daily_records')
        .select('*')
        .order('date', { ascending: false });

      if (!error && data) {
        const serverRecords = data as DailyRecord[];
        const localRecords = getLocalRecords();

        // FIX: Identificar registros que existem localmente mas NÃO estão no servidor
        const localOnlyRecords = localRecords.filter(local => 
            !serverRecords.some(server => server.id === local.id)
        );

        const combinedRecords = [...serverRecords, ...localOnlyRecords];

        const mergedRecords = combinedRecords.map(r => {
            const local = localRecords.find(l => l.id === r.id);
            const serverHasArchived = 'archived' in r;
            const archived = serverHasArchived ? r.archived : (local?.archived || (r as any).archived || false);
            return { ...r, archived };
        });

        mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        setLocalRecords(mergedRecords);
        return mergedRecords;
      }

      if (error) {
        console.error("SUPABASE FETCH ERROR:", error.message, error.details);
      }
    }

    // Fallback completo
    await delay(300);
    return getLocalRecords().sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newRecordBase = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
    } as DailyRecord;

    if (supabase) {
      const { data: { user } } = await supabase.auth.getUser();
      // Garante que o ID do usuário vá para o banco (necessário para as políticas de segurança RLS)
      const payload = { ...newRecordBase, user_id: user?.id };

      const { data, error } = await supabase.from('daily_records').insert(payload).select().single();

      if (!error && data) {
        console.log("Record saved to Supabase successfully:", data.id);
        const currentLocal = getLocalRecords();
        currentLocal.push(data as DailyRecord);
        setLocalRecords(currentLocal);
        return data as DailyRecord;
      }

      if (error) {
          console.error("SUPABASE CREATE ERROR:", error.message, error.details || error.hint);

          const isSchemaError = error.code === 'PGRST204' || error.message?.includes("column") || error.code === '42P01'; // 42P01 is "undefined table"
          if (isSchemaError) {
             console.warn("Table or Column missing in Supabase. Falling back to local storage.");
          }
      }
    }

    // Fallback
    await delay(500);
    const records = getLocalRecords();
    records.push(newRecordBase);
    setLocalRecords(records);
    return newRecordBase;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let supabaseError = null;

    if (supabase) {
      const { data, error } = await supabase.from('daily_records').update(updates).eq('id', id).select().single();

      if (!error && data) {
         console.log("Record updated in Supabase:", id);
         const records = getLocalRecords();
         const index = records.findIndex(r => r.id === id);
         if (index !== -1) {
            records[index] = { ...records[index], ...data };
            setLocalRecords(records);
         }
         return data as DailyRecord;
      }

      if (error) {
        console.error("SUPABASE UPDATE ERROR:", error.message);
        const isSchemaError = error.code === 'PGRST204' || error.message?.includes("column");

        if (isSchemaError) {
             console.warn("Supabase schema mismatch. Using local-only update.");
        } else {
             supabaseError = error;
        }
      }
    }

    // Fallback
    await delay(300);
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }

    if (supabaseError) throw supabaseError;
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
        if (!error && data) {
            const localRecords = getLocalRecords();
            const local = localRecords.find(l => l.id === id);
            const serverHasArchived = 'archived' in data;
            const archived = serverHasArchived ? data.archived : (local?.archived || false);
            return { ...data, archived } as DailyRecord;
        }
    }
    await delay(200);
    return getLocalRecords().find(r => r.id === id);
  }
};

import { GoogleGenAI } from "@google/genai";
import { DailyRecord } from "../types";

const apiKey = process.env.API_KEY || ''; 

const ai = new GoogleGenAI({ apiKey });

// Helper function to crunch the numbers before sending to AI
// This ensures the AI doesn't have to do math on raw text, which reduces hallucinations.
const generateAnalysisContext = (records: DailyRecord[]) => {
  if (records.length === 0) return "No records available database is empty.";

  // 1. Calculate Global Totals
  const totalKm = records.reduce((sum, r) => sum + (Number(r.km_total) || 0), 0);
  const totalFuel = records.reduce((sum, r) => sum + (Number(r.fuel_amount) || 0), 0);
  const totalTolls = records.reduce((sum, r) => sum + (Number(r.toll_amount) || 0), 0);
  const totalDelivered = records.reduce((sum, r) => sum + (Number(r.articles_delivered) || 0), 0);
  const totalFailed = records.reduce((sum, r) => sum + (Number(r.articles_not_delivered) || 0), 0);
  const totalRecords = records.length;

  // 2. Calculate Stats per Team
  const teamStats: Record<string, { km: number, delivered: number, failed: number, cost: number, days: number }> = {};

  records.forEach(r => {
    const team = r.team || "Unknown Team";
    if (!teamStats[team]) {
        teamStats[team] = { km: 0, delivered: 0, failed: 0, cost: 0, days: 0 };
    }
    teamStats[team].km += (Number(r.km_total) || 0);
    teamStats[team].delivered += (Number(r.articles_delivered) || 0);
    teamStats[team].failed += (Number(r.articles_not_delivered) || 0);
    teamStats[team].cost += (Number(r.fuel_amount) || 0) + (Number(r.toll_amount) || 0);
    teamStats[team].days += 1;
  });

  // 3. Format the text block
  return `
  === EXECUTIVE SUMMARY ===
  - Total Records: ${totalRecords}
  - Total Distance Driven: ${totalKm.toFixed(1)} km
  - Total Expenses (Fuel + Tolls): €${(totalFuel + totalTolls).toFixed(2)} (Fuel: €${totalFuel}, Tolls: €${totalTolls})
  - Overall Delivery Success: ${totalDelivered} delivered / ${totalFailed} failed

  === PERFORMANCE BY TEAM ===
  ${Object.entries(teamStats).map(([team, stats]) => 
    `- ${team}: ${stats.days} shifts, ${stats.km.toFixed(0)}km, ${stats.delivered} delivered, ${stats.failed} failed, €${stats.cost.toFixed(2)} cost.`
  ).join('\n')}

  === RECENT LOG ENTRIES (Date | Team | KM | Delivered/Failed | Cost | Notes) ===
  ${records.slice(0, 50).map(r => 
    `${r.date} | ${r.team} | ${r.km_total}km | ${r.articles_delivered}/${r.articles_not_delivered} | €${((r.fuel_amount||0)+(r.toll_amount||0)).toFixed(0)} | ${r.notes ? r.notes.substring(0, 50) + '...' : '-'}`
  ).join('\n')}
  `;
};

export const geminiService = {
  // Chatbot using Gemini 3 Pro for deep reasoning over analytics
  async chatWithBot(message: string, records: DailyRecord[]) {
    if (!apiKey) return "API Key not configured in environment.";

    const context = generateAnalysisContext(records);

    const systemInstruction = `You are the specialized AI Analyst for 'SNavegar', a delivery logistics company.

    YOUR CAPABILITIES:
    1. You have access to the full database statistics (Summary) and detailed logs below.
    2. You can answer questions about total costs, team efficiency, specific delivery failures, and distance trends.
    3. If asked about a specific team, look at the "PERFORMANCE BY TEAM" section.
    4. Keep answers professional, concise, and data-driven. Use Euro (€) for currency.

    CURRENT DATA CONTEXT:
    ${context}
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: message,
        config: {
          systemInstruction,
          temperature: 0.3, // Lower temperature for more factual answers based on data
        }
      });
      return response.text || "I analyzed the data but couldn't generate a text response.";
    } catch (error) {
      console.error("Gemini Chat Error:", error);
      return "I'm having trouble analyzing the data right now. Please try again later.";
    }
  },

  // Fast responses using Gemini Flash Lite
  async getQuickInsight(records: DailyRecord[]) {
    if (!apiKey) return "API Key missing.";

    // We send a lighter context for the quick insight
    const totalDelivered = records.reduce((sum, r) => sum + (Number(r.articles_delivered) || 0), 0);
    const totalFailed = records.reduce((sum, r) => sum + (Number(r.articles_not_delivered) || 0), 0);

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-flash-lite-latest', 
        contents: `Based on ${records.length} records with ${totalDelivered} successes and ${totalFailed} failures, give me ONE single motivating sentence or a very brief efficiency tip.`,
      });
      return response.text || "Keep pushing for excellence!";
    } catch (error) {
      console.error("Gemini Flash Lite Error:", error);
      return "Ready for a new day!";
    }
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Bot, User } from 'lucide-react';
import { geminiService } from '../services/geminiService';
import { DailyRecord } from '../types';

interface ChatBotProps {
  records: DailyRecord[];
}

const ChatBot: React.FC<ChatBotProps> = ({ records }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [message, setMessage] = useState('');
  const [history, setHistory] = useState<{ sender: 'user' | 'bot'; text: string }[]>([
    { sender: 'bot', text: 'Hello! I have analyzed your entire database. Ask me about total expenses, team performance, kilometer trends, or specific delivery issues.' }
  ]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history, isOpen]);

  const handleSend = async () => {
    if (!message.trim()) return;

    const userMsg = message;
    setMessage('');
    setHistory(prev => [...prev, { sender: 'user', text: userMsg }]);
    setLoading(true);

    const response = await geminiService.chatWithBot(userMsg, records);

    setHistory(prev => [...prev, { sender: 'bot', text: response }]);
    setLoading(false);
  };

  return (
    <>
      {/* Floating Trigger */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-20 md:bottom-8 right-4 md:right-8 bg-primary text-white p-3 rounded-full shadow-lg hover:bg-blue-700 transition-all z-40 ${isOpen ? 'hidden' : 'flex'}`}
        aria-label="Open Chat"
      >
        <MessageSquare size={24} />
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-0 right-0 md:bottom-24 md:right-8 w-full md:w-96 h-[80vh] md:h-[600px] bg-white shadow-2xl rounded-t-2xl md:rounded-2xl flex flex-col z-50 overflow-hidden border border-gray-200">
          {/* Header */}
          <div className="bg-primary p-4 text-white flex justify-between items-center shadow-md">
            <div className="flex items-center space-x-2">
              <Bot size={20} />
              <span className="font-semibold">AI Assistant</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:bg-blue-600 p-1 rounded">
              <X size={20} />
            </button>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50" ref={scrollRef}>
            {history.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] p-3 rounded-lg text-sm ${
                    msg.sender === 'user'
                      ? 'bg-primary text-white rounded-br-none'
                      : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {loading && (
               <div className="flex justify-start">
                <div className="bg-gray-200 text-gray-500 text-xs px-3 py-2 rounded-lg animate-pulse">
                  Analyzing data...
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-3 bg-white border-t flex items-center space-x-2">
            <input
              type="text"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ex: How much did we spend on fuel?"
              className="flex-1 border border-gray-300 rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white text-gray-900"
            />
            <button
              onClick={handleSend}
              disabled={loading || !message.trim()}
              className="bg-primary text-white p-2 rounded-full hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </>
  );
};

export default ChatBot;

