import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Filter, Calendar, ChevronRight, Archive, RefreshCcw, FolderOpen, AlertCircle } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

interface RecordListProps {
  viewMode?: 'active' | 'archived';
}

const RecordList: React.FC<RecordListProps> = ({ viewMode = 'active' }) => {
  const navigate = useNavigate();
  const [records, setRecords] = useState<DailyRecord[]>([]);
  const [filteredRecords, setFilteredRecords] = useState<DailyRecord[]>([]);
  const [filterTeam, setFilterTeam] = useState('');
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  // Function to fetch records
  const loadRecords = async () => {
    setLoading(true);
    try {
        const data = await recordService.getAll();
        setRecords(data);
    } catch (e) {
        console.error(e);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadRecords();
  }, [viewMode]); 

  useEffect(() => {
    // 1. Filter by Active vs Archived
    let result = records.filter(r => {
        const isArchived = !!r.archived; // Ensure boolean
        if (viewMode === 'archived') {
            return isArchived === true;
        } else {
            return isArchived === false;
        }
    });

    // 2. Filter by Team Search
    if (filterTeam) {
      result = result.filter(r => r.team.toLowerCase().includes(filterTeam.toLowerCase()));
    }
    setFilteredRecords(result);
  }, [filterTeam, records, viewMode]);

  const handleToggleArchive = async (e: React.MouseEvent, record: DailyRecord) => {
    // Critical: Stop the click from bubbling up to the card div (which navigates to details)
    e.preventDefault(); 
    e.stopPropagation(); 

    setErrorMsg('');
    const willArchive = !record.archived;

    // Optimistic Update: Update UI immediately
    setRecords(prevRecords => prevRecords.map(r => {
        if (r.id === record.id) {
            return { ...r, archived: willArchive };
        }
        return r;
    }));

    // Perform actual update in background
    try {
        await recordService.update(record.id, { archived: willArchive });
    } catch (error: any) {
        console.error("Failed to update archive status", error);

        // Try to get a readable message
        let msg = "Verifique sua conexão ou permissões.";
        if (error?.message) msg = error.message;
        else if (error?.error_description) msg = error.error_description;

        setErrorMsg(`Falha ao atualizar: ${msg}`);

        // Revert optimistic update on failure
        setTimeout(() => {
            setRecords(prevRecords => prevRecords.map(r => {
                if (r.id === record.id) {
                    return { ...r, archived: !willArchive }; // Revert
                }
                return r;
            }));
        }, 1000); // Small delay so user sees what happened
    }
  };

  return (
    <div className="min-h-screen">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
        <div className="flex items-center space-x-3">
            {viewMode === 'archived' && <div className="bg-gray-200 p-2 rounded-lg text-gray-600"><Archive size={24} /></div>}
            <div>
                <h2 className="text-2xl font-bold text-gray-800">{viewMode === 'archived' ? 'Serviços Arquivados' : 'Registros Diários'}</h2>
                <p className="text-sm text-gray-500">{viewMode === 'archived' ? 'Estes registros não aparecem nas métricas.' : 'Operações diárias ativas.'}</p>
            </div>
        </div>

        {/* Search Bar */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por equipe..." 
            value={filterTeam}
            onChange={(e) => setFilterTeam(e.target.value)}
            className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-primary/50 bg-white text-gray-900"
          />
        </div>
      </div>

      {errorMsg && (
        <div className="mb-4 bg-red-50 text-red-600 p-3 rounded-lg flex items-center space-x-2 text-sm animate-pulse">
            <AlertCircle size={16} />
            <span>{errorMsg}</span>
        </div>
      )}

      {loading ? (
        <div className="space-y-4">
             {[1, 2, 3, 4].map(i => <div key={i} className="h-24 bg-gray-200 rounded-xl animate-pulse"/>)}
        </div>
      ) : (
        <div className="grid gap-4">
          {filteredRecords.map(record => (
            <div 
              key={record.id}
              onClick={() => navigate(`/records/${record.id}`)}
              className={`p-5 rounded-xl shadow-sm border hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center group relative ${record.archived ? 'bg-gray-50 border-gray-200 opacity-90' : 'bg-white border-gray-100'}`}
            >
              <div className="flex-1">
                <div className="flex items-center space-x-3 mb-2">
                    <div className={`px-2 py-1 rounded text-xs font-bold uppercase tracking-wide ${record.archived ? 'bg-gray-200 text-gray-600' : 'bg-blue-50 text-primary'}`}>
                        {new Date(record.date).toLocaleDateString('pt-BR', { month: 'short', day: 'numeric' })}
                    </div>
                    <span className={`font-bold ${record.archived ? 'text-gray-500' : 'text-gray-900'}`}>{record.team}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full ${record.status === 'finalized' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                        {record.status === 'finalized' ? 'finalizado' : 'rascunho'}
                    </span>
                </div>
                <div className="flex flex-wrap gap-4 text-sm text-gray-500">
                    <span>Van: {record.van_plate}</span>
                    <span>•</span>
                    <span>{record.km_total} km</span>
                    <span>•</span>
                    <span className={record.articles_not_delivered > 0 ? 'text-red-500 font-medium' : 'text-green-600'}>
                        {record.articles_not_delivered > 0 ? `${record.articles_not_delivered} Falhas` : 'Todos Entregues'}
                    </span>
                </div>
              </div>

              <div className="flex items-center space-x-2 pl-4 z-20">
                  {/* Archive/Unarchive Action Button */}
                  <button 
                    type="button"
                    onClick={(e) => handleToggleArchive(e, record)}
                    className={`p-3 rounded-full transition-colors flex items-center justify-center shadow-sm border ${
                        record.archived 
                        ? 'bg-white border-blue-200 text-blue-600 hover:bg-blue-50' 
                        : 'bg-white border-gray-200 text-gray-400 hover:text-red-500 hover:border-red-200 hover:bg-red-50'
                    }`}
                    title={record.archived ? "Desarquivar" : "Arquivar"}
                  >
                    {record.archived ? <RefreshCcw size={18} /> : <Archive size={18} />}
                  </button>

                  <ChevronRight className="text-gray-300 group-hover:text-primary transition-colors" />
              </div>
            </div>
          ))}

          {filteredRecords.length === 0 && (
             <div className="text-center py-16 text-gray-400 bg-white rounded-xl border border-dashed border-gray-200 animate-fade-in">
                 <FolderOpen size={48} className="mx-auto mb-3 opacity-20" />
                 <p className="font-medium">Nenhum registro {viewMode === 'active' ? 'ativo' : 'arquivado'} encontrado.</p>
                 <p className="text-sm opacity-70 mt-1">
                    {viewMode === 'active' 
                        ? 'Operações concluídas aparecerão aqui.' 
                        : 'Arquive registros para ocultá-los da lista principal.'}
                 </p>
             </div>
          )}
        </div>
      )}
       <style>{`
        .animate-fade-in {
            animation: fadeIn 0.3s ease-out;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(5px); }
            to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default RecordList;

import React, { useEffect, useState } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, LineChart, Line } from 'recharts';
import { Users, Filter } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

const TEAMS = [
    "Equipe 1 - Luiz e Luigi",
    "Equipe 2 - David e Ruben"
];

const Analytics: React.FC = () => {
  const [records, setRecords] = useState<DailyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedTeam, setSelectedTeam] = useState<string>('All');

  useEffect(() => {
    recordService.getAll().then(data => {
        setRecords(data);
        setLoading(false);
    });
  }, []);

  if (loading) return <div className="p-8 text-center text-gray-500">Carregando métricas...</div>;

  // 1. Filter out archived records FIRST
  const activeRecords = records.filter(r => !r.archived);

  // 2. Filter records based on team selection
  const filteredRecords = selectedTeam === 'All' 
    ? activeRecords 
    : activeRecords.filter(r => r.team === selectedTeam);

  // Simple aggregation for last 7 records (mocking "last 7 days" based on filtered data)
  // We reverse to show oldest to newest on chart
  const chartData = [...filteredRecords].reverse().slice(-7).map(r => ({
      date: new Date(r.date).toLocaleDateString('pt-BR', { weekday: 'short' }),
      delivered: r.articles_delivered,
      failed: r.articles_not_delivered,
      km: r.km_total
  }));

  const totalDeliveries = filteredRecords.reduce((acc, r) => acc + r.articles_delivered, 0);
  const totalFailed = filteredRecords.reduce((acc, r) => acc + r.articles_not_delivered, 0);
  const totalKm = filteredRecords.reduce((acc, r) => acc + r.km_total, 0);
  const totalCost = filteredRecords.reduce((acc, r) => acc + (r.fuel_amount || 0) + (r.toll_amount || 0), 0);

  return (
    <div className="pb-10 space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800">Métricas de Desempenho</h2>
            <p className="text-xs text-gray-500 mt-1">Exclui registros arquivados</p>
        </div>

        {/* Team Filter */}
        <div className="bg-white p-1.5 rounded-xl border border-gray-200 flex overflow-x-auto no-scrollbar shadow-sm">
            <button
                onClick={() => setSelectedTeam('All')}
                className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${
                    selectedTeam === 'All' 
                    ? 'bg-primary text-white shadow-md' 
                    : 'text-gray-600 hover:bg-gray-100'
                }`}
            >
                Todas as Equipes
            </button>
            {TEAMS.map(team => (
                <button
                    key={team}
                    onClick={() => setSelectedTeam(team)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ml-1 ${
                        selectedTeam === team 
                        ? 'bg-primary text-white shadow-md' 
                        : 'text-gray-600 hover:bg-gray-100'
                    }`}
                >
                    {/* Shorten name for display: "Equipe 1..." */}
                    {team.split(' - ')[0]}
                </button>
            ))}
        </div>
      </div>

      {filteredRecords.length === 0 ? (
          <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 text-center">
              <div className="text-gray-400 mb-2">Nenhum registro ativo encontrado para {selectedTeam === 'All' ? 'qualquer equipe' : selectedTeam}.</div>
              {selectedTeam !== 'All' && <p className="text-sm text-gray-500">Tente criar um novo registro diário para esta equipe.</p>}
          </div>
      ) : (
          <>
            {/* KPI Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-fade-in">
                <KPICard label="Entregas" value={totalDeliveries} color="text-green-600" />
                <KPICard label="Falhas" value={totalFailed} color="text-red-500" />
                <KPICard label="KM Total" value={`${totalKm} km`} color="text-blue-600" />
                <KPICard label="Despesas" value={`€${totalCost.toFixed(0)}`} color="text-purple-600" />
            </div>

            {/* Charts */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fade-in">

                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="font-semibold text-gray-700 mb-4">Entregas (Recentes)</h3>
                    <div className="h-64">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={chartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                <XAxis dataKey="date" axisLine={false} tickLine={false} fontSize={12} />
                                <Tooltip 
                                    contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} 
                                />
                                <Bar dataKey="delivered" fill="#22c55e" radius={[4, 4, 0, 0]} name="Entregues" />
                                <Bar dataKey="failed" fill="#ef4444" radius={[4, 4, 0, 0]} name="Falhas" />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="font-semibold text-gray-700 mb-4">Distância Percorrida (Recente)</h3>
                    <div className="h-64">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={chartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                <XAxis dataKey="date" axisLine={false} tickLine={false} fontSize={12} />
                                <Tooltip 
                                    contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                                />
                                <Line type="monotone" dataKey="km" stroke="#2563eb" strokeWidth={3} dot={{r: 4, fill: '#2563eb', strokeWidth: 0}} name="Quilômetros" />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
          </>
      )}

      <style>{`
        .animate-fade-in {
            animation: fadeIn 0.4s ease-out;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

const KPICard = ({ label, value, color }: { label: string, value: string | number, color: string }) => (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center hover:shadow-md transition-shadow">
        <span className="text-gray-400 text-xs font-medium uppercase tracking-wider mb-1">{label}</span>
        <span className={`text-2xl font-bold ${color}`}>{value}</span>
    </div>
);

export default Analytics;

