const CACHE_NAME = 'snavegar-v1';
const urlsToCache = [
  './',
  './index.html',
  './manifest.json',
  './icon.svg'
];

self.addEventListener('install', event => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => response || fetch(event.request))
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';

const getLocalRecords = (): DailyRecord[] => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

const setLocalRecords = (records: DailyRecord[]) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
};

// Simulate async delay ONLY for offline actions
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper robusto para gerar UUIDs
const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    if (supabase) {
      const { data, error } = await supabase
        .from('daily_records')
        .select('*')
        .order('date', { ascending: false });

      if (!error && data) {
        const serverRecords = data as DailyRecord[];
        const localRecords = getLocalRecords();

        // FIX: Identificar registros que existem localmente mas NÃO estão no servidor
        const localOnlyRecords = localRecords.filter(local => 
            !serverRecords.some(server => server.id === local.id)
        );

        const combinedRecords = [...serverRecords, ...localOnlyRecords];

        const mergedRecords = combinedRecords.map(r => {
            const local = localRecords.find(l => l.id === r.id);
            const serverHasArchived = 'archived' in r;
            const archived = serverHasArchived ? r.archived : (local?.archived || (r as any).archived || false);
            return { ...r, archived };
        });

        mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        setLocalRecords(mergedRecords);
        return mergedRecords;
      }

      if (error) {
        console.warn("Supabase fetch skipped (using local):", error.message);
      }
    }

    // Fallback completo
    await delay(300);
    return getLocalRecords().sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newRecordBase = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
    } as DailyRecord;

    let savedToCloud = false;

    if (supabase) {
      const { data: { user } } = await supabase.auth.getUser();

      // Only attempt Supabase insert if we have a user, to avoid obvious RLS blocks on anon
      if (user) {
        const payload = { ...newRecordBase, user_id: user.id };

        const { data, error } = await supabase.from('daily_records').insert(payload).select().single();

        if (!error && data) {
          console.log("Record saved to Supabase:", data.id);
          const currentLocal = getLocalRecords();
          currentLocal.push(data as DailyRecord);
          setLocalRecords(currentLocal);
          return data as DailyRecord;
        }

        if (error) {
            // Handle RLS or Schema errors gracefully
            const isRLS = error.code === '42501' || error.message?.includes('row-level security');
            const isSchema = error.code === 'PGRST204' || error.message?.includes("column") || error.code === '42P01';

            if (isRLS) {
                console.warn("Offline Mode (RLS): Saving locally. Cloud sync requires correct permissions.");
            } else if (isSchema) {
                console.warn("Offline Mode (Schema): Table/Column missing. Saving locally.");
            } else {
                console.error("Supabase Error:", error.message);
            }
        }
      }
    }

    // Fallback logic
    await delay(500);
    const records = getLocalRecords();
    records.push(newRecordBase);
    setLocalRecords(records);
    return newRecordBase;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let supabaseError = null;

    if (supabase) {
      const { data, error } = await supabase.from('daily_records').update(updates).eq('id', id).select().single();

      if (!error && data) {
         console.log("Record updated in Supabase:", id);
         const records = getLocalRecords();
         const index = records.findIndex(r => r.id === id);
         if (index !== -1) {
            records[index] = { ...records[index], ...data };
            setLocalRecords(records);
         }
         return data as DailyRecord;
      }

      if (error) {
        const isRLS = error.code === '42501' || error.message?.includes('row-level security');
        if (!isRLS) {
            console.error("SUPABASE UPDATE ERROR:", error.message);
            supabaseError = error;
        } else {
            console.warn("RLS blocked update. Updating locally.");
        }
      }
    }

    // Fallback
    await delay(300);
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }

    // Only throw if it wasn't a handled RLS/Schema error that we already fell back for
    if (supabaseError) {
         // Suppress throw for seamless offline feeling, but log it
         console.warn("Update failed on server, kept local.");
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
        if (!error && data) {
            const localRecords = getLocalRecords();
            const local = localRecords.find(l => l.id === id);
            const serverHasArchived = 'archived' in data;
            const archived = serverHasArchived ? data.archived : (local?.archived || false);
            return { ...data, archived } as DailyRecord;
        }
    }
    await delay(200);
    return getLocalRecords().find(r => r.id === id);
  }
};

