export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];

    // 1. Tenta buscar do servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('daily_records')
          .select('*')
          .order('date', { ascending: false });

        if (!error && data) {
          serverRecords = data as DailyRecord[];
        } else if (error) {
          console.warn("Erro ao buscar do Supabase (usando local):", error.message);
        }
      } catch (err) {
        console.warn("Erro de conexão Supabase:", err);
      }
    }

    // 2. Busca registros locais
    const localRecords = getLocalRecords();

    // 3. Mescla: Servidor + Local (apenas os que não existem no servidor)
    const localOnlyRecords = localRecords.filter(local => 
        !serverRecords.some(server => server.id === local.id)
    );

    const mergedRecords = [...serverRecords, ...localOnlyRecords];

    // 4. Ordena por data
    mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // 5. Atualiza cache local com a versão mais recente
    setLocalRecords(mergedRecords);

    return mergedRecords;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    // 1. Prepara o objeto completo
    const newRecord = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
    } as DailyRecord;

    let savedToCloud = false;

    // 2. Tenta salvar no Supabase
    if (supabase) {
      try {
        const { data: { user } } = await supabase.auth.getUser();

        if (user) {
          const payload = { 
              ...newRecord, 
              user_id: user.id,
              created_by_email: user.email 
          };

          const { data, error } = await supabase.from('daily_records').insert(payload).select().single();

          if (!error && data) {
            console.log("Salvo no Supabase com sucesso:", data.id);
            // Atualiza o objeto com dados do servidor (caso haja triggers/default values)
            Object.assign(newRecord, data);
            savedToCloud = true;
          } else {
            console.error("Erro ao salvar no Supabase (Salvando Localmente):", error?.message);
          }
        }
      } catch (err) {
        console.error("Erro crítico Supabase:", err);
      }
    }

    // 3. SEMPRE salva localmente (Fallback ou Cache)
    // Isso garante que o usuário nunca perca o dado, mesmo se o banco falhar
    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    // 1. Tenta atualizar no Supabase
    if (supabase) {
      try {
        const { error } = await supabase.from('daily_records').update(updates).eq('id', id);
        if (error) console.error("Erro update Supabase:", error.message);
      } catch (err) {
        console.error(err);
      }
    }

    // 2. Atualiza Localmente
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }

    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    // Tenta cache local primeiro para velocidade
    const localRecords = getLocalRecords();
    const localMatch = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (!error && data) {
                return data as DailyRecord;
            }
        } catch (e) {
            console.warn("Erro fetch single Supabase", e);
        }
    }

    return localMatch;
  }
};

import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, ChevronRight, Package, Truck, AlertCircle, TrendingUp } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

const Home: React.FC = () => {
  const navigate = useNavigate();
  const [recentRecords, setRecentRecords] = useState<DailyRecord[]>([]);
  const insight = "Organização hoje, resultados amanhã.";
  const [loading, setLoading] = useState(true);

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const records = await recordService.getAll();
      setRecentRecords(records.slice(0, 5)); // Top 5 recent
    } catch (err) {
      console.error("Failed to load home data", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();

    // Adiciona listener para recarregar quando a janela ganhar foco (útil em mobile PWA)
    window.addEventListener('focus', loadData);
    return () => window.removeEventListener('focus', loadData);
  }, [loadData]);

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      {/* Welcome & Insight */}
      <div className="bg-gradient-to-r from-blue-600 to-blue-800 rounded-2xl p-6 text-white shadow-lg">
        <h2 className="text-2xl font-bold mb-2">Olá, Equipe! 👋</h2>
        <div className="flex items-start space-x-3 bg-white/10 p-3 rounded-lg backdrop-blur-sm">
            <TrendingUp className="text-yellow-300 shrink-0 mt-1" size={20} />
            <p className="text-sm md:text-base font-medium leading-relaxed opacity-95">
                {insight}
            </p>
        </div>
      </div>

      {/* Primary Action */}
      <button
        onClick={() => navigate('/create')}
        className="w-full bg-white border-2 border-dashed border-primary/50 hover:border-primary text-primary font-semibold py-4 rounded-xl flex items-center justify-center space-x-2 transition-all hover:bg-blue-50"
      >
        <Plus size={24} />
        <span>Criar Registro Diário</span>
      </button>

      {/* Recent Activity */}
      <div>
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-bold text-gray-800">Atividade Recente</h3>
          <button 
            onClick={() => navigate('/records')}
            className="text-sm text-primary font-medium hover:underline"
          >
            Ver Todos
          </button>
        </div>

        {loading ? (
          <div className="space-y-3">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-20 bg-gray-200 rounded-xl animate-pulse"></div>
            ))}
          </div>
        ) : recentRecords.length === 0 ? (
          <div className="text-center py-10 text-gray-400 bg-white rounded-xl shadow-sm border border-gray-100">
            <Package size={48} className="mx-auto mb-2 opacity-20" />
            <p>Nenhum registro encontrado ainda.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {recentRecords.map(record => (
              <div
                key={record.id}
                onClick={() => navigate(`/records/${record.id}`)}
                className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:shadow-md transition-shadow cursor-pointer"
              >
                <div className="flex-1">
                  <div className="flex items-center space-x-2 mb-1">
                    <span className="font-bold text-gray-900">{record.team}</span>
                    <span className="text-xs text-gray-400">• {new Date(record.date).toLocaleDateString()}</span>
                  </div>
                  <div className="flex space-x-4 text-sm text-gray-600">
                    <div className="flex items-center space-x-1">
                      <Truck size={14} />
                      <span>{record.km_total} km</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <Package size={14} />
                      <span className="text-green-600">{record.articles_delivered}</span>
                      {record.articles_not_delivered > 0 && (
                        <span className="text-red-500 pl-1 flex items-center">
                            / {record.articles_not_delivered} <AlertCircle size={12} className="ml-0.5"/>
                        </span>
                      )}
                    </div>
                  </div>
                </div>
                <ChevronRight className="text-gray-400" size={20} />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Home;

