import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';

const getLocalRecords = (): DailyRecord[] => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Erro ao ler cache local:", e);
    return [];
  }
};

const setLocalRecords = (records: DailyRecord[]) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  } catch (e: any) {
    // Tratamento específico para cota excedida
    if (e.name === 'QuotaExceededError' || e.code === 22) {
      console.warn("LocalStorage cheio! Tentando limpar imagens antigas do cache local para liberar espaço.");

      // Cria uma versão "leve" dos registros apenas para cache (remove imagens pesadas)
      // O dado real completo deve estar salvo no Supabase
      const slimRecords = records.map(r => ({
        ...r,
        attachments: [] // Remove anexos do cache local para economizar espaço
      }));

      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(slimRecords));
        console.log("Cache salvo com versão otimizada (sem imagens).");
      } catch (retryError) {
        console.error("Crítico: Não foi possível salvar cache nem removendo imagens.", retryError);
      }
    } else {
        console.error("Erro desconhecido ao salvar cache:", e);
    }
  }
};

// Helper robusto para gerar UUIDs
const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const recordService = {
  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];

    // 1. Tenta buscar do servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('daily_records')
          .select('*')
          .order('date', { ascending: false });

        if (!error && data) {
          serverRecords = data as DailyRecord[];
        } else if (error) {
          console.warn("Erro ao buscar do Supabase (usando local):", error.message);
        }
      } catch (err) {
        console.warn("Erro de conexão Supabase:", err);
      }
    }

    // 2. Busca registros locais (com try/catch interno)
    const localRecords = getLocalRecords();

    // 3. Mescla: Servidor + Local (apenas os que não existem no servidor)
    const localOnlyRecords = localRecords.filter(local => 
        !serverRecords.some(server => server.id === local.id)
    );

    const mergedRecords = [...serverRecords, ...localOnlyRecords];

    // 4. Ordena por data
    mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // 5. Atualiza cache local com a versão mais recente
    // IMPORTANTE: Não deve quebrar o fluxo se falhar
    setLocalRecords(mergedRecords);

    return mergedRecords;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    // 1. Prepara o objeto completo
    const newRecord = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
    } as DailyRecord;

    // 2. Tenta salvar no Supabase
    if (supabase) {
      try {
        const { data: { user } } = await supabase.auth.getUser();

        if (user) {
          const payload = { 
              ...newRecord, 
              user_id: user.id,
              created_by_email: user.email 
          };

          const { data, error } = await supabase.from('daily_records').insert(payload).select().single();

          if (!error && data) {
            console.log("Salvo no Supabase com sucesso:", data.id);
            // Atualiza o objeto com dados do servidor (caso haja triggers/default values)
            Object.assign(newRecord, data);
          } else {
            console.error("Erro ao salvar no Supabase (Salvando Localmente):", error?.message);
          }
        }
      } catch (err) {
        console.error("Erro crítico Supabase:", err);
      }
    }

    // 3. SEMPRE tenta atualizar o cache local (Fallback)
    // Usa a função segura setLocalRecords que lida com QuotaExceeded
    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    // 1. Tenta atualizar no Supabase
    if (supabase) {
      try {
        const { error } = await supabase.from('daily_records').update(updates).eq('id', id);
        if (error) console.error("Erro update Supabase:", error.message);
      } catch (err) {
        console.error(err);
      }
    }

    // 2. Atualiza Localmente
    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records); // Salva com segurança
      return records[index];
    }

    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    // Tenta cache local primeiro para velocidade
    const localRecords = getLocalRecords();
    const localMatch = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (!error && data) {
                return data as DailyRecord;
            }
        } catch (e) {
            console.warn("Erro fetch single Supabase", e);
        }
    }

    return localMatch;
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Save, CheckCircle, Camera, UploadCloud, X, Loader2 } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

const TEAMS = [
  "Equipe 1 - Luiz e Luigi",
  "Equipe 2 - David e Ruben"
];

const RecordForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams(); // If ID exists, we are editing
  const [loading, setLoading] = useState(false);
  const [processingImage, setProcessingImage] = useState(false);

  const [formData, setFormData] = useState<Partial<DailyRecord>>({
    date: new Date().toISOString().split('T')[0],
    team: '',
    van_plate: '',
    start_time: '08:00',
    km_start: 0,
    km_end: 0,
    km_total: 0,
    articles_loaded: 0,
    articles_delivered: 0,
    articles_not_delivered: 0,
    reason_not_delivered: '',
    fueling: false,
    fuel_amount: 0,
    toll_amount: 0,
    attachments: [],
    notes: '',
    status: 'draft'
  });

  useEffect(() => {
    if (id) {
      const loadRecord = async () => {
        const record = await recordService.getById(id);
        if (record) setFormData(record);
      };
      loadRecord();
    }
  }, [id]);

  // Auto-calculate total KM
  useEffect(() => {
    const start = Number(formData.km_start) || 0;
    const end = Number(formData.km_end) || 0;
    if (end >= start) {
      setFormData(prev => ({ ...prev, km_total: end - start }));
    }
  }, [formData.km_start, formData.km_end]);

  const handleChange = (field: keyof DailyRecord, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  // Compress image to avoid QuotaExceededError and save data
  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                // Max width 800px to keep size small
                const scaleFactor = 800 / img.width;
                const newWidth = scaleFactor < 1 ? 800 : img.width;
                const newHeight = scaleFactor < 1 ? img.height * scaleFactor : img.height;

                canvas.width = newWidth;
                canvas.height = newHeight;

                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, newWidth, newHeight);

                // Compress to JPEG 0.7 quality
                const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.7);
                resolve(compressedDataUrl);
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setProcessingImage(true);

      try {
        const compressedBase64 = await compressImage(file);
        setFormData(prev => ({
            ...prev,
            attachments: [...(prev.attachments || []), compressedBase64]
          }));
      } catch (err) {
        console.error("Failed to process image", err);
        alert("Erro ao processar imagem. Tente uma menor.");
      } finally {
        setProcessingImage(false);
      }
    }
  };

  const removeAttachment = (index: number) => {
    setFormData(prev => ({
        ...prev,
        attachments: prev.attachments?.filter((_, i) => i !== index)
    }));
  };

  const handleSubmit = async (status: 'draft' | 'finalized') => {
    if (!formData.team || !formData.van_plate) {
        alert("Por favor selecione uma Equipe e preencha a Placa da Van.");
        return;
    }

    setLoading(true);
    const dataToSave = { ...formData, status } as DailyRecord; 

    try {
        if (id) {
            await recordService.update(id, dataToSave);
        } else {
            await recordService.create(dataToSave);
        }
        navigate('/');
    } catch (error) {
        console.error(error);
        alert("Erro ao salvar registro.");
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="pb-10">
      <h2 className="text-2xl font-bold mb-6 text-gray-800">{id ? 'Editar Registro' : 'Novo Registro Diário'}</h2>

      <div className="space-y-6">
        {/* Section 1: General */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold text-primary mb-4 border-b pb-2">Informações Gerais</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-gray-600 mb-1">Data</label>
              <input type="date" className="input-field" value={formData.date} onChange={e => handleChange('date', e.target.value)} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Hora de Início</label>
              <input type="time" className="input-field" value={formData.start_time} onChange={e => handleChange('start_time', e.target.value)} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Nome da Equipe</label>
              <select 
                className="input-field" 
                value={formData.team} 
                onChange={e => handleChange('team', e.target.value)}
              >
                <option value="" disabled>Selecione a Equipe</option>
                {TEAMS.map(team => (
                    <option key={team} value={team}>{team}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">Placa da Van</label>
              <input type="text" placeholder="AA-00-BB" className="input-field uppercase" value={formData.van_plate} onChange={e => handleChange('van_plate', e.target.value)} />
            </div>
          </div>
        </div>

        {/* Section 2: Kilometers */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold text-primary mb-4 border-b pb-2">Quilometragem</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-gray-600 mb-1">KM Inicial</label>
              <input type="number" className="input-field" value={formData.km_start} onChange={e => handleChange('km_start', parseFloat(e.target.value))} />
            </div>
            <div>
              <label className="block text-sm text-gray-600 mb-1">KM Final</label>
              <input type="number" className="input-field" value={formData.km_end} onChange={e => handleChange('km_end', parseFloat(e.target.value))} />
            </div>
          </div>
          <div className="mt-4 bg-gray-50 p-3 rounded-lg flex justify-between items-center">
            <span className="font-medium text-gray-700">Distância Total:</span>
            <span className="font-bold text-xl text-primary">{formData.km_total} km</span>
          </div>
        </div>

        {/* Section 3: Articles */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold text-primary mb-4 border-b pb-2">Artigos</h3>
          <div className="grid grid-cols-3 gap-3">
             <div className="col-span-3 md:col-span-1">
                <label className="block text-sm text-gray-600 mb-1">Carregados</label>
                <input type="number" className="input-field" value={formData.articles_loaded} onChange={e => handleChange('articles_loaded', parseInt(e.target.value))} />
             </div>
             <div>
                <label className="block text-sm text-gray-600 mb-1">Entregues</label>
                <input type="number" className="input-field text-green-600 font-medium" value={formData.articles_delivered} onChange={e => handleChange('articles_delivered', parseInt(e.target.value))} />
             </div>
             <div>
                <label className="block text-sm text-gray-600 mb-1">Não Entregues</label>
                <input type="number" className="input-field text-red-500 font-medium" value={formData.articles_not_delivered} onChange={e => handleChange('articles_not_delivered', parseInt(e.target.value))} />
             </div>
          </div>

          {(formData.articles_not_delivered || 0) > 0 && (
            <div className="mt-4 animate-fade-in">
                <label className="block text-sm text-red-600 font-medium mb-1">Motivo das falhas</label>
                <textarea 
                    className="input-field min-h-[80px]" 
                    placeholder="Ex: Cliente ausente, endereço errado..." 
                    value={formData.reason_not_delivered}
                    onChange={e => handleChange('reason_not_delivered', e.target.value)}
                />
            </div>
          )}
        </div>

        {/* Section 4: Expenses */}
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold text-primary mb-4 border-b pb-2">Despesas</h3>

          <div className="flex items-center mb-4">
            <input 
                type="checkbox" 
                id="fueling" 
                checked={formData.fueling} 
                onChange={e => handleChange('fueling', e.target.checked)}
                className="w-5 h-5 text-primary rounded focus:ring-primary bg-white border-gray-300"
            />
            <label htmlFor="fueling" className="ml-2 text-gray-700 font-medium">Abasteceu hoje?</label>
          </div>

