            alert("Upload falhou (Verifique internet). Salvando localmente provisoriamente.");
            const reader = new FileReader();
            reader.readAsDataURL(compressedBlob);
            reader.onloadend = () => {
                 setFormData(prev => ({
                    ...prev,
                    attachments: [...(prev.attachments || []), reader.result as string]
                  }));
            };
        }
      } catch (err) {
        console.error("Erro processamento imagem", err);
        alert("Erro ao processar imagem.");
      } finally {
        setProcessingImage(false);
      }
    }
  };

