import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';
const BUCKET_NAME = 'app-images';

const getLocalRecords = (): DailyRecord[] => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Erro ao ler cache local:", e);
    return [];
  }
};

const setLocalRecords = (records: DailyRecord[]) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  } catch (e: any) {
    if (e.name === 'QuotaExceededError' || e.code === 22) {
      console.warn("LocalStorage cheio! Limpando cache antigo.");
      const slimRecords = records.map(r => ({
        ...r,
        attachments: [] 
      }));
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(slimRecords));
      } catch (retryError) {
        console.error("Crítico: Falha no cache local.", retryError);
      }
    }
  }
};

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;

    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;

      const { data, error } = await supabase.storage
        .from(BUCKET_NAME)
        .upload(fileName, file, {
          cacheControl: '3600',
          upsert: false
        });

      if (error) {
        console.error("Erro upload Supabase:", error);
        return null;
      }

      const { data: publicUrlData } = supabase.storage
        .from(BUCKET_NAME)
        .getPublicUrl(data.path);

      return publicUrlData.publicUrl;

    } catch (err) {
      console.error("Erro no serviço de upload:", err);
      return null;
    }
  },

  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];

    // 1. Tenta buscar do servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('daily_records')
          .select('*')
          .order('date', { ascending: false });

        if (!error && data) {
          serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
        }
      } catch (err) {
        console.warn("Erro conexão Supabase:", err);
      }
    }

    // 2. Busca locais e identifica os que NÃO estão no servidor
    const localRecords = getLocalRecords();
    const localOnlyRecords = localRecords.filter(local => 
        !serverRecords.some(server => server.id === local.id)
    );

    // 3. AUTO-SYNC: Tenta subir os registros locais para a nuvem em background
    if (supabase && localOnlyRecords.length > 0) {
        // Não usamos await para não travar a UI (Fire and Forget)
        (async () => {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                console.log(`Tentando sincronizar ${localOnlyRecords.length} registros pendentes...`);
                for (const record of localOnlyRecords) {
                    const payload = { 
                        ...record, 
                        user_id: user.id,
                        // Garante que não enviamos campos de controle interno
                        _isSynced: undefined 
                    };
                    const { error } = await supabase.from('daily_records').upsert(payload);
                    if (!error) console.log(`Registro ${record.id} sincronizado com sucesso!`);
                }
            }
        })();
    }

    // Marca locais como não sincronizados visualmente
    const localOnlyWithFlag = localOnlyRecords.map(r => ({ ...r, _isSynced: false }));

    const mergedRecords = [...serverRecords, ...localOnlyWithFlag];
    mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    setLocalRecords(mergedRecords);
    return mergedRecords;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newRecord = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false // Começa como false, vira true se der certo
    } as DailyRecord;

    let savedToServer = false;

    if (supabase) {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (user) {
          const payload = { 
              ...newRecord, 
              user_id: user.id,
              created_by_email: user.email,
              _isSynced: undefined // Remove helper field antes de enviar
          };
          const { data, error } = await supabase.from('daily_records').insert(payload).select().single();
          if (!error && data) {
            Object.assign(newRecord, data);
            savedToServer = true;
            newRecord._isSynced = true;
          } else {
             console.error("Erro ao salvar no Supabase (será salvo localmente):", error?.message);
          }
        }
      } catch (err) {
        console.error("Erro create Supabase:", err);
      }
    }

    // Salva localmente (como backup ou oficial se estiver offline)
    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    // Remove o campo _isSynced se vier nos updates para não quebrar o banco
    const { _isSynced, ...cleanUpdates } = updates;

    if (supabase) {
      try {
        const { error } = await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
        if (error) console.error("Erro update Supabase:", error.message);
      } catch (err) { console.error(err); }
    }

    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    const localRecords = getLocalRecords();
    const localMatch = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (!error && data) return { ...data, _isSynced: true } as DailyRecord;
        } catch (e) {}
    }
    return localMatch ? { ...localMatch, _isSynced: false } : undefined;
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Filter, Calendar, ChevronRight, Archive, RefreshCcw, FolderOpen, AlertCircle, User, Truck, Package, DollarSign, Cloud, CloudOff } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

interface RecordListProps {
  viewMode?: 'active' | 'archived';
}

const RecordList: React.FC<RecordListProps> = ({ viewMode = 'active' }) => {
  const navigate = useNavigate();
  const [records, setRecords] = useState<DailyRecord[]>([]);
  const [filteredRecords, setFilteredRecords] = useState<DailyRecord[]>([]);
  const [filterTeam, setFilterTeam] = useState('');
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  // Function to fetch records
  const loadRecords = async () => {
    setLoading(true);
    try {
        const data = await recordService.getAll();
        setRecords(data);
    } catch (e) {
        console.error(e);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadRecords();
  }, [viewMode]); 

  useEffect(() => {
    // 1. Filter by Active vs Archived
    let result = records.filter(r => {
        const isArchived = !!r.archived; // Ensure boolean
        if (viewMode === 'archived') {
            return isArchived === true;
        } else {
            return isArchived === false;
        }
    });

    // 2. Filter by Team Search
    if (filterTeam) {
      result = result.filter(r => r.team.toLowerCase().includes(filterTeam.toLowerCase()));
    }
    setFilteredRecords(result);
  }, [filterTeam, records, viewMode]);

  const handleToggleArchive = async (e: React.MouseEvent, record: DailyRecord) => {
    e.preventDefault(); 
    e.stopPropagation(); 

    setErrorMsg('');
    const willArchive = !record.archived;

    setRecords(prevRecords => prevRecords.map(r => {
        if (r.id === record.id) {
            return { ...r, archived: willArchive };
        }
        return r;
    }));

    try {
        await recordService.update(record.id, { archived: willArchive });
    } catch (error: any) {
        console.error("Failed to update archive status", error);

        let msg = "Verifique sua conexão ou permissões.";
        if (error?.message) msg = error.message;

        setErrorMsg(`Falha ao atualizar: ${msg}`);

        setTimeout(() => {
            setRecords(prevRecords => prevRecords.map(r => {
                if (r.id === record.id) {
                    return { ...r, archived: !willArchive };
                }
                return r;
            }));
        }, 1000);
    }
  };

  return (
    <div className="min-h-screen pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
        <div className="flex items-center space-x-3">
            {viewMode === 'archived' && <div className="bg-gray-200 p-2 rounded-lg text-gray-600"><Archive size={24} /></div>}
            <div>
                <h2 className="text-2xl font-bold text-gray-800">{viewMode === 'archived' ? 'Serviços Arquivados' : 'Registros Diários'}</h2>
                <p className="text-sm text-gray-500">{viewMode === 'archived' ? 'Estes registros não aparecem nas métricas.' : 'Visão geral de todas as equipes.'}</p>
            </div>
        </div>

        {/* Search Bar */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por equipe..." 
            value={filterTeam}
            onChange={(e) => setFilterTeam(e.target.value)}
            className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-primary/50 bg-white text-gray-900"
          />
        </div>
      </div>

      {errorMsg && (
        <div className="mb-4 bg-red-50 text-red-600 p-3 rounded-lg flex items-center space-x-2 text-sm animate-pulse">
            <AlertCircle size={16} />
            <span>{errorMsg}</span>
        </div>
      )}

      {loading ? (
        <div className="space-y-4">
             {[1, 2, 3, 4].map(i => <div key={i} className="h-24 bg-gray-200 rounded-xl animate-pulse"/>)}
        </div>
      ) : filteredRecords.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-100 shadow-sm">
            <div className="text-gray-300 mb-3 flex justify-center"><FolderOpen size={48} /></div>
            <p className="text-gray-500 font-medium">Nenhum registro encontrado.</p>
            {viewMode === 'active' && <p className="text-sm text-gray-400 mt-1">Crie um novo registro para começar.</p>}
        </div>
      ) : (
        <div className="grid gap-4">
          {filteredRecords.map(record => (
            <div 
              key={record.id}
              onClick={() => navigate(`/records/${record.id}`)}
              className={`p-5 rounded-xl shadow-sm border hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center group relative ${record.archived ? 'bg-gray-50 border-gray-200 opacity-90' : 'bg-white border-gray-100'}`}
            >
              <div className="flex-1">
                <div className="flex flex-col md:flex-row md:items-center md:space-x-3 mb-2">
                    <div className="flex items-center space-x-2 mb-1 md:mb-0">
                        <div className={`px-2 py-1 rounded text-xs font-bold uppercase tracking-wide ${record.archived ? 'bg-gray-200 text-gray-600' : 'bg-blue-50 text-primary'}`}>
                            {new Date(record.date).toLocaleDateString('pt-BR', { month: 'short', day: 'numeric' })}
                        </div>
                        <span className={`font-bold ${record.archived ? 'text-gray-500' : 'text-gray-900'}`}>{record.team}</span>
                    </div>

                    {/* Visual indicator of who created it */}
                    {record.created_by_email && (
                        <div className="flex items-center space-x-1 text-xs text-gray-400 bg-gray-50 px-2 py-0.5 rounded-full w-fit">
                            <User size={10} />
                            <span>{record.created_by_email.split('@')[0]}</span>
                        </div>
                    )}

                    {/* Sync Status Indicator */}
                    <div className="flex items-center space-x-1 text-xs px-2 py-0.5 rounded-full w-fit">
                        {record._isSynced ? (
                            <span className="text-green-500 flex items-center space-x-1" title="Salvo na nuvem">
                                <Cloud size={12} />
                                <span className="hidden md:inline">Sincronizado</span>
                            </span>
                        ) : (
                            <span className="text-orange-500 bg-orange-50 flex items-center space-x-1 px-1 rounded" title="Salvo apenas no celular">
                                <CloudOff size={12} />
                                <span>Offline</span>
                            </span>
                        )}
                    </div>
                </div>

                <div className="flex flex-wrap gap-4 text-sm text-gray-600 mt-3 md:mt-1">
                    <div className="flex items-center space-x-1" title="Quilometragem Total">
                      <Truck size={14} />
                      <span>{record.km_total} km</span>
                    </div>
                    <div className="flex items-center space-x-1" title="Entregas Realizadas">
                      <Package size={14} />
                      <span className="text-green-600 font-medium">{record.articles_delivered}</span>
                      {record.articles_not_delivered > 0 && (
                          <span className="text-red-500 font-medium ml-1">
                            ({record.articles_not_delivered} falhas)
                          </span>
                      )}
                    </div>
                    {(record.fuel_amount > 0 || record.toll_amount > 0) && (
                        <div className="flex items-center space-x-1 text-gray-500" title="Custo Total">
                            <DollarSign size={14} />
                            <span>€{((record.fuel_amount || 0) + (record.toll_amount || 0)).toFixed(0)}</span>
                        </div>
                    )}
                </div>
              </div>

              <div className="flex flex-col items-end space-y-2 ml-4">
                 <button 
                    onClick={(e) => handleToggleArchive(e, record)}
                    className={`p-2 rounded-full transition-colors ${record.archived ? 'text-green-600 hover:bg-green-50' : 'text-gray-300 hover:text-red-500 hover:bg-red-50'}`}
                    title={record.archived ? "Desarquivar" : "Arquivar"}
                 >
                    {record.archived ? <RefreshCcw size={18} /> : <Archive size={18} />}
                 </button>
                 <ChevronRight className="text-gray-300" size={20} />
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

