import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';
const BUCKET_NAME = 'app-images';

const getLocalRecords = (): DailyRecord[] => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Erro ao ler cache local:", e);
    return [];
  }
};

const setLocalRecords = (records: DailyRecord[]) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  } catch (e: any) {
    if (e.name === 'QuotaExceededError' || e.code === 22) {
      console.warn("LocalStorage cheio! Limpando cache antigo.");
      const slimRecords = records.map(r => ({
        ...r,
        attachments: [] 
      }));
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(slimRecords));
      } catch (retryError) {
        console.error("Crítico: Falha no cache local.", retryError);
      }
    }
  }
};

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;

    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;

      const { data, error } = await supabase.storage
        .from(BUCKET_NAME)
        .upload(fileName, file, {
          cacheControl: '3600',
          upsert: false
        });

      if (error) {
        console.error("Erro upload Supabase:", error);
        return null;
      }

      const { data: publicUrlData } = supabase.storage
        .from(BUCKET_NAME)
        .getPublicUrl(data.path);

      return publicUrlData.publicUrl;

    } catch (err) {
      console.error("Erro no serviço de upload:", err);
      return null;
    }
  },

  // Função dedicada para forçar sincronização manual ou automática
  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    const localRecords = getLocalRecords();
    let syncedCount = 0;

    try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return 0;

        // Busca IDs que já estão no servidor para não reenviar desnecessariamente
        const { data: serverData } = await supabase.from('daily_records').select('id');
        const serverIds = new Set(serverData?.map(r => r.id) || []);

        const pending = localRecords.filter(r => !serverIds.has(r.id) || r._isSynced === false);

        for (const record of pending) {
            const payload = { 
                ...record, 
                user_id: user.id, // Garante que o registro tenha dono
                created_by_email: user.email,
                _isSynced: undefined 
            };

            // Upsert: Insere se não existe, atualiza se existe
            const { error } = await supabase.from('daily_records').upsert(payload);

            if (!error) {
                syncedCount++;
                // Atualiza localmente para marcar como sincronizado
                record._isSynced = true;
            } else {
                console.error(`Erro ao sincronizar registro ${record.id}:`, error.message);
            }
        }

        // Atualiza o storage local com os status corrigidos
        if (syncedCount > 0) {
            setLocalRecords(localRecords);
        }

    } catch (err) {
        console.error("Erro fatal no sync:", err);
    }
    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];

    // 1. Tenta buscar do servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('daily_records')
          .select('*')
          .order('date', { ascending: false });

        if (!error && data) {
          serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
        }
      } catch (err) {
        console.warn("Erro conexão Supabase:", err);
      }
    }

    // 2. Busca locais
    const localRecords = getLocalRecords();

    // 3. Merge inteligente:
    // Se existe no servidor, usa do servidor. Se só existe local, usa local.
    const mergedMap = new Map<string, DailyRecord>();

    // Prioridade para o servidor
    serverRecords.forEach(r => mergedMap.set(r.id, r));

    // Adiciona locais que não estão no servidor (Offline created)
    localRecords.forEach(r => {
        if (!mergedMap.has(r.id)) {
            mergedMap.set(r.id, { ...r, _isSynced: false });
        }
    });

    const mergedRecords = Array.from(mergedMap.values());
    mergedRecords.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // Salva o merge no local para garantir que dados do servidor fiquem em cache
    setLocalRecords(mergedRecords);

    // 4. Auto-trigger sync em background se houver itens não sincronizados
    const hasPending = mergedRecords.some(r => r._isSynced === false);
    if (hasPending && supabase) {
        this.syncPendingRecords().then(count => {
            if (count > 0) console.log(`Auto-sync: ${count} registros enviados.`);
        });
    }

    return mergedRecords;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newRecord = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    if (supabase) {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (user) {
          const payload = { 
              ...newRecord, 
              user_id: user.id,
              created_by_email: user.email,
              _isSynced: undefined 
          };
          const { data, error } = await supabase.from('daily_records').insert(payload).select().single();
          if (!error && data) {
            Object.assign(newRecord, data);
            newRecord._isSynced = true;
          }
        }
      } catch (err) {
        console.error("Erro create Supabase:", err);
      }
    }

    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    const { _isSynced, ...cleanUpdates } = updates;

    if (supabase) {
      try {
        const { error } = await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
        if (error) console.error("Erro update Supabase:", error.message);
      } catch (err) { console.error(err); }
    }

    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    const localRecords = getLocalRecords();
    const localMatch = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data, error } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (!error && data) return { ...data, _isSynced: true } as DailyRecord;
        } catch (e) {}
    }
    return localMatch ? { ...localMatch, _isSynced: false } : undefined;
  }
};

import React, { useState, useEffect } from 'react';
