    const localRecords = getLocalRecords();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return 0;

    const pending = localRecords.filter(r => r._isSynced === false);
    if (pending.length === 0) return 0;

    let syncedCount = 0;
    for (const record of pending) {
        const payload = preparePayload(record, user.id, user.email);
        const { error } = await supabase.from('daily_records').upsert(payload);
        if (!error) {
            record._isSynced = true;
            syncedCount++;
        }
    }
    if (syncedCount > 0) setLocalRecords(localRecords);
    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    if (supabase) {
      try {
        const { data, error } = await supabase.from('daily_records').select('*').order('date', { ascending: false });
        if (error) isOffline = true;
        else if (data) serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
      } catch (err) { isOffline = true; }
    }

    const localRecords = getLocalRecords();
    const finalMap = new Map<string, DailyRecord>();

    if (!isOffline) {
        serverRecords.forEach(r => finalMap.set(r.id, r));
        // Apenas locais que não existem no server entram (pendentes)
        localRecords.forEach(r => {
            if (!finalMap.has(r.id)) finalMap.set(r.id, { ...r, _isSynced: false });
        });
    } else {
        localRecords.forEach(r => finalMap.set(r.id, r));
    }

    const merged = Array.from(finalMap.values()).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
