      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    let savedToServer = false;
    let serverError = '';

    if (supabase) {
      try {
        // Tenta pegar usuário. Se falhar, tenta atualizar sessão
        let { data: { user } } = await supabase.auth.getUser();

        if (!user) {
            // Tenta refresh
            const { data: refreshData } = await supabase.auth.refreshSession();
