          } else {
            console.error("Erro CREATE:", error?.message);
            serverError = error?.message || 'Erro desconhecido no servidor';
          }
        } else {
            console.warn("Usuário não autenticado no momento do salvamento.");
            serverError = "Usuário não autenticado";
        }
      } catch (err: any) {
        console.error("Exceção CREATE:", err);
        serverError = err.message;
      }
    }

    // Salva localmente
    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

    // Se houve erro de servidor mas salvamos localmente, avisamos o componente para mostrar alerta
    if (!savedToServer && serverError === "Usuário não autenticado") {
        throw new Error("LOGIN_REQUIRED");
    }

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    if (supabase) {
        try {
            const { _isSynced, ...cleanUpdates } = updates;
            await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
        } catch (e) {}
    }

    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        try {
            const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (data) return { ...data, _isSynced: true } as DailyRecord;
        } catch (e) {}
    }
    const localRecords = getLocalRecords();
    return localRecords.find(r => r.id === id);
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Save, CheckCircle, Camera, X, Loader2, AlertTriangle, LogIn } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';
import { supabase } from '../services/supabaseClient';

const TEAMS = [
  "Equipe 1 - Luiz e Luigi",
  "Equipe 2 - David e Ruben"
];

const RecordForm: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [loading, setLoading] = useState(false);
  const [processingImage, setProcessingImage] = useState(false);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [authChecking, setAuthChecking] = useState(true);

  const [formData, setFormData] = useState<Partial<DailyRecord>>({
    date: new Date().toISOString().split('T')[0],
    team: '',
    van_plate: '',
    start_time: '08:00',
    km_start: 0,
    km_end: 0,
    km_total: 0,
    articles_loaded: 0,
    articles_delivered: 0,
    articles_not_delivered: 0,
    reason_not_delivered: '',
    fueling: false,
    fuel_amount: 0,
    toll_amount: 0,
    attachments: [],
    notes: '',
    status: 'draft'
  });

  // Check Auth on Mount
  useEffect(() => {
    const checkUser = async () => {
        if (!supabase) return;
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
            setUserEmail(session.user.email || 'Usuário');
        } else {
            setUserEmail(null);
        }
        setAuthChecking(false);
    };
    checkUser();
  }, []);

  useEffect(() => {
    if (id) {
      const loadRecord = async () => {
        const record = await recordService.getById(id);
        if (record) setFormData(record);
      };
      loadRecord();
    }
  }, [id]);

  useEffect(() => {
    const start = Number(formData.km_start) || 0;
    const end = Number(formData.km_end) || 0;
    if (end >= start) {
      setFormData(prev => ({ ...prev, km_total: end - start }));
    }
  }, [formData.km_start, formData.km_end]);

  const handleChange = (field: keyof DailyRecord, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const compressImageToBlob = (file: File): Promise<Blob> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const scaleFactor = 1024 / img.width;
                const newWidth = scaleFactor < 1 ? 1024 : img.width;
                const newHeight = scaleFactor < 1 ? img.height * scaleFactor : img.height;

                canvas.width = newWidth;
                canvas.height = newHeight;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, newWidth, newHeight);
                canvas.toBlob((blob) => {
                    if (blob) resolve(blob);
                    else reject(new Error("Conversion failed"));
                }, 'image/jpeg', 0.8);
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      setProcessingImage(true);

      try {
        const compressedBlob = await compressImageToBlob(file);
        const publicUrl = await recordService.uploadImage(compressedBlob);

        if (publicUrl) {
           setFormData(prev => ({
            ...prev,
            attachments: [...(prev.attachments || []), publicUrl]
          }));
        } else {
            alert("Upload falhou (Modo Offline). A foto será salva apenas neste dispositivo.");
            const reader = new FileReader();
            reader.readAsDataURL(compressedBlob);
            reader.onloadend = () => {
                 setFormData(prev => ({
                    ...prev,
                    attachments: [...(prev.attachments || []), reader.result as string]
                  }));
            };
        }
      } catch (err) {
        alert("Erro ao processar imagem.");
      } finally {
        setProcessingImage(false);
      }
    }
  };

  const removeAttachment = (index: number) => {
    setFormData(prev => ({
        ...prev,
        attachments: prev.attachments?.filter((_, i) => i !== index)
    }));
  };

  const handleSubmit = async (status: 'draft' | 'finalized') => {
    if (!userEmail) {
        alert("ERRO: Você está desconectado. Faça login novamente para salvar.");
        navigate('/login');
        return;
    }

    if (!formData.team || !formData.van_plate) {
        alert("Selecione uma Equipe e preencha a Placa.");
        return;
    }

    setLoading(true);
    const dataToSave = { ...formData, status } as DailyRecord; 

    try {
        if (id) {
            await recordService.update(id, dataToSave);
        } else {
            await recordService.create(dataToSave);
        }
        navigate('/');
    } catch (error: any) {
        console.error(error);
        if (error.message === "LOGIN_REQUIRED") {
            alert("Sua sessão expirou. O registro foi salvo localmente, mas você precisa fazer login novamente para enviar para a equipe.");
            navigate('/login');
        } else {
            alert("Erro ao salvar. Verifique sua conexão.");
        }
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="pb-10">
      {/* Auth Status Warning */}
      {!authChecking && !userEmail && (
        <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 rounded-r-lg shadow-sm">
            <div className="flex items-start">
