const CACHE_NAME = 'snavegar-v3-reset-total'; // Versão bumpada para forçar recarregamento
const urlsToCache = [
  './',
  './index.html',
  './manifest.json',
  './icon.svg'
];

self.addEventListener('install', event => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => response || fetch(event.request))
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';
const BUCKET_NAME = 'app-images';

// Função auxiliar para garantir que números sejam números e não strings vazias
const safeFloat = (val: any): number => {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return val;
  // Substitui vírgula por ponto (comum em teclados PT-BR)
  const str = String(val).replace(',', '.').trim();
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

const getLocalRecords = (): DailyRecord[] => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Erro ao ler cache local:", e);
    return [];
  }
};

const setLocalRecords = (records: DailyRecord[]) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  } catch (e: any) {
    if (e.name === 'QuotaExceededError' || e.code === 22) {
      const slimRecords = records.map(r => ({ ...r, attachments: [] }));
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify(slimRecords)); } catch (err) {}
    }
  }
};

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const preparePayload = (record: DailyRecord, userId: string, userEmail?: string) => {
  // Constrói o payload forçando tipos corretos para o Postgres
  const payload = {
    id: record.id,
    user_id: userId,
    created_by_email: userEmail || record.created_by_email,
    date: record.date,
    team: record.team,
    van_plate: record.van_plate,
    start_time: record.start_time,
    // Força conversão numérica segura
    km_start: safeFloat(record.km_start),
    km_end: safeFloat(record.km_end),
    km_total: safeFloat(record.km_total),
    articles_loaded: safeFloat(record.articles_loaded),
    articles_delivered: safeFloat(record.articles_delivered),
    articles_not_delivered: safeFloat(record.articles_not_delivered),
    reason_not_delivered: record.reason_not_delivered || '',
    fueling: !!record.fueling,
    fuel_amount: safeFloat(record.fuel_amount),
    toll_amount: safeFloat(record.toll_amount),
    attachments: record.attachments || [],
    notes: record.notes || '',
    status: record.status || 'draft',
    archived: !!record.archived,
    created_at: record.created_at
  };
  return payload;
};

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
      const { data, error } = await supabase.storage.from(BUCKET_NAME).upload(fileName, file, { cacheControl: '3600', upsert: false });
      if (error) return null;
      const { data: publicUrlData } = supabase.storage.from(BUCKET_NAME).getPublicUrl(data.path);
      return publicUrlData.publicUrl;
    } catch (err) { return null; }
  },

  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    const localRecords = getLocalRecords();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return 0;

    const pending = localRecords.filter(r => r._isSynced === false);
    if (pending.length === 0) return 0;

    let syncedCount = 0;
    for (const record of pending) {
        const payload = preparePayload(record, user.id, user.email);
        const { error } = await supabase.from('daily_records').upsert(payload);

        if (!error) {
            record._isSynced = true;
            syncedCount++;
        } else {
            console.error("Falha ao sincronizar registro pendente:", error.message);
        }
    }

    if (syncedCount > 0) {
        setLocalRecords(localRecords);
    }
    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    // Tenta pegar do servidor
    if (supabase) {
      try {
        const { data, error } = await supabase.from('daily_records').select('*').order('date', { ascending: false });
        if (error) {
            console.error("Erro GET Supabase:", error.message);
            isOffline = true;
        } else if (data) {
          serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
        }
      } catch (err) { isOffline = true; }
    }

    // Mescla com locais
    const localRecords = getLocalRecords();
    const finalMap = new Map<string, DailyRecord>();

    if (!isOffline) {
        serverRecords.forEach(r => finalMap.set(r.id, r));
        localRecords.forEach(r => {
            // Se o local não foi sincronizado ainda, mantém ele na lista
            if (!finalMap.has(r.id)) {
                finalMap.set(r.id, { ...r, _isSynced: false });
            }
        });
    } else {
        localRecords.forEach(r => finalMap.set(r.id, r));
    }

    const merged = Array.from(finalMap.values()).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    setLocalRecords(merged);

    // Auto-sync
    if (!isOffline && merged.some(r => !r._isSynced)) {
        this.syncPendingRecords();
    }
    return merged;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newRecord = {
      ...record,
      id: generateUUID(),
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    let savedToServer = false;

    if (supabase) {
      try {
        let { data: { user } } = await supabase.auth.getUser();

        // Tenta refresh se não tiver user
        if (!user) {
            const { data: refreshData } = await supabase.auth.refreshSession();
            user = refreshData.user;
        }

        if (user) {
          const payload = preparePayload(newRecord, user.id, user.email);

          // Debug
          console.log("Tentando enviar para o Supabase:", payload);

          const { data, error } = await supabase.from('daily_records').insert(payload).select().single();

          if (!error && data) {
            Object.assign(newRecord, data);
            newRecord._isSynced = true;
            savedToServer = true;
          } else {
            console.error("Erro CRÍTICO Supabase CREATE:", error.message, error.details);
            throw new Error(error.message); // Lança erro para ser pego pelo componente
          }
        } else {
            throw new Error("LOGIN_REQUIRED");
        }
      } catch (err: any) {
        console.error("Exceção no processo de create:", err);
        // Se for erro de login, repassa. Se for rede, silencia e salva local.
        if (err.message === "LOGIN_REQUIRED" || err.message.includes("JWT")) {
            throw new Error("LOGIN_REQUIRED");
        }
      }
    }

    // Salva Local
    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    if (supabase) {
        try {
            const { _isSynced, ...cleanUpdates } = updates;
            // Sanitiza números também no update
            const safeUpdates: any = { ...cleanUpdates };
            ['km_start', 'km_end', 'km_total', 'articles_loaded', 'articles_delivered', 'articles_not_delivered', 'fuel_amount', 'toll_amount'].forEach(key => {
                if (key in safeUpdates) safeUpdates[key] = safeFloat(safeUpdates[key]);
            });

            await supabase.from('daily_records').update(safeUpdates).eq('id', id);
        } catch (e) {
            console.error("Erro Update:", e);
        }
    }

    const records = getLocalRecords();
    const index = records.findIndex(r => r.id === id);
    if (index !== -1) {
      records[index] = { ...records[index], ...updates };
      setLocalRecords(records);
      return records[index];
    }
    return null;
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    if (supabase) {
        try {
            const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (data) return { ...data, _isSynced: true } as DailyRecord;
        } catch (e) {}
    }
    const localRecords = getLocalRecords();
    return localRecords.find(r => r.id === id);
  }
};

