export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
      const { data, error } = await supabase.storage.from(BUCKET_NAME).upload(fileName, file, { 
        cacheControl: '3600', 
        upsert: false 
      });
      if (error) {
        console.error("Upload Error:", error);
        return null;
      }
      const { data: publicUrlData } = supabase.storage.from(BUCKET_NAME).getPublicUrl(data.path);
      return publicUrlData.publicUrl;
    } catch (err) { 
        console.error("Upload Exception:", err);
        return null; 
    }
  },

  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    // 1. Verifica autenticação
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) return 0;

    const user = session.user;
    const localRecords = getLocalRecords();
    const pending = localRecords.filter(r => r._isSynced === false);

    if (pending.length === 0) return 0;

    console.log(`Tentando sincronizar ${pending.length} registros...`);
    let syncedCount = 0;

    for (const record of pending) {
        try {
            const payload = preparePayload(record, user.id, user.email);
            // Upsert garante que se já existir (pelo ID), atualiza. Se não, cria.
            const { error } = await supabase.from('daily_records').upsert(payload);

            if (!error) {
                record._isSynced = true;
                syncedCount++;
            } else {
                console.error("Sync Error Individual:", error.message);
            }
        } catch (err) {
            console.error("Sync Exception:", err);
        }
    }

    if (syncedCount > 0) {
        setLocalRecords(localRecords);
        // Recarrega lista completa para garantir consistência
        await this.getAll();
    }

    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    // 1. Busca do Servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
            .from('daily_records')
            .select('*')
            .order('date', { ascending: false });

        if (error) {
            console.error("Supabase GET Error:", error.message);
            isOffline = true;
        } else if (data) {
          serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
        }
      } catch (err) {
        isOffline = true;
      }
    }

    // 2. Busca Local
    const localRecords = getLocalRecords();

    // 3. Merge Inteligente
    const finalMap = new Map<string, DailyRecord>();

    if (!isOffline) {
        // Confiança total no servidor
        serverRecords.forEach(r => finalMap.set(r.id, r));

        // Adiciona APENAS os locais que ainda não subiram (pendentes)
        localRecords.forEach(r => {
            // Se o servidor não tem esse ID, e ele está marcado como não sincronizado localmente, adiciona.
            if (!finalMap.has(r.id)) {
                finalMap.set(r.id, { ...r, _isSynced: false });
            }
        });
    } else {
        // Offline: mostra tudo que tem local
        localRecords.forEach(r => finalMap.set(r.id, r));
    }

    const merged = Array.from(finalMap.values())
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    setLocalRecords(merged);

    // Tenta sync background se tiver online
    if (!isOffline && merged.some(r => !r._isSynced)) {
        this.syncPendingRecords();
    }

    return merged;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
