        } else {
            throw new Error("LOGIN_REQUIRED");
        }
      } catch (err: any) {
        console.error("Create Exception:", err);
        if (err.message === "LOGIN_REQUIRED") throw err;
        // Outros erros (ex: internet), segue para salvar local
      }
    }

    // Salva Localmente Sempre
    const currentLocal = getLocalRecords();
    currentLocal.push(newRecord);
    setLocalRecords(currentLocal);

