    return localRecords.find(r => r.id === id);
  }
};

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const STORAGE_KEY = 'snavegar_records';
const BUCKET_NAME = 'app-images';

// --- HELPERS ---

// Gera UUID compatível se o navegador não tiver crypto.randomUUID (alguns Androids antigos)
const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// Remove vírgulas de teclados brasileiros e garante Number
const safeFloat = (val: any): number => {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return val;
  const str = String(val).replace(',', '.').trim();
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

const getLocalRecords = (): DailyRecord[] => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    return [];
  }
};

const setLocalRecords = (records: DailyRecord[]) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  } catch (e: any) {
    // Tratamento de Erro de Quota (Storage Full)
    if (e.name === 'QuotaExceededError' || e.code === 22 || e.message?.toLowerCase().includes('quota')) {
      console.warn("Storage Limit Exceeded. Trimming cache...");

      // Estratégia de Limpeza:
      // 1. Prioridade MAXIMA: Manter registros não sincronizados (dados ainda não salvos na nuvem).
      // 2. Prioridade ALTA: Manter os últimos 20 registros sincronizados para consulta offline.
      // 3. Descartar: Registros antigos já sincronizados.

      const unsynced = records.filter(r => r._isSynced === false);
      const synced = records.filter(r => r._isSynced === true);

      // Ordena sincronizados do mais novo para o mais antigo
      synced.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      // Mantém apenas os 20 mais recentes
      const keptSynced = synced.slice(0, 20);
      const optimizedRecords = [...unsynced, ...keptSynced];

      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(optimizedRecords));
        console.log(`Cache limpo com sucesso. Mantidos: ${unsynced.length} pendentes, ${keptSynced.length} recentes.`);
      } catch (e2) {
        // Se ainda falhar, modo de emergência: Tenta salvar apenas os não sincronizados
        try {
           console.warn("Ainda sem espaço. Salvando apenas pendentes.");
           localStorage.setItem(STORAGE_KEY, JSON.stringify(unsynced));
        } catch (e3) {
           console.error("CRÍTICO: Não foi possível salvar dados locais. Armazenamento cheio.", e3);
        }
      }
    }
  }
};

// Prepara o objeto para ser aceito pelo PostgreSQL sem erros
const preparePayload = (record: DailyRecord, userId: string, userEmail?: string) => {
  return {
    id: record.id,
    user_id: userId,
    created_by_email: userEmail || record.created_by_email,
    date: record.date,
    team: record.team || 'Equipe Indefinida',
    van_plate: record.van_plate || '',
    start_time: record.start_time || '00:00',
    km_start: safeFloat(record.km_start),
    km_end: safeFloat(record.km_end),
    km_total: safeFloat(record.km_total),
    articles_loaded: safeFloat(record.articles_loaded),
    articles_delivered: safeFloat(record.articles_delivered),
    articles_not_delivered: safeFloat(record.articles_not_delivered),
    reason_not_delivered: record.reason_not_delivered || '',
    fueling: !!record.fueling,
    fuel_amount: safeFloat(record.fuel_amount),
    toll_amount: safeFloat(record.toll_amount),
    attachments: record.attachments || [],
    notes: record.notes || '',
    status: record.status || 'draft',
    archived: !!record.archived,
    created_at: record.created_at || new Date().toISOString()
  };
};

