];

self.addEventListener('install', event => {
  // REMOVIDO self.skipWaiting().
  // Isso permite que o novo SW instale em background, mas fique "esperando"
  // até que o usuário feche todas as abas/janelas do app antes de ativar.
  event.waitUntil(
