import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';

interface RecordContextType {
  records: DailyRecord[];
  loading: boolean;
  refreshRecords: () => Promise<void>;
}

const RecordContext = createContext<RecordContextType | undefined>(undefined);

export const RecordProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [records, setRecords] = useState<DailyRecord[]>([]);
  const [loading, setLoading] = useState(true);

  const refreshRecords = useCallback(async () => {
    // Não seta loading=true aqui para evitar "piscar" a tela se já tiver dados
    try {
      const data = await recordService.getAll();
      setRecords(data);
    } catch (error) {
      console.error("Erro ao atualizar contexto:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  // Carga inicial
  useEffect(() => {
    refreshRecords();
  }, [refreshRecords]);

  // Listener para recarregar quando a janela ganhar foco (útil ao voltar de outro app)
  useEffect(() => {
    const onFocus = () => refreshRecords();
    window.addEventListener('focus', onFocus);
    return () => window.removeEventListener('focus', onFocus);
  }, [refreshRecords]);

  return (
    <RecordContext.Provider value={{ records, loading, refreshRecords }}>
      {children}
    </RecordContext.Provider>
  );
};

export const useRecords = () => {
  const context = useContext(RecordContext);
  if (!context) {
    throw new Error('useRecords deve ser usado dentro de um RecordProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import ChatBot from './components/ChatBot';
import Login from './pages/Login';
import Home from './pages/Home';
import RecordForm from './pages/RecordForm';
import RecordList from './pages/RecordList';
import RecordDetail from './pages/RecordDetail';
import Analytics from './pages/Analytics';
import { supabase } from './services/supabaseClient';
import { RecordProvider } from './contexts/RecordContext';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check active session
    const checkSession = async () => {
        if (supabase) {
            const { data: { session } } = await supabase.auth.getSession();
            setIsAuthenticated(!!session);
        } else {
             // Fallback for demo without Supabase keys
             const localAuth = localStorage.getItem('snavegar_auth');
             if (localAuth) setIsAuthenticated(true);
        }
        setLoading(false);
    };

    checkSession();

    // Listen for auth changes
    const { data: authListener } = supabase?.auth.onAuthStateChange((_event, session) => {
        setIsAuthenticated(!!session);
    }) || { data: { subscription: { unsubscribe: () => {} } } };

    return () => {
        authListener.subscription.unsubscribe();
    };
  }, []);

  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = async () => {
    if (supabase) {
        await supabase.auth.signOut();
    } else {
        localStorage.removeItem('snavegar_auth');
    }
    setIsAuthenticated(false);
  };

  if (loading) {
      return <div className="min-h-screen flex items-center justify-center bg-gray-50 text-primary">Loading...</div>;
  }

  return (
    <HashRouter>
      <RecordProvider>
        <Routes>
          <Route 
            path="/login" 
            element={!isAuthenticated ? <Login onLogin={handleLogin} /> : <Navigate to="/" />} 
          />

          <Route
            path="/*"
            element={
              isAuthenticated ? (
                <Layout onLogout={handleLogout}>
                  <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/create" element={<RecordForm />} />
                    <Route path="/records" element={<RecordList viewMode="active" />} />
                    <Route path="/archived" element={<RecordList viewMode="archived" />} />
                    <Route path="/records/:id" element={<RecordDetail />} />
                    <Route path="/records/:id/edit" element={<RecordForm />} />
                    <Route path="/analytics" element={<Analytics />} />
                    <Route path="*" element={<Navigate to="/" />} />
                  </Routes>
                  {/* Global ChatBot now uses Context internaly */}
                  <ChatBot />
                </Layout>
              ) : (
                <Navigate to="/login" />
              )
            }
          />
        </Routes>
      </RecordProvider>
    </HashRouter>
  );
};

export default App;

