  const [errorMsg, setErrorMsg] = useState('');

  const handleManualSync = async () => {
    setSyncing(true);
    setErrorMsg('');
    try {
        await recordService.syncPendingRecords();
        await refreshRecords(); 
    } catch (e) {
        console.error("Sync error", e);
        setErrorMsg("Falha na sincronização.");
    } finally {
        setSyncing(false);
    }
  };

