const CACHE_NAME = 'snavegar-v6-network-only-api'; 
const urlsToCache = [
  './',
  './index.html',
  './manifest.json',
  './icon.svg'
];

// Domains explicitly excluded from cache to ensure live data and auth tokens
const NETWORK_ONLY_DOMAINS = [
  'generativelanguage.googleapis.com', // Google Gemini API
  'supabase.co'                        // Supabase API
];

self.addEventListener('install', event => {
  // Allows the new SW to install in background but waits for next launch to activate
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);

  // Check if the request is for an API that requires live network access
  const isNetworkOnly = NETWORK_ONLY_DOMAINS.some(domain => url.hostname.includes(domain));

  if (isNetworkOnly) {
    // Network-Only Strategy for APIs:
    // 1. Bypasses cache completely to prevent stale data or auth token issues.
    // 2. Ensures Gemini and Supabase requests always hit the network.
    // 3. Allows the application logic to handle offline errors naturally.
    event.respondWith(
      fetch(event.request).catch(error => {
        console.warn('[SW] API Network request failed:', url.href);
        // Rethrow to let the client app handle the exception (e.g. show offline message)
        throw error;
      })
    );
    return;
  }

  // Cache-First Strategy for static assets (UI, icons, HTML)
  event.respondWith(
    caches.match(event.request)
      .then(response => response || fetch(event.request))
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    Promise.all([
      // Clean up old caches
      caches.keys().then(cacheNames => {
        return Promise.all(
          cacheNames.map(cacheName => {
            if (cacheName !== CACHE_NAME) {
              return caches.delete(cacheName);
            }
          })
        );
      }),
      // Take control of clients immediately to apply new routing rules
      self.clients.claim()
    ])
  );
});

