export default RecordForm;

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const DB_NAME = 'SNavegarDB';
const DB_VERSION = 1;
const STORE_NAME = 'daily_records';
const BUCKET_NAME = 'app-images';
const OLD_STORAGE_KEY = 'snavegar_records'; // Para migração

// --- INDEXED DB HELPERS (O "Armazém Gigante") ---

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => reject("Erro ao abrir banco de dados local");

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        // Cria a "tabela" local usando 'id' como chave primária
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = (event) => {
      resolve((event.target as IDBOpenDBRequest).result);
    };
  });
};

// Salva um único registro no IndexedDB
const saveLocalRecord = async (record: DailyRecord) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put(record); 

    // IMPORTANTE: Aguarda a transação completar totalmente antes de resolver.
    // Isso garante que os dados estão no disco antes de a UI tentar lê-los.
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro na transação de salvamento local");
    request.onerror = () => reject("Erro na requisição de salvamento local");
  });
};

// Remove um registro do IndexedDB
const deleteLocalRecord = async (id: string) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.delete(id);

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro ao apagar registro local");
  });
};

// Busca todos os registros locais
const getAllLocalRecords = async (): Promise<DailyRecord[]> => {
  const db = await openDB();
  return new Promise<DailyRecord[]>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => {
        const records = request.result as DailyRecord[];
        resolve(records || []);
    };
    request.onerror = () => reject("Erro ao ler registros locais");
  });
};

// Migração: Move dados do LocalStorage (Bolso) para IndexedDB (Mochila) e limpa o bolso
const migrateLegacyData = async () => {
  const legacyData = localStorage.getItem(OLD_STORAGE_KEY);
  if (legacyData) {
    try {
      console.log("Iniciando migração de armazenamento...");
      const parsedData: DailyRecord[] = JSON.parse(legacyData);

      const db = await openDB();
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);

      parsedData.forEach(record => {
        store.put(record);
      });

      transaction.oncomplete = () => {
        console.log("Migração concluída com sucesso!");
        localStorage.removeItem(OLD_STORAGE_KEY); // Libera o localStorage
      };
    } catch (e) {
      console.error("Erro na migração de dados:", e);
    }
  }
};

// --- HELPERS GERAIS ---

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const safeFloat = (val: any): number => {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return val;
  const str = String(val).replace(',', '.').trim();
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

// Prepara o objeto para ser aceito pelo PostgreSQL sem erros
const preparePayload = (record: DailyRecord, userId: string, userEmail?: string) => {
  return {
    id: record.id,
    user_id: userId,
    created_by_email: userEmail || record.created_by_email,
    date: record.date,
    team: record.team || 'Equipe Indefinida',
    van_plate: record.van_plate || '',
    start_time: record.start_time || '00:00',
    km_start: safeFloat(record.km_start),
    km_end: safeFloat(record.km_end),
    km_total: safeFloat(record.km_total),
    articles_loaded: safeFloat(record.articles_loaded),
    articles_delivered: safeFloat(record.articles_delivered),
    articles_not_delivered: safeFloat(record.articles_not_delivered),
    reason_not_delivered: record.reason_not_delivered || '',
    fueling: !!record.fueling,
    fuel_amount: safeFloat(record.fuel_amount),
    toll_amount: safeFloat(record.toll_amount),
    attachments: record.attachments || [],
    notes: record.notes || '',
    status: record.status || 'draft',
    archived: !!record.archived,
    created_at: record.created_at || new Date().toISOString()
  };
};

// --- SERVICE ---

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
      const { data, error } = await supabase.storage.from(BUCKET_NAME).upload(fileName, file, { 
        cacheControl: '3600', 
        upsert: false 
      });
      if (error) {
        console.error("Upload Error:", error);
        return null;
      }
      const { data: publicUrlData } = supabase.storage.from(BUCKET_NAME).getPublicUrl(data.path);
      return publicUrlData.publicUrl;
    } catch (err) { 
        console.error("Upload Exception:", err);
        return null; 
    }
  },

  async processAttachmentsForSync(attachments: string[]): Promise<string[]> {
    if (!attachments || !attachments.length) return [];

    const hasBase64 = attachments.some(a => a.startsWith('data:'));
    if (!hasBase64) return attachments;

    const processed = await Promise.all(attachments.map(async (att) => {
      if (att.startsWith('data:')) {
        try {
            const res = await fetch(att);
            const blob = await res.blob();
            const url = await this.uploadImage(blob);
            return url || att; 
        } catch (e) {
            console.error("Falha ao processar imagem para sync:", e);
            return att;
        }
      }
      return att;
    }));
    return processed;
  },

  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    // Tenta migrar dados legados antes do sync, por segurança
    await migrateLegacyData();

    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) return 0;

    const user = session.user;
    const localRecords = await getAllLocalRecords();
    const pending = localRecords.filter(r => r._isSynced === false);

    if (pending.length === 0) return 0;

    console.log(`Tentando sincronizar ${pending.length} registros...`);
    let syncedCount = 0;

    for (const record of pending) {
        try {
            if (record.attachments && record.attachments.length > 0) {
                const updatedAttachments = await this.processAttachmentsForSync(record.attachments);
                record.attachments = updatedAttachments;
            }

            const payload = preparePayload(record, user.id, user.email);
            const { error } = await supabase.from('daily_records').upsert(payload);

            if (!error) {
                // Atualiza localmente para marcar como sincronizado
                const syncedRecord = { ...record, _isSynced: true };
                await saveLocalRecord(syncedRecord);
                syncedCount++;
            } else {
                console.error("Sync Error Individual:", error.message);
            }
        } catch (err) {
            console.error("Sync Exception:", err);
        }
    }

    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    await migrateLegacyData();

    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    // 2. Busca do Servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
            .from('daily_records')
            .select('*')
            .order('date', { ascending: false })
            .limit(100);

        if (error) {
            console.warn("Supabase GET Error (Offline?):", error.message);
            isOffline = true;
        } else if (data) {
          serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
        }
      } catch (err) {
        isOffline = true;
      }
    }

    // 3. Busca Local
    const localRecords = await getAllLocalRecords();

    // 4. Merge Inteligente
    const finalMap = new Map<string, DailyRecord>();

    if (!isOffline) {
        // Servidor tem prioridade, mas salvamos o que vem dele no cache local
        for (const r of serverRecords) {
           finalMap.set(r.id, r);
           // Update cache in background without awaiting
           saveLocalRecord(r).catch(e => console.warn("Cache update failed", e));
        }

        // Adiciona locais que ainda não subiram
        localRecords.forEach(r => {
            if (!finalMap.has(r.id) || !r._isSynced) {
                finalMap.set(r.id, r);
            }
        });
    } else {
        // Offline: mostra tudo que tem local
        localRecords.forEach(r => finalMap.set(r.id, r));
    }

    const merged = Array.from(finalMap.values())
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return merged;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newId = generateUUID();
    const newRecord = {
      ...record,
      id: newId,
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    if (supabase) {
      try {
        const { data: { session } } = await supabase.auth.getSession();

        if (session?.user) {
          // Processa imagens se necessário
          if (newRecord.attachments && newRecord.attachments.some(a => a.startsWith('data:'))) {
             newRecord.attachments = await this.processAttachmentsForSync(newRecord.attachments);
          }

          const payload = preparePayload(newRecord, session.user.id, session.user.email);
          const { error } = await supabase.from('daily_records').insert(payload);

          if (!error) {
            newRecord._isSynced = true;
          } else {
            console.error("Supabase Create Error:", error.message);
            // Não damos throw aqui, deixamos salvar localmente com _isSynced=false
          }
        } else {
             // Sem sessão, apenas salva local (offline mode ou fallback)
             console.warn("User not logged in, saving locally only.");
        }
      } catch (err: any) {
        console.error("Create Exception:", err);
      }
    }

    // Salva Localmente Sempre e espera a transação completar
    await saveLocalRecord(newRecord);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let updatedRecord: DailyRecord | null = null;

    const localRecords = await getAllLocalRecords();
    const existing = localRecords.find(r => r.id === id);

    if (existing) {
        updatedRecord = { ...existing, ...updates, _isSynced: false };
    }

    if (supabase) {
        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                const cleanUpdates: any = { ...updates };
                delete cleanUpdates._isSynced;
                delete cleanUpdates.id;

                if (cleanUpdates.attachments && cleanUpdates.attachments.some((a:string) => a.startsWith('data:'))) {
                    cleanUpdates.attachments = await this.processAttachmentsForSync(cleanUpdates.attachments);
                    if (updatedRecord) updatedRecord.attachments = cleanUpdates.attachments;
                }

                ['km_start', 'km_end', 'km_total', 'articles_loaded', 
                 'articles_delivered', 'articles_not_delivered', 
                 'fuel_amount', 'toll_amount'].forEach(key => {
                    if (cleanUpdates[key] !== undefined) {
                        cleanUpdates[key] = safeFloat(cleanUpdates[key]);
                    }
                });

                const { error } = await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
                if (!error && updatedRecord) {
                    updatedRecord._isSynced = true;
                }
            }
        } catch (e) {
            console.error("Update DB Error:", e);
        }
    }

    if (updatedRecord) {
        await saveLocalRecord(updatedRecord);
    }

    return updatedRecord;
  },

  // NOVO MÉTODO: HARD DELETE
  async delete(id: string): Promise<void> {
    // 1. Recupera o registro para saber quais fotos apagar
    const record = await this.getById(id);

    if (supabase) {
        try {
            // A. Deletar Imagens do Storage (Limpeza Pesada)
            if (record && record.attachments && record.attachments.length > 0) {
                const filesToRemove = record.attachments.map(url => {
                    // Extrai o nome do arquivo da URL pública
                    // Ex: .../app-images/1715000_abcde.jpg -> 1715000_abcde.jpg
                    if (url.includes(BUCKET_NAME)) {
                        return url.split(`${BUCKET_NAME}/`).pop();
                    }
                    return null;
                }).filter(f => f !== null && f !== undefined) as string[];

                if (filesToRemove.length > 0) {
                    console.log(`Removendo ${filesToRemove.length} imagens do storage...`);
                    const { error: storageError } = await supabase.storage
                        .from(BUCKET_NAME)
                        .remove(filesToRemove);

                    if (storageError) console.error("Erro ao apagar imagens:", storageError);
                }
            }

            // B. Deletar Registro do Banco
            const { error: dbError } = await supabase
                .from('daily_records')
                .delete()
                .eq('id', id);

            if (dbError) throw dbError;

        } catch (e) {
            console.error("Erro ao deletar do servidor (continuando exclusão local):", e);
            // Se falhar o servidor, ainda queremos apagar local para o usuário
        }
    }

    // 2. Apagar Localmente (Cache)
    await deleteLocalRecord(id);
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    // Tenta cache local primeiro para velocidade
    const localRecords = await getAllLocalRecords();
    const local = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (data) {
                const record = { ...data, _isSynced: true } as DailyRecord;
                await saveLocalRecord(record);
                return record;
            }
        } catch (e) {}
    }

    return local;
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Archive, RefreshCcw, FolderOpen, AlertCircle, User, Truck, Package, DollarSign, Cloud, WifiOff, RefreshCw, ChevronRight, Trash2 } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';
import { useRecords } from '../contexts/RecordContext';

interface RecordListProps {
  viewMode?: 'active' | 'archived';
}

const RecordList: React.FC<RecordListProps> = ({ viewMode = 'active' }) => {
  const navigate = useNavigate();
  const { records, loading, refreshRecords } = useRecords(); // Usa o contexto global
  const [filteredRecords, setFilteredRecords] = useState<DailyRecord[]>([]);
  const [filterTeam, setFilterTeam] = useState('');
  const [syncing, setSyncing] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  const handleManualSync = async () => {
    setSyncing(true);
    setErrorMsg('');
    try {
        await recordService.syncPendingRecords();
        await refreshRecords(); 
    } catch (e) {
        console.error("Sync error", e);
        setErrorMsg("Falha na sincronização.");
    } finally {
        setSyncing(false);
    }
  };

  useEffect(() => {
    // Filtra instantaneamente baseado nos dados em memória do Context
    let result = records.filter(r => {
        const isArchived = !!r.archived;
        if (viewMode === 'archived') {
            return isArchived === true;
        } else {
            return isArchived === false;
        }
    });

    if (filterTeam) {
      result = result.filter(r => r.team.toLowerCase().includes(filterTeam.toLowerCase()));
    }
    setFilteredRecords(result);
  }, [filterTeam, records, viewMode]);

  const handleToggleArchive = async (e: React.MouseEvent, record: DailyRecord) => {
    e.preventDefault(); 
    e.stopPropagation(); 
    setErrorMsg('');
    const willArchive = !record.archived;

    try {
        await recordService.update(record.id, { archived: willArchive });
        await refreshRecords();
    } catch (error: any) {
        setErrorMsg(`Falha ao atualizar: ${error?.message || 'Erro desconhecido'}`);
    }
  };

  const handleDeleteRecord = async (e: React.MouseEvent, recordId: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (window.confirm("ATENÇÃO: Isso apagará PERMANENTEMENTE o registro e todas as fotos associadas para liberar espaço. Não há como desfazer.\n\nTem certeza?")) {
        try {
            await recordService.delete(recordId);
            await refreshRecords();
        } catch (error: any) {
            alert("Erro ao excluir: " + error.message);
        }
    }
  };

  const pendingCount = records.filter(r => !r._isSynced).length;

  return (
    <div className="min-h-screen pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
        <div className="flex items-center space-x-3">
            {viewMode === 'archived' && <div className="bg-gray-200 p-2 rounded-lg text-gray-600"><Archive size={24} /></div>}
            <div>
                <h2 className="text-2xl font-bold text-gray-800">{viewMode === 'archived' ? 'Serviços Arquivados' : 'Registros Diários'}</h2>
                <p className="text-sm text-gray-500">{viewMode === 'archived' ? 'Estes registros não aparecem nas métricas.' : 'Visão geral de todas as equipes.'}</p>
            </div>
        </div>

        <div className="flex items-center space-x-2 w-full md:w-auto">
             <button 
                onClick={handleManualSync} 
                disabled={syncing}
                className={`p-2 rounded-lg border flex items-center justify-center transition-all ${pendingCount > 0 ? 'bg-orange-50 border-orange-200 text-orange-600 animate-pulse' : 'bg-white border-gray-300 text-gray-600'}`}
                title={pendingCount > 0 ? "Clique para enviar dados pendentes" : "Recarregar lista"}
             >
                <RefreshCw size={20} className={syncing ? "animate-spin" : ""} />
                {pendingCount > 0 && <span className="ml-2 text-sm font-bold">{pendingCount}</span>}
             </button>

            <div className="relative flex-1 md:flex-none">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Buscar por equipe..." 
                    value={filterTeam}
                    onChange={(e) => setFilterTeam(e.target.value)}
                    className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-primary/50 bg-white text-gray-900"
                />
            </div>
        </div>
      </div>

      {errorMsg && (
        <div className="mb-4 bg-red-50 text-red-600 p-3 rounded-lg flex items-center space-x-2 text-sm">
            <AlertCircle size={16} />
            <span>{errorMsg}</span>
        </div>
      )}

      {loading && records.length === 0 ? (
        <div className="space-y-4">
             {[1, 2, 3, 4].map(i => <div key={i} className="h-24 bg-gray-200 rounded-xl animate-pulse"/>)}
        </div>
      ) : filteredRecords.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-100 shadow-sm px-4">
            <div className="text-gray-300 mb-3 flex justify-center"><FolderOpen size={48} /></div>
            <p className="text-gray-500 font-medium">Nenhum registro encontrado.</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {filteredRecords.map(record => (
            <div 
              key={record.id}
              onClick={() => navigate(`/records/${record.id}`)}
              className={`p-5 rounded-xl shadow-sm border hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center group relative ${record.archived ? 'bg-gray-50 border-gray-200 opacity-90' : 'bg-white border-gray-100'}`}
            >
              <div className="flex-1">
                <div className="flex flex-col md:flex-row md:items-center md:space-x-3 mb-2">
                    <div className="flex items-center space-x-2 mb-1 md:mb-0">
                        <div className={`px-2 py-1 rounded text-xs font-bold uppercase tracking-wide ${record.archived ? 'bg-gray-200 text-gray-600' : 'bg-blue-50 text-primary'}`}>
                            {new Date(record.date).toLocaleDateString('pt-BR', { month: 'short', day: 'numeric' })}
                        </div>
                        <span className={`font-bold ${record.archived ? 'text-gray-500' : 'text-gray-900'}`}>{record.team}</span>
                    </div>

                    {record.created_by_email && (
                        <div className="flex items-center space-x-1 text-xs text-gray-400 bg-gray-50 px-2 py-0.5 rounded-full w-fit">
                            <User size={10} />
                            <span>{record.created_by_email.split('@')[0]}</span>
                        </div>
                    )}

                    <div className="flex items-center space-x-1 text-xs px-2 py-0.5 rounded-full w-fit">
                        {record._isSynced ? (
                            <span className="text-green-500 flex items-center space-x-1" title="Salvo na nuvem">
                                <Cloud size={12} />
                                <span className="hidden md:inline">Sincronizado</span>
                            </span>
                        ) : (
                            <span className="text-orange-500 bg-orange-50 flex items-center space-x-1 px-1 rounded" title="Salvo apenas no celular">
                                <WifiOff size={12} />
                                <span>Offline</span>
                            </span>
                        )}
                    </div>
                </div>

                <div className="flex flex-wrap gap-4 text-sm text-gray-600 mt-3 md:mt-1">
                    <div className="flex items-center space-x-1" title="Quilometragem Total">
                      <Truck size={14} />
                      <span>{record.km_total} km</span>
                    </div>
                    <div className="flex items-center space-x-1" title="Entregas Realizadas">
                      <Package size={14} />
                      <span className="text-green-600 font-medium">{record.articles_delivered}</span>
                      {record.articles_not_delivered > 0 && (
                          <span className="text-red-500 font-medium ml-1">
                            ({record.articles_not_delivered})
                          </span>
                      )}
                    </div>
                    {(record.fuel_amount > 0 || record.toll_amount > 0) && (
                        <div className="flex items-center space-x-1 text-gray-500" title="Custo Total">
                            <DollarSign size={14} />
                            <span>€{((record.fuel_amount || 0) + (record.toll_amount || 0)).toFixed(0)}</span>
                        </div>
                    )}
                </div>
              </div>

              <div className="flex items-center space-x-2 ml-4">
                 {/* Botão de Excluir apenas para Arquivados */}
                 {viewMode === 'archived' && (
                     <button 
                        onClick={(e) => handleDeleteRecord(e, record.id)}
                        className="p-2 rounded-full text-gray-300 hover:text-red-600 hover:bg-red-100 transition-colors"
                        title="Apagar Permanentemente"
                     >
                        <Trash2 size={18} />
                     </button>
                 )}

                 <button 
                    onClick={(e) => handleToggleArchive(e, record)}
                    className={`p-2 rounded-full transition-colors ${record.archived ? 'text-green-600 hover:bg-green-50' : 'text-gray-300 hover:text-red-500 hover:bg-red-50'}`}
                    title={record.archived ? "Desarquivar" : "Arquivar"}
                 >
                    {record.archived ? <RefreshCcw size={18} /> : <Archive size={18} />}
                 </button>

                 {viewMode !== 'archived' && (
                    <ChevronRight className="text-gray-300" size={20} />
                 )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default RecordList;

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const DB_NAME = 'SNavegarDB';
const DB_VERSION = 1;
const STORE_NAME = 'daily_records';
const BUCKET_NAME = 'app-images';
const OLD_STORAGE_KEY = 'snavegar_records'; // Para migração

// --- INDEXED DB HELPERS (O "Armazém Gigante") ---

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => reject("Erro ao abrir banco de dados local");

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        // Cria a "tabela" local usando 'id' como chave primária
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = (event) => {
      resolve((event.target as IDBOpenDBRequest).result);
    };
  });
};

// Salva um único registro no IndexedDB
const saveLocalRecord = async (record: DailyRecord) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put(record); 

    // IMPORTANTE: Aguarda a transação completar totalmente antes de resolver.
    // Isso garante que os dados estão no disco antes de a UI tentar lê-los.
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro na transação de salvamento local");
    request.onerror = () => reject("Erro na requisição de salvamento local");
  });
};

// Remove um registro do IndexedDB
const deleteLocalRecord = async (id: string) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.delete(id);

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro ao apagar registro local");
  });
};

// Busca todos os registros locais
const getAllLocalRecords = async (): Promise<DailyRecord[]> => {
  const db = await openDB();
  return new Promise<DailyRecord[]>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => {
        const records = request.result as DailyRecord[];
        resolve(records || []);
    };
    request.onerror = () => reject("Erro ao ler registros locais");
  });
};

// Migração: Move dados do LocalStorage (Bolso) para IndexedDB (Mochila) e limpa o bolso
const migrateLegacyData = async () => {
  const legacyData = localStorage.getItem(OLD_STORAGE_KEY);
  if (legacyData) {
    try {
      console.log("Iniciando migração de armazenamento...");
      const parsedData: DailyRecord[] = JSON.parse(legacyData);

      const db = await openDB();
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);

      parsedData.forEach(record => {
        store.put(record);
      });

      transaction.oncomplete = () => {
        console.log("Migração concluída com sucesso!");
        localStorage.removeItem(OLD_STORAGE_KEY); // Libera o localStorage
      };
    } catch (e) {
      console.error("Erro na migração de dados:", e);
    }
  }
};

// --- HELPERS GERAIS ---

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const safeFloat = (val: any): number => {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return val;
  const str = String(val).replace(',', '.').trim();
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

// Prepara o objeto para ser aceito pelo PostgreSQL sem erros
const preparePayload = (record: DailyRecord, userId: string, userEmail?: string) => {
  return {
    id: record.id,
    user_id: userId,
    created_by_email: userEmail || record.created_by_email,
    date: record.date,
    team: record.team || 'Equipe Indefinida',
    van_plate: record.van_plate || '',
    start_time: record.start_time || '00:00',
    km_start: safeFloat(record.km_start),
    km_end: safeFloat(record.km_end),
    km_total: safeFloat(record.km_total),
    articles_loaded: safeFloat(record.articles_loaded),
    articles_delivered: safeFloat(record.articles_delivered),
    articles_not_delivered: safeFloat(record.articles_not_delivered),
    reason_not_delivered: record.reason_not_delivered || '',
    fueling: !!record.fueling,
    fuel_amount: safeFloat(record.fuel_amount),
    toll_amount: safeFloat(record.toll_amount),
    attachments: record.attachments || [],
    notes: record.notes || '',
    status: record.status || 'draft',
    archived: !!record.archived,
    created_at: record.created_at || new Date().toISOString()
  };
};

// --- SERVICE ---

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
      const { data, error } = await supabase.storage.from(BUCKET_NAME).upload(fileName, file, { 
        cacheControl: '3600', 
        upsert: false 
      });
      if (error) {
        console.error("Upload Error:", error);
        return null;
      }
      const { data: publicUrlData } = supabase.storage.from(BUCKET_NAME).getPublicUrl(data.path);
      return publicUrlData.publicUrl;
    } catch (err) { 
        console.error("Upload Exception:", err);
        return null; 
    }
  },

  async processAttachmentsForSync(attachments: string[]): Promise<string[]> {
    if (!attachments || !attachments.length) return [];

    const hasBase64 = attachments.some(a => a.startsWith('data:'));
    if (!hasBase64) return attachments;

    const processed = await Promise.all(attachments.map(async (att) => {
      if (att.startsWith('data:')) {
        try {
            const res = await fetch(att);
            const blob = await res.blob();
            const url = await this.uploadImage(blob);
            return url || att; 
        } catch (e) {
            console.error("Falha ao processar imagem para sync:", e);
            return att;
        }
      }
      return att;
    }));
    return processed;
  },

  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    // Tenta migrar dados legados antes do sync, por segurança
    await migrateLegacyData();

    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) return 0;

    const user = session.user;
    const localRecords = await getAllLocalRecords();
    const pending = localRecords.filter(r => r._isSynced === false);

    if (pending.length === 0) return 0;

    console.log(`Tentando sincronizar ${pending.length} registros...`);
    let syncedCount = 0;

    for (const record of pending) {
        try {
            if (record.attachments && record.attachments.length > 0) {
                const updatedAttachments = await this.processAttachmentsForSync(record.attachments);
                record.attachments = updatedAttachments;
            }

            const payload = preparePayload(record, user.id, user.email);
            const { error } = await supabase.from('daily_records').upsert(payload);

            if (!error) {
                // Atualiza localmente para marcar como sincronizado
                const syncedRecord = { ...record, _isSynced: true };
                await saveLocalRecord(syncedRecord);
                syncedCount++;
            } else {
                console.error("Sync Error Individual:", error.message);
            }
        } catch (err) {
            console.error("Sync Exception:", err);
        }
    }

    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    await migrateLegacyData();

    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    // 2. Busca do Servidor
    if (supabase) {
      try {
        const { data, error } = await supabase
            .from('daily_records')
            .select('*')
            .order('date', { ascending: false })
            .limit(100);

        if (error) {
            console.warn("Supabase GET Error (Offline?):", error.message);
            isOffline = true;
        } else if (data) {
          serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
        }
      } catch (err) {
        isOffline = true;
      }
    }

    // 3. Busca Local
    const localRecords = await getAllLocalRecords();

    // 4. Merge Inteligente
    const finalMap = new Map<string, DailyRecord>();

    if (!isOffline) {
        // Servidor tem prioridade, mas salvamos o que vem dele no cache local
        for (const r of serverRecords) {
           finalMap.set(r.id, r);
           // Update cache in background without awaiting
           saveLocalRecord(r).catch(e => console.warn("Cache update failed", e));
        }

        // Adiciona locais que ainda não subiram
        localRecords.forEach(r => {
            if (!finalMap.has(r.id) || !r._isSynced) {
                finalMap.set(r.id, r);
            }
        });
    } else {
        // Offline: mostra tudo que tem local
        localRecords.forEach(r => finalMap.set(r.id, r));
    }

    const merged = Array.from(finalMap.values())
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return merged;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newId = generateUUID();
    const newRecord = {
      ...record,
      id: newId,
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    if (supabase) {
      try {
        const { data: { session } } = await supabase.auth.getSession();

        if (session?.user) {
          // Processa imagens se necessário
          if (newRecord.attachments && newRecord.attachments.some(a => a.startsWith('data:'))) {
             newRecord.attachments = await this.processAttachmentsForSync(newRecord.attachments);
          }

          const payload = preparePayload(newRecord, session.user.id, session.user.email);
          const { error } = await supabase.from('daily_records').insert(payload);

          if (!error) {
            newRecord._isSynced = true;
          } else {
            console.error("Supabase Create Error:", error.message);
            // Não damos throw aqui, deixamos salvar localmente com _isSynced=false
          }
        } else {
             // Sem sessão, apenas salva local (offline mode ou fallback)
             console.warn("User not logged in, saving locally only.");
        }
      } catch (err: any) {
        console.error("Create Exception:", err);
      }
    }

    // Salva Localmente Sempre e espera a transação completar
    await saveLocalRecord(newRecord);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let updatedRecord: DailyRecord | null = null;

    const localRecords = await getAllLocalRecords();
    const existing = localRecords.find(r => r.id === id);

    if (existing) {
        updatedRecord = { ...existing, ...updates, _isSynced: false };
    }

    if (supabase) {
        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                const cleanUpdates: any = { ...updates };
                delete cleanUpdates._isSynced;
                delete cleanUpdates.id;

                if (cleanUpdates.attachments && cleanUpdates.attachments.some((a:string) => a.startsWith('data:'))) {
                    cleanUpdates.attachments = await this.processAttachmentsForSync(cleanUpdates.attachments);
                    if (updatedRecord) updatedRecord.attachments = cleanUpdates.attachments;
                }

                ['km_start', 'km_end', 'km_total', 'articles_loaded', 
                 'articles_delivered', 'articles_not_delivered', 
                 'fuel_amount', 'toll_amount'].forEach(key => {
                    if (cleanUpdates[key] !== undefined) {
                        cleanUpdates[key] = safeFloat(cleanUpdates[key]);
                    }
                });

                const { error } = await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
                if (!error && updatedRecord) {
                    updatedRecord._isSynced = true;
                }
            }
        } catch (e) {
            console.error("Update DB Error:", e);
        }
    }

    if (updatedRecord) {
        await saveLocalRecord(updatedRecord);
    }

    return updatedRecord;
  },

  // HARD DELETE ÚNICO (Mantido para compatibilidade, mas redireciona para múltiplo para consistência)
  async delete(id: string): Promise<void> {
    return this.deleteMultiple([id]);
  },

  // --- OTIMIZAÇÃO: HARD DELETE EM LOTE ---
  async deleteMultiple(ids: string[]): Promise<void> {
    if (!ids || ids.length === 0) return;

    console.log(`Iniciando exclusão em lote de ${ids.length} registros...`);

    // 1. Identificar todas as imagens que precisam ser apagadas
    // Precisamos dos dados originais para saber os URLs
    let allImagesToDelete: string[] = [];

    // Tenta pegar do cache local para ser rápido
    const localRecords = await getAllLocalRecords();

    for (const id of ids) {
        const record = localRecords.find(r => r.id === id);
        if (record && record.attachments && record.attachments.length > 0) {
            record.attachments.forEach(url => {
                 if (url.includes(BUCKET_NAME)) {
                    const fileName = url.split(`${BUCKET_NAME}/`).pop();
                    if (fileName) allImagesToDelete.push(fileName);
                 }
            });
        }
    }

    if (supabase) {
        try {
            // A. Batch Delete Images (Uma única requisição para N imagens)
            if (allImagesToDelete.length > 0) {
                console.log(`Removendo ${allImagesToDelete.length} imagens do storage (Batch)...`);
                // Supabase permite deletar array de arquivos
                const { error: storageError } = await supabase.storage
                    .from(BUCKET_NAME)
                    .remove(allImagesToDelete);

                if (storageError) console.error("Erro Batch Storage:", storageError);
            }

            // B. Batch Delete Records no DB (Uma única query 'in')
            const { error: dbError } = await supabase
                .from('daily_records')
                .delete()
                .in('id', ids); // WHERE id IN (1, 2, 3...)

            if (dbError) throw dbError;

        } catch (e) {
            console.error("Erro ao deletar lote do servidor:", e);
        }
    }

    // 2. Apagar Localmente (Cache) - Loop é rápido localmente
    for (const id of ids) {
        await deleteLocalRecord(id);
    }

    console.log("Exclusão em lote concluída.");
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    // Tenta cache local primeiro para velocidade
    const localRecords = await getAllLocalRecords();
    const local = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (data) {
                const record = { ...data, _isSynced: true } as DailyRecord;
                await saveLocalRecord(record);
                return record;
            }
        } catch (e) {}
    }

    return local;
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Archive, RefreshCcw, FolderOpen, AlertCircle, User, Truck, Package, DollarSign, Cloud, WifiOff, RefreshCw, ChevronRight, Trash2, CheckSquare, Square, X, Check } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';
import { useRecords } from '../contexts/RecordContext';

interface RecordListProps {
  viewMode?: 'active' | 'archived';
}

const RecordList: React.FC<RecordListProps> = ({ viewMode = 'active' }) => {
  const navigate = useNavigate();
  const { records, loading, refreshRecords } = useRecords();
  const [filteredRecords, setFilteredRecords] = useState<DailyRecord[]>([]);
  const [filterTeam, setFilterTeam] = useState('');
  const [syncing, setSyncing] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Estados para Seleção Múltipla
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const handleManualSync = async () => {
    setSyncing(true);
    setErrorMsg('');
    try {
        await recordService.syncPendingRecords();
        await refreshRecords(); 
    } catch (e) {
        console.error("Sync error", e);
        setErrorMsg("Falha na sincronização.");
    } finally {
        setSyncing(false);
    }
  };

  useEffect(() => {
    // Sai do modo de seleção se mudar de aba
    setIsSelectionMode(false);
    setSelectedIds(new Set());

    let result = records.filter(r => {
        const isArchived = !!r.archived;
        if (viewMode === 'archived') {
            return isArchived === true;
        } else {
            return isArchived === false;
        }
    });

    if (filterTeam) {
      result = result.filter(r => r.team.toLowerCase().includes(filterTeam.toLowerCase()));
    }
    setFilteredRecords(result);
  }, [filterTeam, records, viewMode]);

  const handleToggleArchive = async (e: React.MouseEvent, record: DailyRecord) => {
    e.preventDefault(); 
    e.stopPropagation(); 
    setErrorMsg('');
    const willArchive = !record.archived;

    try {
        await recordService.update(record.id, { archived: willArchive });
        await refreshRecords();
    } catch (error: any) {
        setErrorMsg(`Falha ao atualizar: ${error?.message || 'Erro desconhecido'}`);
    }
  };

  const handleDeleteRecord = async (e: React.MouseEvent, recordId: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (window.confirm("ATENÇÃO: Isso apagará PERMANENTEMENTE o registro e todas as fotos associadas. Não há como desfazer.\n\nTem certeza?")) {
        try {
            await recordService.delete(recordId);
            await refreshRecords();
        } catch (error: any) {
            alert("Erro ao excluir: " + error.message);
        }
    }
  };

  // --- LÓGICA DE SELEÇÃO EM LOTE ---

  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set());
  };

  const toggleSelectRecord = (id: string) => {
    const newSelection = new Set(selectedIds);
    if (newSelection.has(id)) {
        newSelection.delete(id);
    } else {
        newSelection.add(id);
    }
    setSelectedIds(newSelection);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === filteredRecords.length) {
        setSelectedIds(new Set());
    } else {
        const allIds = new Set(filteredRecords.map(r => r.id));
        setSelectedIds(allIds);
    }
  };

  const handleBulkDelete = async () => {
    const count = selectedIds.size;
    if (count === 0) return;

    if (window.confirm(`ATENÇÃO: Você está prestes a apagar ${count} registros PERMANENTEMENTE e todas as fotos associadas a eles.\n\nEsta ação liberará espaço, mas não pode ser desfeita.\n\nConfirmar exclusão em massa?`)) {
        setSyncing(true); // Reusa o loading state
        try {
            await recordService.deleteMultiple(Array.from(selectedIds));
            await refreshRecords();
            setIsSelectionMode(false);
            setSelectedIds(new Set());
        } catch (e: any) {
            alert("Erro na exclusão em massa: " + e.message);
        } finally {
            setSyncing(false);
        }
    }
  };

  const pendingCount = records.filter(r => !r._isSynced).length;

  return (
    <div className="min-h-screen pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
        <div className="flex items-center space-x-3">
            {viewMode === 'archived' && <div className="bg-gray-200 p-2 rounded-lg text-gray-600"><Archive size={24} /></div>}
            <div>
                <h2 className="text-2xl font-bold text-gray-800">{viewMode === 'archived' ? 'Serviços Arquivados' : 'Registros Diários'}</h2>
                <p className="text-sm text-gray-500">{viewMode === 'archived' ? 'Estes registros não aparecem nas métricas.' : 'Visão geral de todas as equipes.'}</p>
            </div>
        </div>

        <div className="flex items-center space-x-2 w-full md:w-auto">

            {/* Botão de Seleção (Apenas para Arquivados e se houver itens) */}
            {viewMode === 'archived' && filteredRecords.length > 0 && (
                <button 
                    onClick={toggleSelectionMode}
                    className={`p-2 rounded-lg border flex items-center justify-center transition-colors ${isSelectionMode ? 'bg-blue-100 border-blue-300 text-blue-700' : 'bg-white border-gray-300 text-gray-600'}`}
                    title={isSelectionMode ? "Cancelar Seleção" : "Gerenciar Itens"}
                >
                    {isSelectionMode ? <X size={20} /> : <CheckSquare size={20} />}
                    <span className="ml-2 text-sm font-medium hidden md:inline">{isSelectionMode ? "Cancelar" : "Selecionar"}</span>
                </button>
            )}

            {!isSelectionMode && (
                <>
                    <button 
                        onClick={handleManualSync} 
                        disabled={syncing}
                        className={`p-2 rounded-lg border flex items-center justify-center transition-all ${pendingCount > 0 ? 'bg-orange-50 border-orange-200 text-orange-600 animate-pulse' : 'bg-white border-gray-300 text-gray-600'}`}
                        title={pendingCount > 0 ? "Clique para enviar dados pendentes" : "Recarregar lista"}
                    >
                        <RefreshCw size={20} className={syncing ? "animate-spin" : ""} />
                        {pendingCount > 0 && <span className="ml-2 text-sm font-bold">{pendingCount}</span>}
                    </button>

                    <div className="relative flex-1 md:flex-none">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="Buscar por equipe..." 
                            value={filterTeam}
                            onChange={(e) => setFilterTeam(e.target.value)}
                            className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-primary/50 bg-white text-gray-900"
                        />
                    </div>
                </>
            )}
        </div>
      </div>

      {/* Barra de Ferramentas de Seleção */}
      {isSelectionMode && (
        <div className="bg-blue-50 border border-blue-100 p-3 rounded-xl mb-4 flex justify-between items-center animate-fade-in shadow-sm sticky top-0 z-10">
            <div className="flex items-center space-x-3">
                <button 
                    onClick={toggleSelectAll}
                    className="flex items-center space-x-2 text-blue-700 font-medium hover:bg-blue-100 px-3 py-1.5 rounded-lg transition-colors"
                >
                    {selectedIds.size === filteredRecords.length && filteredRecords.length > 0 ? <CheckSquare size={20} /> : <Square size={20} />}
                    <span>{selectedIds.size === filteredRecords.length ? "Desmarcar Todos" : "Selecionar Todos"}</span>
                </button>
                <span className="text-sm text-blue-600 font-semibold border-l border-blue-200 pl-3">
                    {selectedIds.size} selecionado(s)
                </span>
            </div>

            <button
                onClick={handleBulkDelete}
                disabled={selectedIds.size === 0 || syncing}
                className={`flex items-center space-x-2 px-4 py-2 rounded-lg font-bold text-white transition-all shadow-md ${
                    selectedIds.size > 0 && !syncing
                        ? 'bg-red-500 hover:bg-red-600' 
                        : 'bg-gray-300 cursor-not-allowed'
                }`}
            >
                {syncing ? <RefreshCw size={18} className="animate-spin" /> : <Trash2 size={18} />}
                <span>Apagar Selecionados</span>
            </button>
        </div>
      )}

      {errorMsg && (
        <div className="mb-4 bg-red-50 text-red-600 p-3 rounded-lg flex items-center space-x-2 text-sm">
            <AlertCircle size={16} />
            <span>{errorMsg}</span>
        </div>
      )}

      {loading && records.length === 0 ? (
        <div className="space-y-4">
             {[1, 2, 3, 4].map(i => <div key={i} className="h-24 bg-gray-200 rounded-xl animate-pulse"/>)}
        </div>
      ) : filteredRecords.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-100 shadow-sm px-4">
            <div className="text-gray-300 mb-3 flex justify-center"><FolderOpen size={48} /></div>
            <p className="text-gray-500 font-medium">Nenhum registro encontrado.</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {filteredRecords.map(record => (
            <div 
              key={record.id}
              onClick={() => {
                if (isSelectionMode) {
                    toggleSelectRecord(record.id);
                } else {
                    navigate(`/records/${record.id}`);
                }
              }}
              className={`p-5 rounded-xl shadow-sm border transition-all cursor-pointer flex justify-between items-center group relative
                ${record.archived ? 'bg-gray-50 border-gray-200 opacity-90' : 'bg-white border-gray-100'}
                ${isSelectionMode && selectedIds.has(record.id) ? 'ring-2 ring-blue-500 bg-blue-50' : ''}
              `}
            >
              {/* Checkbox de Seleção (Lado Esquerdo) */}
              {isSelectionMode && (
                <div className="mr-4 text-blue-500">
                    {selectedIds.has(record.id) ? <CheckSquare size={24} className="fill-blue-500 text-white" /> : <Square size={24} className="text-gray-300" />}
                </div>
              )}

              <div className="flex-1">
                <div className="flex flex-col md:flex-row md:items-center md:space-x-3 mb-2">
                    <div className="flex items-center space-x-2 mb-1 md:mb-0">
                        <div className={`px-2 py-1 rounded text-xs font-bold uppercase tracking-wide ${record.archived ? 'bg-gray-200 text-gray-600' : 'bg-blue-50 text-primary'}`}>
                            {new Date(record.date).toLocaleDateString('pt-BR', { month: 'short', day: 'numeric' })}
                        </div>
                        <span className={`font-bold ${record.archived ? 'text-gray-500' : 'text-gray-900'}`}>{record.team}</span>
                    </div>

                    {record.created_by_email && (
                        <div className="flex items-center space-x-1 text-xs text-gray-400 bg-gray-50 px-2 py-0.5 rounded-full w-fit">
                            <User size={10} />
                            <span>{record.created_by_email.split('@')[0]}</span>
                        </div>
                    )}

                    <div className="flex items-center space-x-1 text-xs px-2 py-0.5 rounded-full w-fit">
                        {record._isSynced ? (
                            <span className="text-green-500 flex items-center space-x-1" title="Salvo na nuvem">
                                <Cloud size={12} />
                                <span className="hidden md:inline">Sincronizado</span>
                            </span>
                        ) : (
                            <span className="text-orange-500 bg-orange-50 flex items-center space-x-1 px-1 rounded" title="Salvo apenas no celular">
                                <WifiOff size={12} />
                                <span>Offline</span>
                            </span>
                        )}
                    </div>
                </div>

                <div className="flex flex-wrap gap-4 text-sm text-gray-600 mt-3 md:mt-1">
                    <div className="flex items-center space-x-1" title="Quilometragem Total">
                      <Truck size={14} />
                      <span>{record.km_total} km</span>
                    </div>
                    <div className="flex items-center space-x-1" title="Entregas Realizadas">
                      <Package size={14} />
                      <span className="text-green-600 font-medium">{record.articles_delivered}</span>
                      {record.articles_not_delivered > 0 && (
                          <span className="text-red-500 font-medium ml-1">
                            ({record.articles_not_delivered})
                          </span>
                      )}
                    </div>
                </div>
              </div>

              {/* Controles da Direita (Ocultos no modo de seleção para limpar a tela) */}
              {!isSelectionMode && (
                  <div className="flex items-center space-x-2 ml-4">
                     {/* Botão de Excluir apenas para Arquivados */}
                     {viewMode === 'archived' && (
                         <button 
                            onClick={(e) => handleDeleteRecord(e, record.id)}
                            className="p-2 rounded-full text-gray-300 hover:text-red-600 hover:bg-red-100 transition-colors"
                            title="Apagar Permanentemente"
                         >
                            <Trash2 size={18} />
                         </button>
                     )}

                     <button 
                        onClick={(e) => handleToggleArchive(e, record)}
                        className={`p-2 rounded-full transition-colors ${record.archived ? 'text-green-600 hover:bg-green-50' : 'text-gray-300 hover:text-red-500 hover:bg-red-50'}`}
                        title={record.archived ? "Desarquivar" : "Arquivar"}
                     >
                        {record.archived ? <RefreshCcw size={18} /> : <Archive size={18} />}
                     </button>

                     {viewMode !== 'archived' && (
                        <ChevronRight className="text-gray-300" size={20} />
                     )}
                  </div>
              )}
            </div>
          ))}
        </div>
      )}
      <style>{`
        .animate-fade-in {
            animation: fadeIn 0.3s ease-out;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(-5px); }
            to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

