                        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"><Calendar size={14} /></span>
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="pl-8 pr-2 py-1.5 rounded-lg border border-gray-300 text-sm w-full focus:ring-2 focus:ring-primary/50 outline-none"
                        />
                    </div>
                    <span className="text-gray-400 font-medium">até</span>
                    <div className="relative flex-1 md:flex-none">
                        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"><Calendar size={14} /></span>
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="pl-8 pr-2 py-1.5 rounded-lg border border-gray-300 text-sm w-full focus:ring-2 focus:ring-primary/50 outline-none"
                        />
                    </div>
                </div>

                {/* Botões de Atalho */}
                <div className="flex gap-2 w-full md:w-auto overflow-x-auto no-scrollbar pb-1 md:pb-0">
                    <button onClick={handleSetLast7Days} className="quick-filter-btn">7 Dias</button>
                    <button onClick={handleSetThisMonth} className="quick-filter-btn">Este Mês</button>
                    <button onClick={handleSetLastMonth} className="quick-filter-btn">Mês Passado</button>
                </div>
            </div>

            {/* Linha 2: Seleção de Equipe */}
