            {/* KPI Cards */}
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4 animate-fade-in">
                <KPICard label="Entregas" value={totalDeliveries} color="text-green-600" />
                <KPICard label="Falhas" value={totalFailed} color="text-red-500" />
                <KPICard label="KM Total" value={`${totalKm} km`} color="text-blue-600" />
                <KPICard label="Despesas" value={`€${totalCost.toFixed(0)}`} color="text-purple-600" />
                <KPICard label="Sucatas" value={totalScraps} color="text-orange-600" />
            </div>

            {/* Charts */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fade-in">

                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="font-semibold text-gray-700 mb-4 text-sm uppercase tracking-wide">Volume de Entregas</h3>
                    <div className="h-64">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={chartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                                <XAxis 
                                    dataKey="date" 
                                    axisLine={false} 
                                    tickLine={false} 
                                    fontSize={11} 
                                    tick={{fill: '#9ca3af'}}
                                    interval={chartData.length > 10 ? 'preserveStartEnd' : 0} // Evita sobreposição se tiver muitos dias
                                />
                                <Tooltip 
                                    contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                                    labelStyle={{ fontWeight: 'bold', color: '#374151' }}
                                />
                                <Bar dataKey="delivered" fill="#22c55e" radius={[4, 4, 0, 0]} name="Entregues" stackId="a" />
                                <Bar dataKey="failed" fill="#ef4444" radius={[4, 4, 0, 0]} name="Falhas" stackId="a" />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="font-semibold text-gray-700 mb-4 text-sm uppercase tracking-wide">Evolução KM</h3>
                    <div className="h-64">
                        <ResponsiveContainer width="100%" height="100%">
                            <LineChart data={chartData}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                                <XAxis 
                                    dataKey="date" 
                                    axisLine={false} 
                                    tickLine={false} 
                                    fontSize={11} 
                                    tick={{fill: '#9ca3af'}}
                                    interval={chartData.length > 10 ? 'preserveStartEnd' : 0}
                                />
                                <Tooltip 
                                    contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
                                    labelStyle={{ fontWeight: 'bold', color: '#374151' }}
                                />
                                <Line 
                                    type="monotone" 
                                    dataKey="km" 
                                    stroke="#2563eb" 
                                    strokeWidth={3} 
                                    dot={{r: 3, fill: '#2563eb', strokeWidth: 0}} 
                                    activeDot={{r: 6}}
                                    name="Quilômetros" 
                                />
                            </LineChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
          </>
      )}

      <style>{`
        .quick-filter-btn {
            padding: 0.35rem 0.75rem;
            background-color: #ffffff;
            border: 1px solid #e5e7eb;
            border-radius: 0.5rem;
            font-size: 0.75rem;
            font-weight: 500;
            color: #4b5563;
            white-space: nowrap;
            transition: all;
        }
        .quick-filter-btn:hover {
            background-color: #f3f4f6;
            color: #111827;
        }

        .team-filter-btn {
            padding: 0.5rem 1rem;
            border-radius: 0.5rem;
            font-size: 0.875rem;
            font-weight: 500;
            white-space: nowrap;
            transition: all;
            color: #4b5563;
        }
        .team-filter-btn:hover {
            background-color: #f3f4f6;
        }
        .team-filter-btn.active {
            background-color: #2563eb;
            color: white;
            box-shadow: 0 4px 6px -1px rgba(37, 99, 235, 0.2);
        }

        .animate-fade-in {
            animation: fadeIn 0.4s ease-out;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

const KPICard = ({ label, value, color }: { label: string, value: string | number, color: string }) => (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col items-center justify-center text-center hover:shadow-md transition-shadow">
        <span className="text-gray-400 text-xs font-medium uppercase tracking-wider mb-1">{label}</span>
        <span className={`text-xl md:text-2xl font-bold ${color}`}>{value}</span>
    </div>
);

export default Analytics;

