import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Login from './pages/Login';
import Home from './pages/Home';
import RecordForm from './pages/RecordForm';
import RecordList from './pages/RecordList';
import RecordDetail from './pages/RecordDetail';
import Analytics from './pages/Analytics';
import { supabase } from './services/supabaseClient';
import { RecordProvider } from './contexts/RecordContext';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check active session
    const checkSession = async () => {
        try {
            if (supabase) {
                // Cria uma promessa de timeout de 5 segundos
                // Se o Supabase demorar demais, nós liberamos a tela
                const timeoutPromise = new Promise((_, reject) => 
                    setTimeout(() => reject(new Error("Timeout checking session")), 5000)
                );

                const sessionPromise = supabase.auth.getSession();

                // Corrida: quem chegar primeiro ganha (Dados ou Timeout)
                const result = await Promise.race([sessionPromise, timeoutPromise]) as any;

                if (result && result.data && result.data.session) {
                    setIsAuthenticated(true);
                } else {
                    setIsAuthenticated(false);
                }
            } else {
                 // Fallback for demo without Supabase keys
                 const localAuth = localStorage.getItem('snavegar_auth');
                 if (localAuth) setIsAuthenticated(true);
            }
        } catch (error) {
            console.error("Erro ou Timeout na verificação de sessão:", error);
            // Em caso de erro (ex: offline total no boot), assumimos não logado
            // para permitir que a UI carregue e o usuário tente logar ou usar offline
            setIsAuthenticated(false); 
        } finally {
            // O MAIS IMPORTANTE: Sempre remover o loading, aconteça o que acontecer
            setLoading(false);
        }
    };

    checkSession();

    // Listen for auth changes
    const { data: authListener } = supabase?.auth.onAuthStateChange((_event, session) => {
        setIsAuthenticated(!!session);
    }) || { data: { subscription: { unsubscribe: () => {} } } };

    return () => {
        authListener.subscription.unsubscribe();
    };
  }, []);

  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = async () => {
    if (supabase) {
        await supabase.auth.signOut();
    } else {
        localStorage.removeItem('snavegar_auth');
    }
    setIsAuthenticated(false);
  };

  if (loading) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 text-primary animate-pulse">
            <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
            <span className="font-semibold">Iniciando SNavegar...</span>
        </div>
      );
  }

  return (
    <HashRouter>
      <RecordProvider>
        <Routes>
          <Route 
            path="/login" 
            element={!isAuthenticated ? <Login onLogin={handleLogin} /> : <Navigate to="/" />} 
          />

          <Route
            path="/*"
            element={
              isAuthenticated ? (
                <Layout onLogout={handleLogout}>
                  <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/create" element={<RecordForm />} />
                    <Route path="/records" element={<RecordList viewMode="active" />} />
                    <Route path="/archived" element={<RecordList viewMode="archived" />} />
                    <Route path="/records/:id" element={<RecordDetail />} />
                    <Route path="/records/:id/edit" element={<RecordForm />} />
                    <Route path="/analytics" element={<Analytics />} />
                    <Route path="*" element={<Navigate to="/" />} />
                  </Routes>
                </Layout>
              ) : (
                <Navigate to="/login" />
              )
            }
          />
        </Routes>
      </RecordProvider>
    </HashRouter>
  );
};

export default App;

const CACHE_NAME = 'snavegar-v10-fix-boot'; 
const urlsToCache = [
  './',
  './index.html',
  './manifest.json',
  './icon.svg'
];

// Domínios que devem ser ignorados pelo Service Worker
// para garantir acesso direto à rede sem interceptação.
const NETWORK_ONLY_DOMAINS = [
  'generativelanguage.googleapis.com', // Google Gemini API
  'supabase.co'                        // Supabase API
];

self.addEventListener('install', event => {
  // Força o novo SW a ativar imediatamente, substituindo o antigo
  self.skipWaiting();

  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);

  // Verifica se é uma requisição de API externa
  const isNetworkOnly = NETWORK_ONLY_DOMAINS.some(domain => url.hostname.includes(domain));

  if (isNetworkOnly) {
    // CORREÇÃO CRÍTICA PWA:
    // Retornar cedo sem chamar event.respondWith() instrui o navegador a
    // usar a pilha de rede nativa. Isso evita que o SW interfira em corpos POST,
    // headers de Auth ou streams, que costumam falhar quando interceptados no PWA.
    return;
  }

  // Cache-First para arquivos estáticos da UI
  event.respondWith(
    caches.match(event.request)
      .then(response => response || fetch(event.request))
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    Promise.all([
      // Limpa caches antigos
      caches.keys().then(cacheNames => {
        return Promise.all(
          cacheNames.map(cacheName => {
            if (cacheName !== CACHE_NAME) {
              return caches.delete(cacheName);
            }
          })
        );
      }),
      // Assume o controle dos clientes imediatamente
      self.clients.claim()
    ])
  );
});

