import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Login from './pages/Login';
import Home from './pages/Home';
import RecordForm from './pages/RecordForm';
import RecordList from './pages/RecordList';
import RecordDetail from './pages/RecordDetail';
import Analytics from './pages/Analytics';
import { supabase } from './services/supabaseClient';
import { RecordProvider } from './contexts/RecordContext';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;

    // 1. WATCHDOG (CÃO DE GUARDA) DE SEGURANÇA
    // Se a verificação do Supabase travar ou a internet cair,
    // este timer garante que o loading desapareça em 3 segundos.
    const watchdog = setTimeout(() => {
        if (mounted && loading) {
            console.warn("⚠️ Watchdog: Tempo limite excedido. Forçando abertura do App.");
            setLoading(false); 
            // Se falhou por timeout, mantemos isAuthenticated como false (padrão),
            // levando o usuário para o Login (fail-safe).
        }
    }, 3000);

    // 2. Verificação de Sessão Real
    const checkSession = async () => {
        try {
            // Verifica se o cliente existe
            if (!supabase) throw new Error("Cliente Supabase não inicializado");

            // Tenta obter a sessão
            const { data, error } = await supabase.auth.getSession();

            if (error) throw error;

            // Se tiver sucesso e o componente ainda estiver montado
            if (mounted) {
                if (data.session) {
                    setIsAuthenticated(true);
                } else {
                    // Token inválido ou expirado
                    setIsAuthenticated(false);
                }
            }
        } catch (error) {
            console.error("Erro na verificação de sessão (App Offline?):", error);
            // Em caso de erro, assume deslogado para permitir acesso à tela de login
            if (mounted) setIsAuthenticated(false);
        } finally {
            // Se a verificação terminar ANTES do watchdog (cenário ideal),
            // limpamos o timer e paramos o loading.
            if (mounted) {
                clearTimeout(watchdog);
                setLoading(false);
            }
        }
    };

    checkSession();

    // 3. Listener de Mudança de Autenticação (Login/Logout em tempo real)
    const { data: authListener } = supabase?.auth.onAuthStateChange((_event, session) => {
        if (mounted) {
            setIsAuthenticated(!!session);
        }
    }) || { data: { subscription: { unsubscribe: () => {} } } };

    return () => {
        mounted = false;
        clearTimeout(watchdog);
        authListener.subscription.unsubscribe();
    };
  }, []);

  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = async () => {
    try {
        if (supabase) await supabase.auth.signOut();
    } catch (e) {
        console.error("Erro ao sair:", e);
    }
    localStorage.removeItem('snavegar_auth');
    setIsAuthenticated(false);
  };

  if (loading) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 text-primary animate-pulse">
            <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
            <span className="font-semibold text-sm tracking-wide">Iniciando sistema...</span>
        </div>
      );
  }

  return (
    <HashRouter>
      <RecordProvider>
        <Routes>
          <Route 
            path="/login" 
            element={!isAuthenticated ? <Login onLogin={handleLogin} /> : <Navigate to="/" />} 
          />

          <Route
            path="/*"
            element={
              isAuthenticated ? (
                <Layout onLogout={handleLogout}>
                  <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/create" element={<RecordForm />} />
                    <Route path="/records" element={<RecordList viewMode="active" />} />
                    <Route path="/archived" element={<RecordList viewMode="archived" />} />
                    <Route path="/records/:id" element={<RecordDetail />} />
                    <Route path="/records/:id/edit" element={<RecordForm />} />
                    <Route path="/analytics" element={<Analytics />} />
                    <Route path="*" element={<Navigate to="/" />} />
                  </Routes>
                </Layout>
              ) : (
                <Navigate to="/login" />
              )
            }
          />
        </Routes>
      </RecordProvider>
    </HashRouter>
  );
};

