const CACHE_NAME = 'snavegar-v12-emergency-boot'; 
const urlsToCache = [
  './',
  './index.html',
  './manifest.json',
  './icon.svg'
];

// Domínios que devem ser ignorados pelo Service Worker
// para garantir acesso direto à rede sem interceptação.
const NETWORK_ONLY_DOMAINS = [
  'generativelanguage.googleapis.com', // Google Gemini API
  'supabase.co'                        // Supabase API
];

self.addEventListener('install', event => {
  // Força o novo SW a ativar imediatamente, substituindo o antigo
  self.skipWaiting();

  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);

  // Verifica se é uma requisição de API externa
  const isNetworkOnly = NETWORK_ONLY_DOMAINS.some(domain => url.hostname.includes(domain));

  if (isNetworkOnly) {
    // CORREÇÃO CRÍTICA PWA:
    // Retornar cedo sem chamar event.respondWith() instrui o navegador a
    // usar a pilha de rede nativa. Isso evita que o SW interfira em corpos POST,
    // headers de Auth ou streams, que costumam falhar quando interceptados no PWA.
    return;
  }

  // Cache-First para arquivos estáticos da UI
  event.respondWith(
    caches.match(event.request)
      .then(response => response || fetch(event.request))
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    Promise.all([
      // Limpa caches antigos
      caches.keys().then(cacheNames => {
        return Promise.all(
          cacheNames.map(cacheName => {
            if (cacheName !== CACHE_NAME) {
              console.log('Apagando cache antigo:', cacheName);
              return caches.delete(cacheName);
            }
          })
        );
      }),
      // Assume o controle dos clientes imediatamente
      self.clients.claim()
    ])
  );
});

import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const DB_NAME = 'SNavegarDB';
const DB_VERSION = 1;
const STORE_NAME = 'daily_records';
const BUCKET_NAME = 'app-images';
const OLD_STORAGE_KEY = 'snavegar_records'; // Para migração

// --- INDEXED DB HELPERS (O "Armazém Gigante") ---

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => reject("Erro ao abrir banco de dados local");

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        // Cria a "tabela" local usando 'id' como chave primária
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = (event) => {
      resolve((event.target as IDBOpenDBRequest).result);
    };
  });
};

// Salva um único registro no IndexedDB
const saveLocalRecord = async (record: DailyRecord) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put(record); 

    // IMPORTANTE: Aguarda a transação completar totalmente antes de resolver.
    // Isso garante que os dados estão no disco antes de a UI tentar lê-los.
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro na transação de salvamento local");
    request.onerror = () => reject("Erro na requisição de salvamento local");
  });
};

// Remove um registro do IndexedDB
const deleteLocalRecord = async (id: string) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.delete(id);

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro ao apagar registro local");
  });
};

// Busca todos os registros locais
const getAllLocalRecords = async (): Promise<DailyRecord[]> => {
  const db = await openDB();
  return new Promise<DailyRecord[]>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => {
        const records = request.result as DailyRecord[];
        resolve(records || []);
    };
    request.onerror = () => reject("Erro ao ler registros locais");
  });
};

// Migração: Move dados do LocalStorage (Bolso) para IndexedDB (Mochila) e limpa o bolso
const migrateLegacyData = async () => {
  const legacyData = localStorage.getItem(OLD_STORAGE_KEY);
  if (legacyData) {
    try {
      console.log("Iniciando migração de armazenamento...");
      const parsedData: DailyRecord[] = JSON.parse(legacyData);

      const db = await openDB();
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);

      parsedData.forEach(record => {
        store.put(record);
      });

      transaction.oncomplete = () => {
        console.log("Migração concluída com sucesso!");
        localStorage.removeItem(OLD_STORAGE_KEY); // Libera o localStorage
      };
    } catch (e) {
      console.error("Erro na migração de dados:", e);
    }
  }
};

// --- HELPERS GERAIS ---

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const safeFloat = (val: any): number => {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return val;
  const str = String(val).replace(',', '.').trim();
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

// Prepara o objeto para ser aceito pelo PostgreSQL sem erros
const preparePayload = (record: DailyRecord, userId: string, userEmail?: string) => {
  return {
    id: record.id,
    user_id: userId,
    created_by_email: userEmail || record.created_by_email,
    date: record.date,
    team: record.team || 'Equipe Indefinida',
    van_plate: record.van_plate || '',
    start_time: record.start_time || '00:00',
    km_start: safeFloat(record.km_start),
    km_end: safeFloat(record.km_end),
    km_total: safeFloat(record.km_total),
    articles_loaded: safeFloat(record.articles_loaded),
    articles_delivered: safeFloat(record.articles_delivered),
    articles_not_delivered: safeFloat(record.articles_not_delivered),
    reason_not_delivered: record.reason_not_delivered || '',

    // Novos campos de sucata
    scraps_collected: safeFloat(record.scraps_collected),
    scrap_client_names: record.scrap_client_names || '',

    fueling: !!record.fueling,
    fuel_amount: safeFloat(record.fuel_amount),
    toll_amount: safeFloat(record.toll_amount),
    attachments: record.attachments || [],
    notes: record.notes || '',
    status: record.status || 'draft',
    archived: !!record.archived,
    created_at: record.created_at || new Date().toISOString()
  };
};

// --- SERVICE ---

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
      const { data, error } = await supabase.storage.from(BUCKET_NAME).upload(fileName, file, { 
        cacheControl: '3600', 
        upsert: false 
      });
      if (error) {
        console.error("Upload Error:", error);
        return null;
      }
      const { data: publicUrlData } = supabase.storage.from(BUCKET_NAME).getPublicUrl(data.path);
      return publicUrlData.publicUrl;
    } catch (err) { 
        console.error("Upload Exception:", err);
        return null; 
    }
  },

  async processAttachmentsForSync(attachments: string[]): Promise<string[]> {
    if (!attachments || !attachments.length) return [];

    const hasBase64 = attachments.some(a => a.startsWith('data:'));
    if (!hasBase64) return attachments;

    const processed = await Promise.all(attachments.map(async (att) => {
      if (att.startsWith('data:')) {
        try {
            const res = await fetch(att);
            const blob = await res.blob();
            const url = await this.uploadImage(blob);
            return url || att; 
        } catch (e) {
            console.error("Falha ao processar imagem para sync:", e);
            return att;
        }
      }
      return att;
    }));
    return processed;
  },

  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    // Tenta migrar dados legados antes do sync, por segurança
    await migrateLegacyData();

    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) return 0;

    const user = session.user;
    const localRecords = await getAllLocalRecords();
    const pending = localRecords.filter(r => r._isSynced === false);

    if (pending.length === 0) return 0;

    console.log(`Tentando sincronizar ${pending.length} registros...`);
    let syncedCount = 0;

    for (const record of pending) {
        try {
            if (record.attachments && record.attachments.length > 0) {
                const updatedAttachments = await this.processAttachmentsForSync(record.attachments);
                record.attachments = updatedAttachments;
            }

            const payload = preparePayload(record, user.id, user.email);
            const { error } = await supabase.from('daily_records').upsert(payload);

            if (!error) {
                // Atualiza localmente para marcar como sincronizado
                const syncedRecord = { ...record, _isSynced: true };
                await saveLocalRecord(syncedRecord);
                syncedCount++;
            } else {
                console.error("Sync Error Individual:", error.message);
            }
        } catch (err) {
            console.error("Sync Exception:", err);
        }
    }

    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    await migrateLegacyData();

    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    // 2. Busca do Servidor
    if (supabase) {
      try {
        // FORÇA REFRESH DA SESSÃO: Garante que temos o token atualizado para ler o DB
        const { data: sessionData } = await supabase.auth.getSession();

        if (!sessionData.session) {
             console.warn("Sem sessão ativa no Supabase ao buscar dados. Buscando apenas local.");
             // Não setamos isOffline=true aqui imediatamente, deixamos tentar o local
             isOffline = true;
        } else {
            // BUSCA DO SERVIDOR COM LIMITE AUMENTADO PARA 1000
            const { data, error } = await supabase
                .from('daily_records')
                .select('*')
                .order('date', { ascending: false })
                .limit(1000); // Garante que vemos todos os registros recentes da equipe

            if (error) {
                console.warn("Supabase GET Error:", error.message);
                isOffline = true;
            } else if (data) {
                console.log(`Baixados ${data.length} registros da nuvem.`);
                serverRecords = data.map(r => ({ ...r, _isSynced: true })) as DailyRecord[];
            }
        }
      } catch (err) {
        console.error("Exceção na busca do servidor:", err);
        isOffline = true;
      }
    }

    // 3. Busca Local
    const localRecords = await getAllLocalRecords();

    // 4. Merge Inteligente
    const finalMap = new Map<string, DailyRecord>();

    if (!isOffline && serverRecords.length > 0) {
        // Servidor tem prioridade (single source of truth)
        for (const r of serverRecords) {
           finalMap.set(r.id, r);
           // Atualiza cache silenciosamente
           saveLocalRecord(r).catch(e => console.warn("Cache update failed", e));
        }

        // Adiciona locais que ainda não subiram (rascunhos ou offline pendentes)
        localRecords.forEach(r => {
            // Se não existe no mapa (não veio do servidor) OU se a versão local não está sincronizada (tem mudanças recentes)
            if (!finalMap.has(r.id) || r._isSynced === false) {
                finalMap.set(r.id, r);
            }
        });
    } else {
        // Offline ou erro no servidor: mostra tudo que tem local
        console.log("Exibindo dados offline/cache.");
        localRecords.forEach(r => finalMap.set(r.id, r));
    }

    const merged = Array.from(finalMap.values())
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return merged;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newId = generateUUID();
    const newRecord = {
      ...record,
      id: newId,
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    if (supabase) {
      try {
        const { data: { session } } = await supabase.auth.getSession();

        if (session?.user) {
          // Processa imagens se necessário
          if (newRecord.attachments && newRecord.attachments.some(a => a.startsWith('data:'))) {
             newRecord.attachments = await this.processAttachmentsForSync(newRecord.attachments);
          }

          const payload = preparePayload(newRecord, session.user.id, session.user.email);
          const { error } = await supabase.from('daily_records').insert(payload);

          if (!error) {
            newRecord._isSynced = true;
          } else {
            console.error("Supabase Create Error:", error.message);
          }
        } else {
             console.warn("User not logged in, saving locally only.");
        }
      } catch (err: any) {
        console.error("Create Exception:", err);
      }
    }

    // Salva Localmente Sempre e espera a transação completar
    await saveLocalRecord(newRecord);

    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let updatedRecord: DailyRecord | null = null;

    const localRecords = await getAllLocalRecords();
    const existing = localRecords.find(r => r.id === id);

    if (existing) {
        updatedRecord = { ...existing, ...updates, _isSynced: false };
    }

    if (supabase) {
        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                const cleanUpdates: any = { ...updates };
                delete cleanUpdates._isSynced;
                delete cleanUpdates.id;

                if (cleanUpdates.attachments && cleanUpdates.attachments.some((a:string) => a.startsWith('data:'))) {
                    cleanUpdates.attachments = await this.processAttachmentsForSync(cleanUpdates.attachments);
                    if (updatedRecord) updatedRecord.attachments = cleanUpdates.attachments;
                }

                ['km_start', 'km_end', 'km_total', 'articles_loaded', 
                 'articles_delivered', 'articles_not_delivered', 
                 'fuel_amount', 'toll_amount', 'scraps_collected'].forEach(key => {
                    if (cleanUpdates[key] !== undefined) {
                        cleanUpdates[key] = safeFloat(cleanUpdates[key]);
                    }
                });

                const { error } = await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
                if (!error && updatedRecord) {
                    updatedRecord._isSynced = true;
                }
            }
        } catch (e) {
            console.error("Update DB Error:", e);
        }
    }

    if (updatedRecord) {
        await saveLocalRecord(updatedRecord);
    }

    return updatedRecord;
  },

  // HARD DELETE ÚNICO (Mantido para compatibilidade, mas redireciona para múltiplo para consistência)
  async delete(id: string): Promise<void> {
    return this.deleteMultiple([id]);
  },

  // --- OTIMIZAÇÃO: HARD DELETE EM LOTE ---
  async deleteMultiple(ids: string[]): Promise<void> {
    if (!ids || ids.length === 0) return;

    console.log(`Iniciando exclusão em lote de ${ids.length} registros...`);

    // 1. Identificar todas as imagens que precisam ser apagadas
    // Precisamos dos dados originais para saber os URLs
    let allImagesToDelete: string[] = [];

    // Tenta pegar do cache local para ser rápido
    const localRecords = await getAllLocalRecords();

    for (const id of ids) {
        const record = localRecords.find(r => r.id === id);
        if (record && record.attachments && record.attachments.length > 0) {
            record.attachments.forEach(url => {
                 if (url.includes(BUCKET_NAME)) {
                    const fileName = url.split(`${BUCKET_NAME}/`).pop();
                    if (fileName) allImagesToDelete.push(fileName);
                 }
            });
        }
    }

    if (supabase) {
        try {
            // A. Batch Delete Images (Uma única requisição para N imagens)
            if (allImagesToDelete.length > 0) {
                console.log(`Removendo ${allImagesToDelete.length} imagens do storage (Batch)...`);
                // Supabase permite deletar array de arquivos
                const { error: storageError } = await supabase.storage
                    .from(BUCKET_NAME)
                    .remove(allImagesToDelete);

                if (storageError) console.error("Erro Batch Storage:", storageError);
            }

            // B. Batch Delete Records no DB (Uma única query 'in')
            const { error: dbError } = await supabase
                .from('daily_records')
                .delete()
                .in('id', ids); // WHERE id IN (1, 2, 3...)

            if (dbError) throw dbError;

        } catch (e) {
            console.error("Erro ao deletar lote do servidor:", e);
        }
    }

    // 2. Apagar Localmente (Cache) - Loop é rápido localmente
    for (const id of ids) {
        await deleteLocalRecord(id);
    }

    console.log("Exclusão em lote concluída.");
  },

  async getById(id: string): Promise<DailyRecord | undefined> {
    // Tenta cache local primeiro para velocidade
    const localRecords = await getAllLocalRecords();
    const local = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (data) {
                const record = { ...data, _isSynced: true } as DailyRecord;
                await saveLocalRecord(record);
                return record;
            }
        } catch (e) {}
    }

    return local;
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Archive, RefreshCcw, FolderOpen, AlertCircle, User, Truck, Package, Cloud, WifiOff, RefreshCw, ChevronRight, Trash2, CheckSquare, Square, X } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';
import { useRecords } from '../contexts/RecordContext';

interface RecordListProps {
  viewMode?: 'active' | 'archived';
}

const RecordList: React.FC<RecordListProps> = ({ viewMode = 'active' }) => {
  const navigate = useNavigate();
  const { records, loading, refreshRecords } = useRecords();
  const [filteredRecords, setFilteredRecords] = useState<DailyRecord[]>([]);
  const [filterTeam, setFilterTeam] = useState('');
  const [syncing, setSyncing] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Estados para Seleção Múltipla
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const handleManualSync = async () => {
    setSyncing(true);
    setErrorMsg('');
    try {
        // Primeiro envia os pendentes
        const uploaded = await recordService.syncPendingRecords();
        // Depois força o download de tudo do servidor
        await refreshRecords(); 

        if (uploaded > 0) {
           // Opcional: Feedback visual de sucesso
        }
    } catch (e: any) {
        console.error("Sync error", e);
        setErrorMsg("Erro de conexão. Verifique sua internet.");
    } finally {
        setSyncing(false);
    }
  };

  useEffect(() => {
    // Sai do modo de seleção se mudar de aba
    setIsSelectionMode(false);
    setSelectedIds(new Set());

    let result = records.filter(r => {
        const isArchived = !!r.archived;
        if (viewMode === 'archived') {
            return isArchived === true;
        } else {
            return isArchived === false;
        }
    });

    if (filterTeam) {
      result = result.filter(r => r.team.toLowerCase().includes(filterTeam.toLowerCase()));
    }
    setFilteredRecords(result);
  }, [filterTeam, records, viewMode]);

  const handleToggleArchive = async (e: React.MouseEvent, record: DailyRecord) => {
    e.preventDefault(); 
    e.stopPropagation(); 
    setErrorMsg('');
    const willArchive = !record.archived;

    try {
        await recordService.update(record.id, { archived: willArchive });
        await refreshRecords();
    } catch (error: any) {
        setErrorMsg(`Falha ao atualizar: ${error?.message || 'Erro desconhecido'}`);
    }
  };

  const handleDeleteRecord = async (e: React.MouseEvent, recordId: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (window.confirm("ATENÇÃO: Isso apagará PERMANENTEMENTE o registro e todas as fotos associadas. Não há como desfazer.\n\nTem certeza?")) {
        try {
            await recordService.delete(recordId);
            await refreshRecords();
        } catch (error: any) {
            alert("Erro ao excluir: " + error.message);
        }
    }
  };

  // --- LÓGICA DE SELEÇÃO EM LOTE ---

  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set());
  };

  const toggleSelectRecord = (id: string) => {
    const newSelection = new Set(selectedIds);
    if (newSelection.has(id)) {
        newSelection.delete(id);
    } else {
        newSelection.add(id);
    }
    setSelectedIds(newSelection);
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === filteredRecords.length) {
        setSelectedIds(new Set());
    } else {
        const allIds = new Set(filteredRecords.map(r => r.id));
        setSelectedIds(allIds);
    }
  };

  const handleBulkDelete = async () => {
