  const [filterTeam, setFilterTeam] = useState('');
  const [syncing, setSyncing] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Estados para Seleção Múltipla
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const handleManualSync = async () => {
    setSyncing(true);
    setErrorMsg('');
    try {
        // 1. Tenta enviar pendentes
        const pendingCount = await recordService.syncPendingRecords();

        // 2. Diagnóstico de Conexão com Servidor (Bypass Cache para teste)
        let serverCount = 0;
        let serverError = null;
        if (supabase) {
            const { count, error } = await supabase
                .from('daily_records')
                .select('*', { count: 'exact', head: true });

            serverCount = count || 0;
            serverError = error;
        }

        // 3. Atualiza a UI
        await refreshRecords(); 

        let msg = `Sincronização concluída!\n\n`;
        msg += `⬆️ Enviados: ${pendingCount}\n`;
        msg += `☁️ Total na Nuvem: ${serverCount}\n`;

        if (serverCount === 0 && !serverError) {
             msg += `\n⚠️ ATENÇÃO: A nuvem retornou 0 registros. Se houver dados lá, verifique as "Policies" (RLS) no Supabase.`;
        } else if (serverError) {
             msg += `\n❌ Erro na Nuvem: ${serverError.message}`;
        } else {
             msg += `✅ Conexão OK.`;
        }

        alert(msg);

    } catch (e: any) {
        console.error("Sync error", e);
        setErrorMsg("Erro de conexão. Verifique sua internet.");
    } finally {
        setSyncing(false);
    }
  };

