// --- ATENÇÃO: SUBSTITUA ESTAS CHAVES PELAS DO SEU NOVO PROJETO SUPABASE ---
// O projeto antigo estourou a cota (Egress 290%). Crie um novo em database.new
const supabaseUrl = 'COLOQUE_SUA_NOVA_URL_AQUI'; // Ex: https://xyz.supabase.co
const supabaseAnonKey = 'COLOQUE_SUA_NOVA_KEY_AQUI'; // Ex: eyJhbGciOiJIUzI1Ni...

// Timeout customizado para evitar loading infinito quando a cota excede
// Se o Supabase não responder em 3s, cancelamos a requisição.
const customFetch = (url: RequestInfo | URL, options: RequestInit = {}) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 3000); // 3 segundos max

  return fetch(url, { ...options, signal: controller.signal })
    .then((response) => {
      clearTimeout(timeoutId);
      return response;
    })
    .catch((error) => {
      clearTimeout(timeoutId);
      // Se for timeout, lança erro específico que o App.tsx trata
      throw error;
    });
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  },
  global: {
    fetch: customFetch, // Injeta o fetch com timeout
  }
});

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Archive, RefreshCcw, FolderOpen, AlertCircle, User, Truck, Package, Cloud, WifiOff, RefreshCw, ChevronRight, Trash2, CheckSquare, Square, X } from 'lucide-react';
import { DailyRecord } from '../types';
import { recordService } from '../services/recordService';
import { useRecords } from '../contexts/RecordContext';
import { supabase } from '../services/supabaseClient';

interface RecordListProps {
  viewMode?: 'active' | 'archived';
}

const RecordList: React.FC<RecordListProps> = ({ viewMode = 'active' }) => {
  const navigate = useNavigate();
  const { records, loading, refreshRecords } = useRecords();
  const [filteredRecords, setFilteredRecords] = useState<DailyRecord[]>([]);
  const [filterTeam, setFilterTeam] = useState('');
  const [syncing, setSyncing] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Estados para Seleção Múltipla
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const handleManualSync = async () => {
    setSyncing(true);
    setErrorMsg('');
    try {
        // 1. Tenta enviar pendentes
        const pendingCount = await recordService.syncPendingRecords();

        // 2. Diagnóstico de Conexão com Servidor
        let serverCount = 0;
        let serverError = null;

        if (supabase) {
            // Tenta uma query leve apenas para testar a conexão
            const { count, error } = await supabase
                .from('daily_records')
                .select('*', { count: 'exact', head: true });

            serverCount = count || 0;
            serverError = error;
        }

        // 3. Atualiza a UI
        await refreshRecords(); 

        let msg = `Sincronização concluída!\n\n`;
        msg += `⬆️ Enviados: ${pendingCount}\n`;

        if (serverError) {
             console.error("Erro Supabase:", serverError);
             msg += `\n❌ Erro na Nuvem: O servidor recusou a conexão. Verifique se a cota do Supabase foi excedida.`;
             setErrorMsg("Falha na conexão com a nuvem (Cota ou Internet).");
        } else {
