import { supabase } from './supabaseClient';
import { DailyRecord } from '../types';

const DB_NAME = 'SNavegarDB';
const DB_VERSION = 1;
const STORE_NAME = 'daily_records';
const BUCKET_NAME = 'app-images';
const OLD_STORAGE_KEY = 'snavegar_records'; // Para migração

// --- INDEXED DB HELPERS (O "Armazém Gigante") ---

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => reject("Erro ao abrir banco de dados local");

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = (event) => {
      resolve((event.target as IDBOpenDBRequest).result);
    };
  });
};

const saveLocalRecord = async (record: DailyRecord) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put(record); 
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro na transação de salvamento local");
    request.onerror = () => reject("Erro na requisição de salvamento local");
  });
};

const deleteLocalRecord = async (id: string) => {
  const db = await openDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.delete(id);
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject("Erro ao apagar registro local");
  });
};

const getAllLocalRecords = async (): Promise<DailyRecord[]> => {
  const db = await openDB();
  return new Promise<DailyRecord[]>((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => {
        const records = request.result as DailyRecord[];
        resolve(records || []);
    };
    request.onerror = () => reject("Erro ao ler registros locais");
  });
};

const migrateLegacyData = async () => {
  const legacyData = localStorage.getItem(OLD_STORAGE_KEY);
  if (legacyData) {
    try {
      console.log("Iniciando migração de armazenamento...");
      const parsedData: DailyRecord[] = JSON.parse(legacyData);
      const db = await openDB();
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      parsedData.forEach(record => store.put(record));
      transaction.oncomplete = () => {
        console.log("Migração concluída com sucesso!");
        localStorage.removeItem(OLD_STORAGE_KEY);
      };
    } catch (e) {
      console.error("Erro na migração de dados:", e);
    }
  }
};

// --- HELPERS GERAIS ---

const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const safeFloat = (val: any): number => {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return val;
  const str = String(val).replace(',', '.').trim();
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

const preparePayload = (record: DailyRecord, userId: string, userEmail?: string) => {
  return {
    id: record.id,
    user_id: userId,
    created_by_email: userEmail || record.created_by_email,
    date: record.date,
    team: record.team || 'Equipe Indefinida',
    van_plate: record.van_plate || '',
    start_time: record.start_time || '00:00',
    km_start: safeFloat(record.km_start),
    km_end: safeFloat(record.km_end),
    km_total: safeFloat(record.km_total),
    articles_loaded: safeFloat(record.articles_loaded),
    articles_delivered: safeFloat(record.articles_delivered),
    articles_not_delivered: safeFloat(record.articles_not_delivered),
    reason_not_delivered: record.reason_not_delivered || '',
    scraps_collected: safeFloat(record.scraps_collected),
    scrap_client_names: record.scrap_client_names || '',
    fueling: !!record.fueling,
    fuel_amount: safeFloat(record.fuel_amount),
    toll_amount: safeFloat(record.toll_amount),
    attachments: record.attachments || [],
    notes: record.notes || '',
    status: record.status || 'draft',
    archived: !!record.archived,
    created_at: record.created_at || new Date().toISOString()
  };
};

// --- SERVICE ---

export const recordService = {
  async uploadImage(file: Blob): Promise<string | null> {
    if (!supabase) return null;
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.jpg`;
      const { data, error } = await supabase.storage.from(BUCKET_NAME).upload(fileName, file, { 
        cacheControl: '3600', 
        upsert: false 
      });
      if (error) {
        console.error("Upload Error:", error);
        return null;
      }
      const { data: publicUrlData } = supabase.storage.from(BUCKET_NAME).getPublicUrl(data.path);
      return publicUrlData.publicUrl;
    } catch (err) { 
        console.error("Upload Exception:", err);
        return null; 
    }
  },

  async processAttachmentsForSync(attachments: string[]): Promise<string[]> {
    if (!attachments || !attachments.length) return [];

    const hasBase64 = attachments.some(a => a.startsWith('data:'));
    if (!hasBase64) return attachments;

    const processed = await Promise.all(attachments.map(async (att) => {
      if (att.startsWith('data:')) {
        try {
            const res = await fetch(att);
            const blob = await res.blob();
            const url = await this.uploadImage(blob);
            return url || att; 
        } catch (e) {
            console.error("Falha ao processar imagem para sync:", e);
            return att;
        }
      }
      return att;
    }));
    return processed;
  },

  async syncPendingRecords(): Promise<number> {
    if (!supabase) return 0;

    await migrateLegacyData();

    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) return 0;

    const user = session.user;
    const localRecords = await getAllLocalRecords();
    const pending = localRecords.filter(r => r._isSynced === false);

    if (pending.length === 0) return 0;

    console.log(`Tentando sincronizar ${pending.length} registros...`);
    let syncedCount = 0;

    for (const record of pending) {
        try {
            if (record.attachments && record.attachments.length > 0) {
                const updatedAttachments = await this.processAttachmentsForSync(record.attachments);
                record.attachments = updatedAttachments;
            }

            const payload = preparePayload(record, user.id, user.email);
            const { error } = await supabase.from('daily_records').upsert(payload);

            if (!error) {
                const syncedRecord = { ...record, _isSynced: true };
                await saveLocalRecord(syncedRecord);
                syncedCount++;
            } else {
                console.error("Sync Error Individual:", error.message);
            }
        } catch (err) {
            console.error("Sync Exception:", err);
        }
    }

    return syncedCount;
  },

  async getAll(): Promise<DailyRecord[]> {
    await migrateLegacyData();

    let serverRecords: DailyRecord[] = [];
    let isOffline = false;

    if (supabase) {
      try {
        const { data: sessionData } = await supabase.auth.getSession();

        if (!sessionData.session) {
             console.warn("Sem sessão ativa.");
             isOffline = true;
        } else {
            // --- OTIMIZAÇÃO DE BANDA (EGRESS) ---
            // Buscamos apenas os dados essenciais para a lista.
            // Ignoramos 'attachments' e 'notes' pesados nesta query inicial.
            // O '*' foi substituído por uma lista explícita de colunas leves.
            const { data, error } = await supabase
                .from('daily_records')
                .select(`
                    id, 
                    date, 
                    team, 
                    van_plate, 
                    created_by_email,
                    km_total, 
                    articles_delivered, 
                    articles_not_delivered, 
                    archived,
                    scraps_collected,
                    _isSynced: id
                `) // O truque '_isSynced: id' apenas garante que retornamos algo para mapear depois
                .order('date', { ascending: false })
                .limit(100); 

            if (error) {
                console.warn("Supabase GET Error:", error.message);
                isOffline = true;
            } else if (data) {
                console.log(`Baixados ${data.length} resumos (Modo Econômico).`);
                serverRecords = data.map(r => ({ ...r, _isSynced: true })) as unknown as DailyRecord[];
            }
        }
      } catch (err) {
        console.error("Exceção na busca do servidor:", err);
        isOffline = true;
      }
    }

    // Busca Local (IndexedDB tem os dados completos, incluindo fotos cacheadas)
    const localRecords = await getAllLocalRecords();

    // Merge Inteligente
    const finalMap = new Map<string, DailyRecord>();

    // 1. Prioriza dados locais se existirem (pois podem ter fotos cacheadas)
    localRecords.forEach(r => finalMap.set(r.id, r));

    // 2. Atualiza/Adiciona dados do servidor
    if (!isOffline && serverRecords.length > 0) {
        for (const serverRecord of serverRecords) {
           const localMatch = finalMap.get(serverRecord.id);

           if (localMatch) {
               // Se já temos localmente, mantemos a versão local se ela tiver attachments (fotos)
               // e a do servidor não tiver (por causa da nossa otimização acima).
               // Mas atualizamos status e textos.
               const merged = { ...localMatch, ...serverRecord, attachments: localMatch.attachments || [] };
               finalMap.set(serverRecord.id, merged);
           } else {
               // Se é novo do servidor, adicionamos
               finalMap.set(serverRecord.id, serverRecord);
               // Salva no cache para uso futuro
               saveLocalRecord(serverRecord).catch(e => console.warn(e));
           }
        }
    }

    const merged = Array.from(finalMap.values())
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return merged;
  },

  async create(record: Omit<DailyRecord, 'id' | 'created_at' | 'archived'>): Promise<DailyRecord> {
    const newId = generateUUID();
    const newRecord = {
      ...record,
      id: newId,
      archived: false,
      created_at: new Date().toISOString(),
      _isSynced: false
    } as DailyRecord;

    if (supabase) {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          if (newRecord.attachments && newRecord.attachments.some(a => a.startsWith('data:'))) {
             newRecord.attachments = await this.processAttachmentsForSync(newRecord.attachments);
          }
          const payload = preparePayload(newRecord, session.user.id, session.user.email);
          const { error } = await supabase.from('daily_records').insert(payload);
          if (!error) newRecord._isSynced = true;
        }
      } catch (err: any) {
        console.error("Create Exception:", err);
      }
    }
    await saveLocalRecord(newRecord);
    return newRecord;
  },

  async update(id: string, updates: Partial<DailyRecord>): Promise<DailyRecord | null> {
    let updatedRecord: DailyRecord | null = null;
    const localRecords = await getAllLocalRecords();
    const existing = localRecords.find(r => r.id === id);

    if (existing) {
        updatedRecord = { ...existing, ...updates, _isSynced: false };
    }

    if (supabase) {
        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                const cleanUpdates: any = { ...updates };
                delete cleanUpdates._isSynced;
                delete cleanUpdates.id;

                if (cleanUpdates.attachments && cleanUpdates.attachments.some((a:string) => a.startsWith('data:'))) {
                    cleanUpdates.attachments = await this.processAttachmentsForSync(cleanUpdates.attachments);
                    if (updatedRecord) updatedRecord.attachments = cleanUpdates.attachments;
                }

                // Sanitização numérica
                ['km_start', 'km_end', 'km_total', 'articles_loaded', 
                 'articles_delivered', 'articles_not_delivered', 
                 'fuel_amount', 'toll_amount', 'scraps_collected'].forEach(key => {
                    if (cleanUpdates[key] !== undefined) cleanUpdates[key] = safeFloat(cleanUpdates[key]);
                });

                const { error } = await supabase.from('daily_records').update(cleanUpdates).eq('id', id);
                if (!error && updatedRecord) updatedRecord._isSynced = true;
            }
        } catch (e) { console.error(e); }
    }

    if (updatedRecord) await saveLocalRecord(updatedRecord);
    return updatedRecord;
  },

  async delete(id: string): Promise<void> {
    return this.deleteMultiple([id]);
  },

  async deleteMultiple(ids: string[]): Promise<void> {
    if (!ids || ids.length === 0) return;
    let allImagesToDelete: string[] = [];
    const localRecords = await getAllLocalRecords();

    for (const id of ids) {
        const record = localRecords.find(r => r.id === id);
        if (record?.attachments?.length) {
            record.attachments.forEach(url => {
                 if (url.includes(BUCKET_NAME)) {
                    const fileName = url.split(`${BUCKET_NAME}/`).pop();
                    if (fileName) allImagesToDelete.push(fileName);
                 }
            });
        }
    }

    if (supabase) {
        try {
            if (allImagesToDelete.length > 0) {
                await supabase.storage.from(BUCKET_NAME).remove(allImagesToDelete);
            }
            await supabase.from('daily_records').delete().in('id', ids);
        } catch (e) { console.error(e); }
    }
    for (const id of ids) await deleteLocalRecord(id);
  },

  // --- OTIMIZAÇÃO DE DETALHES ---
  // Quando abrimos um detalhe, aí sim buscamos TUDO do servidor se não tivermos local
  async getById(id: string): Promise<DailyRecord | undefined> {
    const localRecords = await getAllLocalRecords();
    let local = localRecords.find(r => r.id === id);

    if (supabase) {
        try {
            // Busca completa (SELECT *) apenas aqui
            const { data } = await supabase.from('daily_records').select('*').eq('id', id).single();
            if (data) {
                const record = { ...data, _isSynced: true } as DailyRecord;
                await saveLocalRecord(record);
                return record;
            }
        } catch (e) {}
    }
    return local;
  }
};

import { createClient } from '@supabase/supabase-js';

// --- ATENÇÃO: SUBSTITUA ESTAS CHAVES PELAS DO SEU NOVO PROJETO SUPABASE ---
// Se você ainda não criou o projeto, o app funcionará em modo OFFLINE (sem sincronização).
const supabaseUrl = 'COLOQUE_SUA_NOVA_URL_AQUI'; // Ex: https://xyz.supabase.co
const supabaseAnonKey = 'COLOQUE_SUA_NOVA_KEY_AQUI'; // Ex: eyJhbGciOiJIUzI1Ni...

// Validação de segurança: Verifica se a URL é válida antes de tentar conectar
// Isso evita o erro "Invalid supabaseUrl" que trava o app
const isUrlValid = (url: string) => {
  return url && url.startsWith('http') && !url.includes('COLOQUE_SUA_NOVA_URL');
};

// Timeout customizado para evitar loading infinito
const customFetch = (url: RequestInfo | URL, options: RequestInit = {}) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 3000); // 3 segundos max

  return fetch(url, { ...options, signal: controller.signal })
    .then((response) => {
      clearTimeout(timeoutId);
      return response;
    })
    .catch((error) => {
      clearTimeout(timeoutId);
      throw error;
    });
};

// Se a URL for inválida (ainda for o placeholder), exportamos NULL.
// O resto do app sabe lidar com 'supabase' sendo null (modo offline forçado).
export const supabase = isUrlValid(supabaseUrl)
  ? createClient(supabaseUrl, supabaseAnonKey, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
      },
      global: {
        fetch: customFetch, 
      }
    })
  : null;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Login from './pages/Login';
import Home from './pages/Home';
import RecordForm from './pages/RecordForm';
import RecordList from './pages/RecordList';
import RecordDetail from './pages/RecordDetail';
import Analytics from './pages/Analytics';
import { supabase } from './services/supabaseClient';
import { RecordProvider } from './contexts/RecordContext';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const initApp = async () => {
      console.log("🚀 Iniciando App com verificação de segurança...");

      // Promessa de Timeout: Rejeita se demorar mais de 2s
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error('TIMEOUT_SUPABASE')), 2000)
      );

      try {
        if (!supabase) {
            console.warn("Supabase não configurado (URL inválida). Modo Offline ativo.");
            throw new Error("Supabase não inicializado");
        }

        // Corrida: Quem responder primeiro ganha (O banco ou o relógio)
        const { data } = await Promise.race([
          supabase.auth.getSession(),
          timeoutPromise
        ]) as any;

        if (data?.session) {
          console.log("✅ Sessão válida encontrada.");
          setIsAuthenticated(true);
        } else {
          console.log("ℹ️ Nenhuma sessão ativa.");
          setIsAuthenticated(false);
        }
      } catch (error: any) {
        console.warn("⚠️ Modo Offline:", error.message || error);
        setIsAuthenticated(false);
      } finally {
        // GARANTIA ABSOLUTA QUE O LOADING VAI SUMIR
        setLoading(false);
      }
    };

    initApp();

    // Listener de Auth (apenas se o supabase estiver configurado)
    let authListener: any = null;
    if (supabase) {
        const { data } = supabase.auth.onAuthStateChange((event, session) => {
            if (event === 'SIGNED_IN' && session) setIsAuthenticated(true);
            if (event === 'SIGNED_OUT') setIsAuthenticated(false);
        });
        authListener = data;
    }

    return () => {
      if (authListener) authListener.subscription.unsubscribe();
    };
  }, []);

  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  const handleLogout = async () => {
    try {
        if (supabase) await supabase.auth.signOut();
    } catch (e) {
        console.error("Erro ao sair (possível offline):", e);
    }
    setIsAuthenticated(false);
  };

  if (loading) {
      return (
        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 text-primary">
            <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
            <span className="font-semibold text-sm tracking-wide text-gray-600">Conectando...</span>
            <p className="text-xs text-gray-400 mt-2">Se demorar, entraremos em modo offline.</p>
        </div>
      );
  }

  return (
    <HashRouter>
      <RecordProvider>
        <Routes>
          <Route 
            path="/login" 
            element={!isAuthenticated ? <Login onLogin={handleLogin} /> : <Navigate to="/" />} 
          />

          <Route
            path="/*"
            element={
              isAuthenticated ? (
                <Layout onLogout={handleLogout}>
                  <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/create" element={<RecordForm />} />
                    <Route path="/records" element={<RecordList viewMode="active" />} />
                    <Route path="/archived" element={<RecordList viewMode="archived" />} />
                    <Route path="/records/:id" element={<RecordDetail />} />
                    <Route path="/records/:id/edit" element={<RecordForm />} />
                    <Route path="/analytics" element={<Analytics />} />
                    <Route path="*" element={<Navigate to="/" />} />
                  </Routes>
                </Layout>
              ) : (
                <Navigate to="/login" />
              )
            }
          />
        </Routes>
      </RecordProvider>
    </HashRouter>
  );
};

export default App;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Truck, Loader2, AlertCircle, WifiOff } from 'lucide-react';
import { supabase } from '../services/supabaseClient';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();

    // --- CORREÇÃO DE EMERGÊNCIA: MODO OFFLINE ---
    // Se o Supabase não estiver configurado (URL inválida ou nula), permitimos entrar offline.
    if (!supabase) {
        const confirmOffline = window.confirm(
            "⚠️ MODO OFFLINE DETECTADO\n\n" +
            "O banco de dados não está conectado. Você pode entrar, mas os dados serão salvos APENAS no seu celular.\n\n" +
            "Deseja entrar no Modo Offline?"
        );

        if (confirmOffline) {
            onLogin(); // Autoriza o app
            navigate('/');
        } else {
            setError("Configure o arquivo services/supabaseClient.ts para conectar na nuvem.");
        }
        return;
    }

    setLoading(true);
    setError('');
    setMessage('');

    try {
      if (isSignUp) {
        // Sign Up Logic
        const { data, error } = await supabase.auth.signUp({
          email,
          password,
        });

        if (error) throw error;

        if (data.session) {
            onLogin();
            navigate('/');
        } else {
            setMessage('Conta criada! Verifique seu e-mail para confirmar.');
            setIsSignUp(false);
            setError('Aviso: Para pular a confirmação, desative "Confirm email" no painel do Supabase.');
        }
      } else {
        // Login Logic
        const { error } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (error) throw error;
        onLogin();
        navigate('/');
      }
    } catch (err: any) {
      if (err.message.includes("Email not confirmed")) {
          setError("E-mail não confirmado. Verifique sua caixa de entrada.");
      } else {
          setError(err.message || 'Falha na autenticação');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-sm animate-fade-in">
        <div className="flex flex-col items-center mb-8">
          <div className="bg-blue-100 p-4 rounded-full mb-4 text-primary">
            <Truck size={40} />
          </div>
          <h1 className="text-2xl font-bold text-gray-900">SNavegar</h1>
          <p className="text-gray-500 text-sm mt-1">Operações Diárias de Entrega</p>
        </div>

        {/* Aviso visual se estiver sem configuração */}
        {!supabase && (
            <div className="mb-6 bg-orange-50 border border-orange-200 rounded-lg p-3 text-sm text-orange-800 flex items-start space-x-2">
                <WifiOff className="shrink-0 mt-0.5" size={16} />
                <div>
                    <strong>Aviso de Configuração:</strong>
                    <p className="text-xs mt-1 opacity-90">O banco de dados não foi detectado. Você poderá entrar em <b>Modo Offline</b>.</p>
                </div>
            </div>
        )}

        <form onSubmit={handleAuth} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">E-mail</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all bg-white text-gray-900"
              placeholder="equipe@snavegar.com"
              required={!!supabase} // Só é obrigatório se tiver banco
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Senha</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all bg-white text-gray-900"
              placeholder="••••••••"
              required={!!supabase}
            />
          </div>

          {error && (
            <div className="text-red-600 text-sm bg-red-50 p-3 rounded-lg flex items-start space-x-2">
                <AlertCircle size={16} className="shrink-0 mt-0.5" />
                <span>{error}</span>
            </div>
          )}

          {message && (
             <div className="text-green-600 text-sm text-center bg-green-50 p-3 rounded-lg">
                {message}
             </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full py-3 rounded-lg font-semibold shadow-md transition-colors flex items-center justify-center ${
                !supabase 
                ? 'bg-orange-500 hover:bg-orange-600 text-white' 
                : 'bg-primary hover:bg-blue-700 text-white'
            }`}
          >
            {loading ? <Loader2 className="animate-spin" /> : (!supabase ? 'Entrar Offline' : (isSignUp ? 'Criar Conta' : 'Entrar'))}
          </button>
        </form>

        {supabase && (
            <div className="mt-6 text-center">
                <button 
                    onClick={() => { setIsSignUp(!isSignUp); setError(''); setMessage(''); }}
                    className="text-sm text-primary hover:underline"
                >
                    {isSignUp ? 'Já tem conta? Entrar' : 'Precisa de uma conta? Cadastre-se'}
                </button>
            </div>
        )}

        <p className="text-center text-xs text-gray-400 mt-6">
          © {new Date().getFullYear()} SNavegar Operações
        </p>
      </div>
      <style>{`
        .animate-fade-in {
            animation: fadeIn 0.5s ease-out;
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

