          }));
        } else {
            // Fallback para Base64 em modo offline
            const reader = new FileReader();
            reader.readAsDataURL(compressedFile);
            reader.onloadend = () => {
                 setFormData(prev => ({
                    ...prev,
                    attachments: [...(prev.attachments || []), reader.result as string]
                  }));
