  const handleDeleteRecord = async (e: React.MouseEvent, recordId: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (window.confirm("ATENÇÃO: Isso apagará PERMANENTEMENTE o registro e todas as fotos associadas. Não há como desfazer.\n\nTem certeza?")) {
