                            {syncing ? 'Sincronizando dados...' : `${pendingCount} registros aguardando envio`}
                        </h3>
                        <p className="text-orange-700 text-sm mt-1">
                            {syncing 
                                ? 'Enviando fotos e dados para o servidor. Não feche o app.' 
                                : 'Conecte-se ao Wi-Fi e clique no botão de atualizar para salvar na nuvem.'}
                        </p>
                    </div>
                </div>
                {!syncing && (
                    <button 
                        onClick={() => handleManualSync(false)}
                        className="bg-orange-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md hover:bg-orange-700 transition-colors"
                    >
                        Enviar Agora
                    </button>
                )}
            </div>
          </div>
      )}

      {syncSuccessMsg && (
        <div className="bg-green-100 border border-green-200 text-green-800 px-4 py-3 rounded-lg mb-4 flex items-center shadow-sm animate-fade-in">
